-- =====================================================================
-- Clinic Signage v2.33.0 · Canonical full schema
-- 신규 빈 DB 전용 canonical 기준본. 기존 운영 DB에는 버전별 마이그레이션만 실행하세요.
-- 영상 파일 자체는 Supabase Storage에 저장하지 않는다.
-- =====================================================================

create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;

create table if not exists public.members (
  user_id uuid primary key references auth.users(id) on delete cascade,
  role text not null default 'staff' check (role in ('admin','staff')),
  created_at timestamptz not null default now()
);
-- v2.5부터 members/Supabase 이메일 로그인은 사용하지 않는다. 기존 데이터는 호환을 위해 보존한다.

create table if not exists public.pin_accounts (
  id bigint generated by default as identity primary key,
  role text not null check (role in ('admin','staff')),
  pin_hash text not null,
  enabled boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table if not exists public.pin_sessions (
  id uuid primary key default gen_random_uuid(),
  account_id bigint not null references public.pin_accounts(id) on delete cascade,
  token_hash bytea not null unique,
  expires_at timestamptz not null,
  created_at timestamptz not null default now()
);
create index if not exists pin_sessions_expiry_idx on public.pin_sessions(expires_at);

create table if not exists public.pin_login_throttle (
  client_id text primary key,
  failed_count int not null default 0,
  locked_until timestamptz,
  updated_at timestamptz not null default now()
);

create or replace function public.pin_request_token()
returns text language sql stable security definer set search_path=public as $$
  select nullif((coalesce(nullif(current_setting('request.headers',true),''),'{}')::jsonb ->> 'x-signage-session'),'');
$$;

create or replace function public.pin_session_role()
returns text language sql stable security definer set search_path=public,extensions as $$
  select a.role
  from public.pin_sessions s
  join public.pin_accounts a on a.id=s.account_id and a.enabled
  where s.token_hash=digest(coalesce(public.pin_request_token(),''),'sha256')
    and s.expires_at>clock_timestamp()
  limit 1;
$$;

create or replace function public.is_member()
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(public.pin_session_role() in ('admin', 'staff'), false);
$$;
create or replace function public.is_admin()
returns boolean language sql stable security definer set search_path = public as $$
  select coalesce(public.pin_session_role() = 'admin', false);
$$;

-- SQL Editor에서만 실행: select public.configure_signage_pins('관리자6자리','스텝4~6자리');

-- canonical: earlier duplicate configure_signage_pins removed; final definition appears below.



-- canonical: earlier duplicate pin_login removed; final definition appears below.


create or replace function public.pin_logout()
returns void language plpgsql security definer set search_path=public,extensions as $$
begin
  delete from public.pin_sessions where token_hash=digest(coalesce(public.pin_request_token(),''),'sha256');
end $$;

revoke all on function public.pin_request_token() from public,anon,authenticated;
revoke all on function public.pin_session_role() from public,anon,authenticated;
revoke all on function public.pin_logout() from public;
grant execute on function public.pin_logout() to anon,authenticated;

create table if not exists public.tags (
  name text primary key,
  sort_order int not null default 0,
  patient_context_note text,
  content_reason text,
  created_at timestamptz not null default now()
);
insert into public.tags(name,sort_order) values('기본',0) on conflict(name) do nothing;

create table if not exists public.videos (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  storage_path text unique,
  url text,
  size_bytes bigint,
  duration_sec numeric,
  tags text[] not null default '{}',
  sort_order int not null default 0,
  active boolean not null default true,
  created_at timestamptz not null default now()
);
alter table public.videos alter column storage_path drop not null;
alter table public.videos alter column url drop not null;
alter table public.videos add column if not exists source text;
alter table public.videos add column if not exists file_path text;
alter table public.videos add column if not exists available boolean not null default true;
alter table public.videos add column if not exists file_modified_at timestamptz;
alter table public.videos add column if not exists target_age text[] not null default '{}';
alter table public.videos add column if not exists target_gender text[] not null default '{}';
alter table public.videos add column if not exists target_treatment text[] not null default '{}';
update public.videos set source='legacy' where source is null and url is not null;
update public.videos set source='local' where source is null;
alter table public.videos alter column source set default 'r2';
alter table public.videos alter column source set not null;
-- v2.7 cloud migration: local media-server entries are kept for reference but disabled.
update public.videos set active=false, available=false where source='local';
create index if not exists videos_tags_idx on public.videos using gin(tags);
create index if not exists videos_target_age_idx on public.videos using gin(target_age);
create index if not exists videos_target_gender_idx on public.videos using gin(target_gender);
create index if not exists videos_target_treatment_idx on public.videos using gin(target_treatment);
create unique index if not exists videos_local_file_path_uidx on public.videos(file_path) where source='local' and file_path is not null;

create table if not exists public.rooms (
  id uuid primary key default gen_random_uuid(),
  name text not null,
  sort_order int not null default 0,
  player_key uuid not null unique default gen_random_uuid(),
  default_tags text[] not null default '{기본}',
  session_tags text[] not null default '{}',
  session_started_at timestamptz,
  session_timeout_min int not null default 60 check(session_timeout_min>=0),
  volume int not null default 80 check(volume between 0 and 100),
  paused boolean not null default false,
  overlay_text text,
  reload_nonce int not null default 0,
  last_seen_at timestamptz,
  player_status jsonb,
  map_x_pct numeric(5,2),
  map_y_pct numeric(5,2),
  created_at timestamptz not null default now()
);
alter table public.rooms add column if not exists session_age_group text;
alter table public.rooms add column if not exists session_gender text;
alter table public.rooms add column if not exists session_treatment text;

-- v2.6.2 canonical treatment rename: veneer -> minish.
-- Keep this idempotent so the full schema can be safely re-run on existing installs.
update public.videos
set target_treatment = coalesce((
  select array_agg(distinct case when x='veneer' then 'minish' else x end order by case when x='veneer' then 'minish' else x end)
  from unnest(target_treatment) as x
),'{}'::text[])
where 'veneer'=any(target_treatment);

update public.rooms
set session_treatment = case when session_treatment='veneer' then 'minish' else session_treatment end,
    session_tags = array_replace(coalesce(session_tags,'{}'::text[]),'veneer','minish')
where session_treatment='veneer' or 'veneer'=any(coalesce(session_tags,'{}'::text[]));
alter table public.rooms add column if not exists manual_active boolean not null default false;
alter table public.rooms add column if not exists manual_video_ids uuid[] not null default '{}';
alter table public.rooms add column if not exists manual_updated_at timestamptz;
alter table public.rooms add column if not exists heartbeat_rejected_count int not null default 0;
alter table public.rooms add column if not exists map_x_pct numeric(5,2);
alter table public.rooms add column if not exists map_y_pct numeric(5,2);
alter table public.rooms drop constraint if exists rooms_map_x_pct_check;
alter table public.rooms add constraint rooms_map_x_pct_check check(map_x_pct is null or map_x_pct between 0 and 100);
alter table public.rooms drop constraint if exists rooms_map_y_pct_check;
alter table public.rooms add constraint rooms_map_y_pct_check check(map_y_pct is null or map_y_pct between 0 and 100);
create index if not exists rooms_sort_idx on public.rooms(sort_order,created_at);
create index if not exists rooms_last_seen_idx on public.rooms(last_seen_at desc);

create table if not exists public.broadcast (
  id int primary key default 1 check(id=1),
  active boolean not null default false,
  video_ids uuid[] not null default '{}',
  notice_text text,
  updated_at timestamptz not null default now()
);
alter table public.broadcast add column if not exists effective_at timestamptz;
alter table public.broadcast add column if not exists revision bigint not null default 0;
insert into public.broadcast(id) values(1) on conflict(id) do nothing;

create table if not exists public.app_settings (
  id int primary key default 1 check(id=1),
  media_server_url text not null default '',
  emergency_video_id uuid,
  disk_warning_gb int not null default 20,
  updated_at timestamptz not null default now()
);
alter table public.app_settings add column if not exists emergency_video_id uuid;
alter table public.app_settings add column if not exists disk_warning_gb int not null default 20;
alter table public.app_settings add column if not exists site_name text not null default 'CLINIC SIGNAGE';
alter table public.app_settings add column if not exists building_label text not null default 'MAIN BUILDING';
alter table public.app_settings add column if not exists floorplan_assets jsonb not null default '{}'::jsonb;
insert into public.app_settings(id) values(1) on conflict(id) do nothing;
update public.app_settings set media_server_url='' where id=1;

-- RLS -------------------------------------------------------------------
alter table public.members enable row level security;
alter table public.pin_accounts enable row level security;
alter table public.pin_sessions enable row level security;
alter table public.pin_login_throttle enable row level security;
alter table public.tags enable row level security;
alter table public.videos enable row level security;
alter table public.rooms enable row level security;
alter table public.broadcast enable row level security;
alter table public.app_settings enable row level security;

-- PIN 인증 테이블은 직접 SELECT/UPDATE 정책을 만들지 않는다. SECURITY DEFINER RPC로만 접근한다.
drop policy if exists members_select on public.members;
drop policy if exists members_admin on public.members;

drop policy if exists tags_select on public.tags;
create policy tags_select on public.tags for select to anon,authenticated using(public.is_member());
drop policy if exists tags_admin on public.tags;
create policy tags_admin on public.tags for all to anon,authenticated using(public.is_admin()) with check(public.is_admin());

drop policy if exists videos_select on public.videos;
create policy videos_select on public.videos for select to anon,authenticated using(public.is_member());
drop policy if exists videos_admin on public.videos;
create policy videos_admin on public.videos for all to anon,authenticated using(public.is_admin()) with check(public.is_admin());

-- player_key는 bearer credential. 스텝에게 rooms 원본 SELECT를 주지 않는다.
drop policy if exists rooms_select on public.rooms;
drop policy if exists rooms_admin on public.rooms;
drop policy if exists rooms_admin_select on public.rooms;
-- canonical room admin policies are defined after site foundation.

drop policy if exists broadcast_select on public.broadcast;
create policy broadcast_select on public.broadcast for select to anon,authenticated using(public.is_member());
drop policy if exists broadcast_admin on public.broadcast;
create policy broadcast_admin on public.broadcast for update to anon,authenticated using(public.is_admin()) with check(public.is_admin());

drop policy if exists settings_select on public.app_settings;
create policy settings_select on public.app_settings for select to anon,authenticated using(public.is_member());
drop policy if exists settings_admin on public.app_settings;
create policy settings_admin on public.app_settings for update to anon,authenticated using(public.is_admin()) with check(public.is_admin());

-- PostgREST 테이블 권한은 넓게 부여하되 실제 행 접근은 위 RLS + PIN 세션으로 제한한다.
grant select,insert,update,delete on public.tags,public.videos,public.rooms,public.broadcast,public.app_settings to anon,authenticated;

-- 직원 RPC ---------------------------------------------------------------
-- v2.1 호환용 자유 태그 세션
create or replace function public.start_session(p_room uuid,p_tags text[])
returns void language plpgsql security definer set search_path=public as $$
begin
  if not public.is_member() then raise exception 'not allowed'; end if;
  update public.rooms set
    session_tags=coalesce(p_tags,'{}'),session_started_at=now(),
    session_age_group=null,session_gender=null,session_treatment=null
  where id=p_room;
end $$;

-- v2.2: 스텝은 대상(선택) + 진료유형(필수)만 지정
create or replace function public.start_patient_session(p_room uuid,p_age_group text,p_gender text,p_treatment text)
returns void language plpgsql security definer set search_path=public as $$
declare v_mode text;
begin
  if not public.is_member() then raise exception 'not allowed'; end if;
  if nullif(trim(coalesce(p_treatment,'')),'') is null then raise exception 'treatment required'; end if;
  select room_mode into v_mode from public.rooms where id=p_room;
  if v_mode not in ('treatment','consultation') then raise exception '이 공간에서는 환자 맞춤 송출을 사용하지 않습니다'; end if;
  update public.rooms set
    session_age_group=nullif(trim(coalesce(p_age_group,'')),''),
    session_gender=nullif(trim(coalesce(p_gender,'')),''),
    session_treatment=case when trim(p_treatment)='veneer' then 'minish' else trim(p_treatment) end,
    session_tags=array_remove(array[p_age_group,p_gender,case when trim(p_treatment)='veneer' then 'minish' else trim(p_treatment) end]::text[],null),
    session_started_at=clock_timestamp()
  where id=p_room;
end $$;

create or replace function public.end_session(p_room uuid)
returns void language plpgsql security definer set search_path=public as $$
begin
  if not public.is_member() then raise exception 'not allowed'; end if;
  update public.rooms set
    session_tags='{}',session_started_at=null,
    session_age_group=null,session_gender=null,session_treatment=null
  where id=p_room;
end $$;


-- 관리자 원자적 작업 -----------------------------------------------------
create or replace function public.send_refresh_all_rooms()
returns void language plpgsql security definer set search_path=public as $$
declare k uuid;
begin
  for k in select player_key from public.rooms loop
    perform realtime.send(jsonb_build_object('at',now()),'refresh','room:'||k::text,false);
  end loop;
end $$;
revoke all on function public.send_refresh_all_rooms() from public,anon,authenticated;


create or replace function public.admin_reorder_videos(p_ids uuid[])
returns void language plpgsql security definer set search_path=public as $$
declare i int;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  if p_ids is null then return; end if;
  for i in 1..coalesce(array_length(p_ids,1),0) loop update public.videos set sort_order=i*10 where id=p_ids[i]; end loop;
end $$;

create or replace function public.admin_reorder_rooms(p_ids uuid[])
returns void language plpgsql security definer set search_path=public as $$
declare i int;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  if p_ids is null then return; end if;
  for i in 1..coalesce(array_length(p_ids,1),0) loop update public.rooms set sort_order=i*10 where id=p_ids[i]; end loop;
end $$;

create or replace function public.admin_delete_tag(p_name text)
returns void language plpgsql security definer set search_path=public as $$
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  if p_name='기본' then raise exception '기본 태그는 삭제할 수 없습니다'; end if;
  update public.videos set tags=array_remove(tags,p_name) where p_name=any(tags);
  update public.rooms set default_tags=array_remove(default_tags,p_name) where p_name=any(default_tags);
  update public.rooms set session_tags=array_remove(session_tags,p_name) where p_name=any(session_tags);
  delete from public.tags where name=p_name;
end $$;

create or replace function public.admin_set_room_manual(p_room uuid,p_video_ids uuid[],p_active boolean)
returns void language plpgsql security definer set search_path=public as $$
begin
  perform public.admin_set_rooms_manual(array[p_room]::uuid[],p_video_ids,p_active);
end $$;

-- canonical admin_set_broadcast definition is declared later in this schema.


create or replace function public.admin_sync_local_videos(p_files jsonb)
returns void language plpgsql security definer set search_path=public as $$
declare v_max int;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  if jsonb_typeof(coalesce(p_files,'[]'::jsonb))<>'array' then raise exception 'invalid files'; end if;
  perform set_config('clinic_signage.suppress_refresh','on',true);

  with incoming as (
    select
      trim(both '/' from replace(coalesce(item->>'path',''),'\','/')) as file_path,
      case when coalesce(item->>'size','') ~ '^[0-9]+$' then (item->>'size')::bigint end as size_bytes,
      case when coalesce(item->>'modified_at','')<>'' then (item->>'modified_at')::timestamptz end as modified_at
    from jsonb_array_elements(coalesce(p_files,'[]'::jsonb)) item
  ), valid as (
    select distinct on (file_path) file_path,size_bytes,modified_at
    from incoming
    where file_path<>'' and file_path !~ '(^|/)\.\.(/|$)'
    order by file_path
  )
  update public.videos v set
    available=exists(select 1 from valid i where i.file_path=v.file_path),
    size_bytes=coalesce((select i.size_bytes from valid i where i.file_path=v.file_path),v.size_bytes),
    file_modified_at=coalesce((select i.modified_at from valid i where i.file_path=v.file_path),v.file_modified_at)
  where v.source='local';

  select coalesce(max(sort_order),0) into v_max from public.videos;
  with incoming as (
    select
      trim(both '/' from replace(coalesce(item->>'path',''),'\','/')) as file_path,
      case when coalesce(item->>'size','') ~ '^[0-9]+$' then (item->>'size')::bigint end as size_bytes,
      case when coalesce(item->>'modified_at','')<>'' then (item->>'modified_at')::timestamptz end as modified_at
    from jsonb_array_elements(coalesce(p_files,'[]'::jsonb)) item
  ), valid as (
    select distinct on (file_path) file_path,size_bytes,modified_at
    from incoming
    where file_path<>'' and file_path !~ '(^|/)\.\.(/|$)'
    order by file_path
  ), missing as (
    select i.*,row_number() over(order by i.file_path) rn
    from valid i
    where not exists(select 1 from public.videos v where v.source='local' and v.file_path=i.file_path)
  )
  insert into public.videos(title,source,file_path,size_bytes,file_modified_at,available,active,sort_order,tags,target_age,target_gender,target_treatment)
  select regexp_replace(regexp_replace(file_path,'^.*/',''),'\.[^.]+$',''),'local',file_path,size_bytes,modified_at,true,true,v_max+rn*10,'{}','{}','{}','{}'
  from missing;

  perform public.send_refresh_all_rooms();
end $$;

revoke all on function public.admin_reorder_videos(uuid[]) from public;
revoke all on function public.admin_reorder_rooms(uuid[]) from public;
revoke all on function public.admin_delete_tag(text) from public;
revoke all on function public.admin_set_room_manual(uuid,uuid[],boolean) from public;

revoke all on function public.admin_sync_local_videos(jsonb) from public;
grant execute on function public.admin_reorder_videos(uuid[]) to anon,authenticated;
grant execute on function public.admin_reorder_rooms(uuid[]) to anon,authenticated;
grant execute on function public.admin_delete_tag(text) to anon,authenticated;
grant execute on function public.admin_set_room_manual(uuid,uuid[],boolean) to anon,authenticated;

grant execute on function public.admin_sync_local_videos(jsonb) to anon,authenticated;

-- 플레이어 상태 ----------------------------------------------------------
-- canonical player_get_state definition is declared later in this schema.


create or replace function public.player_heartbeat(p_key uuid,p_status jsonb)
returns void language plpgsql security definer set search_path=public as $$
declare
  clean jsonb; v_room uuid; v_prev jsonb; v_last timestamptz; v_now timestamptz:=clock_timestamp();
  v_delta int:=0; v_day date; v_local_time time; v_start time; v_end time; v_open boolean:=false; v_in_hours boolean:=false;
  v_state text; v_mode text; v_prev_state text; v_prev_mode text; v_reconnect int:=0; v_error_transition int:=0;
begin
  select id,player_status,last_seen_at into v_room,v_prev,v_last from public.rooms where player_key=p_key for update;
  if v_room is null then return; end if;
  if p_status is null or jsonb_typeof(p_status)<>'object' or pg_column_size(p_status)>4096 then
    update public.rooms set heartbeat_rejected_count=heartbeat_rejected_count+1 where id=v_room; return;
  end if;
  clean=jsonb_build_object(
    'video_id',case when jsonb_typeof(p_status->'video_id')='string' then left(p_status->>'video_id',64) else null end,
    'title',left(coalesce(p_status->>'title',''),160),'mode',left(coalesce(p_status->>'mode',''),32),
    'playback_state',left(coalesce(p_status->>'playback_state',''),32),
    'current_time',case when jsonb_typeof(p_status->'current_time')='number' then greatest(0,least((p_status->>'current_time')::numeric,86400)) else 0 end,
    'duration',case when jsonb_typeof(p_status->'duration')='number' then greatest(0,least((p_status->>'duration')::numeric,86400)) else 0 end,
    'muted',case when jsonb_typeof(p_status->'muted')='boolean' then (p_status->>'muted')::boolean else false end,
    'volume',case when jsonb_typeof(p_status->'volume')='number' then greatest(0,least((p_status->>'volume')::int,100)) else 0 end,
    'online',case when jsonb_typeof(p_status->'online')='boolean' then (p_status->>'online')::boolean else false end,
    'error',left(coalesce(p_status->>'error',''),300),'source',left(coalesce(p_status->>'source',''),64),
    'playlist_titles',coalesce((select jsonb_agg(left(x.value,120) order by x.ord) from jsonb_array_elements_text(case when jsonb_typeof(p_status->'playlist_titles')='array' then p_status->'playlist_titles' else '[]'::jsonb end) with ordinality as x(value,ord) where x.ord<=12),'[]'::jsonb),
    'active_hash',left(coalesce(p_status->>'active_hash',''),100),
    'pending_hash',left(coalesce(p_status->>'pending_hash',''),100),
    'pending_count',case when jsonb_typeof(p_status->'pending_count')='number' then greatest(0,least((p_status->>'pending_count')::int,500)) end,
    'pending_total',case when jsonb_typeof(p_status->'pending_total')='number' then greatest(0,least((p_status->>'pending_total')::int,500)) end,
    'storage_persisted',case when jsonb_typeof(p_status->'storage_persisted')='boolean' then (p_status->>'storage_persisted')::boolean end,
    'offline_cache_error',left(coalesce(p_status->>'offline_cache_error',''),160),
    'failed_videos',coalesce((select jsonb_agg(jsonb_build_object('id',left(coalesce(x.item->>'id',''),100),'title',left(coalesce(x.item->>'title',''),60),'code',left(coalesce(x.item->>'code',''),40))) from jsonb_array_elements(case when jsonb_typeof(p_status->'failed_videos')='array' then p_status->'failed_videos' else '[]'::jsonb end) with ordinality as x(item,ord) where x.ord<=5),'[]'::jsonb),
    'playlist_count',case when jsonb_typeof(p_status->'playlist_count')='number' then greatest(0,least((p_status->>'playlist_count')::int,500)) else 0 end,
    'current_index',case when jsonb_typeof(p_status->'current_index')='number' then greatest(0,least((p_status->>'current_index')::int,499)) else 0 end,
    'next_title',left(coalesce(p_status->>'next_title',''),160),'app_version',left(coalesce(p_status->>'app_version',''),24),'reported_at',left(coalesce(p_status->>'reported_at',''),48)
  );
  v_state:=clean->>'playback_state'; v_mode:=clean->>'mode'; v_prev_state:=coalesce(v_prev->>'playback_state',''); v_prev_mode:=coalesce(v_prev->>'mode','');
  v_day:=(v_now at time zone 'Asia/Seoul')::date; v_local_time:=(v_now at time zone 'Asia/Seoul')::time;
  select is_open,start_time,end_time into v_open,v_start,v_end from public.signage_room_operating_window(v_room,v_day);
  v_in_hours:=v_open and v_local_time>=v_start and v_local_time<v_end;
  if v_last is not null then
    -- Up to one 5-minute telemetry interval, with margin for timer jitter.
    -- Older 60-second caps undercounted playback by ~80% at 5-minute intervals.
    v_delta:=greatest(0,least(360,extract(epoch from (v_now-v_last))::int));
    -- A normal 5-minute interval is not a reconnect.
    if extract(epoch from (v_now-v_last))>600 then v_reconnect:=1; end if;
  end if;
  if coalesce(clean->>'error','')<>'' and coalesce(v_prev->>'error','')='' then v_error_transition:=1; end if;
  if v_in_hours and v_delta>0 then
    insert into public.room_playback_daily(day,room_id,online_seconds,playing_seconds,default_seconds,custom_seconds,override_seconds,error_seconds,paused_seconds,reconnect_count,error_count,updated_at)
    values(v_day,v_room,v_delta,
      case when v_state in ('playing','emergency') then v_delta else 0 end,
      case when v_state in ('playing','emergency') and v_mode='default' then v_delta else 0 end,
      case when v_state in ('playing','emergency') and v_mode in ('patient','session') then v_delta else 0 end,
      case when v_state in ('playing','emergency') and v_mode in ('broadcast','broadcast_schedule','group','group_schedule','manual') then v_delta else 0 end,
      case when v_state='error' then v_delta else 0 end,
      case when v_state='paused' then v_delta else 0 end,v_reconnect,v_error_transition,v_now)
    on conflict(day,room_id) do update set
      online_seconds=room_playback_daily.online_seconds+excluded.online_seconds,
      playing_seconds=room_playback_daily.playing_seconds+excluded.playing_seconds,
      default_seconds=room_playback_daily.default_seconds+excluded.default_seconds,
      custom_seconds=room_playback_daily.custom_seconds+excluded.custom_seconds,
      override_seconds=room_playback_daily.override_seconds+excluded.override_seconds,
      error_seconds=room_playback_daily.error_seconds+excluded.error_seconds,
      paused_seconds=room_playback_daily.paused_seconds+excluded.paused_seconds,
      reconnect_count=room_playback_daily.reconnect_count+excluded.reconnect_count,
      error_count=room_playback_daily.error_count+excluded.error_count,updated_at=v_now;
  end if;
  if v_prev is null or v_state<>v_prev_state or v_mode<>v_prev_mode or coalesce(clean->>'video_id','')<>coalesce(v_prev->>'video_id','') or coalesce(clean->>'error','')<>coalesce(v_prev->>'error','') then
    insert into public.player_events(room_id,event_type,mode,playback_state,video_id,title,error)
    values(v_room,'state_change',nullif(v_mode,''),nullif(v_state,''),nullif(clean->>'video_id',''),nullif(clean->>'title',''),nullif(clean->>'error',''));
  end if;
  update public.rooms set last_seen_at=v_now,player_status=clean where id=v_room;
end $$;

revoke all on function public.player_heartbeat(uuid,jsonb) from public;

grant execute on function public.player_heartbeat(uuid,jsonb) to anon,authenticated;

-- Realtime refresh -------------------------------------------------------
create or replace function public.notify_room_change()
returns trigger language plpgsql security definer set search_path=public as $$
begin
  if row(new.name,new.group_id,new.room_mode,new.force_mute,new.default_playlist_id,new.default_tags,new.session_tags,new.session_started_at,new.session_timeout_min,new.session_age_group,new.session_gender,new.session_treatment,new.manual_active,new.manual_video_ids,new.volume,new.paused,new.overlay_text,new.reload_nonce)
    is distinct from row(old.name,old.group_id,old.room_mode,old.force_mute,old.default_playlist_id,old.default_tags,old.session_tags,old.session_started_at,old.session_timeout_min,old.session_age_group,old.session_gender,old.session_treatment,old.manual_active,old.manual_video_ids,old.volume,old.paused,old.overlay_text,old.reload_nonce) then
    perform realtime.send(jsonb_build_object('at',clock_timestamp()),'refresh','room:'||new.player_key::text,false);
  end if;
  return new;
end $$;

create or replace function public.notify_all_rooms()
returns trigger language plpgsql security definer set search_path=public as $$
declare k uuid; begin for k in select player_key from public.rooms loop perform realtime.send(jsonb_build_object('at',clock_timestamp()),'refresh','room:'||k::text,false); end loop; return null; end $$;

create or replace function public.notify_broadcast_change()
returns trigger language plpgsql security definer set search_path=public as $$
begin
  if old.active or new.active then perform public.send_refresh_all_rooms(); end if;
  return new;
end $$;

drop trigger if exists rooms_notify on public.rooms;
create trigger rooms_notify after update on public.rooms for each row execute function public.notify_room_change();
drop trigger if exists videos_notify on public.videos;
create trigger videos_notify after insert or update or delete on public.videos for each statement execute function public.notify_all_rooms();
drop trigger if exists broadcast_notify on public.broadcast;
create trigger broadcast_notify after update on public.broadcast for each row execute function public.notify_broadcast_change();
drop trigger if exists settings_notify on public.app_settings;
create trigger settings_notify after update on public.app_settings for each statement execute function public.notify_all_rooms();

do $$ begin
  begin alter publication supabase_realtime add table public.rooms; exception when duplicate_object then null; end;
  begin alter publication supabase_realtime add table public.broadcast; exception when duplicate_object then null; end;
end $$;

