grant select on public.control_history to anon,authenticated;

create or replace function public.admin_delete_video(p_id uuid)
returns void language plpgsql security definer set search_path=public,extensions as $$
begin
  if not public.is_admin() then raise exception 'ADMIN_REQUIRED'; end if;
  update public.broadcast set video_ids=array_remove(video_ids,p_id),active=case when coalesce(array_length(array_remove(video_ids,p_id),1),0)>0 then active else false end,updated_at=now() where id=1;
  update public.rooms set manual_video_ids=array_remove(manual_video_ids,p_id),manual_active=case when coalesce(array_length(array_remove(manual_video_ids,p_id),1),0)>0 then manual_active else false end where p_id=any(manual_video_ids);
  update public.group_broadcasts set video_ids=array_remove(video_ids,p_id),active=case when coalesce(array_length(array_remove(video_ids,p_id),1),0)>0 then active else false end,updated_at=now() where p_id=any(video_ids);
  update public.broadcast_schedules set video_ids=array_remove(video_ids,p_id),enabled=false where p_id=any(video_ids);
  update public.app_settings set emergency_video_id=null,updated_at=now() where emergency_video_id=p_id;
  delete from public.videos where id=p_id;
end $$;
revoke all on function public.admin_delete_video(uuid) from public;
grant execute on function public.admin_delete_video(uuid) to anon,authenticated;

create or replace function public.send_refresh_group(p_group uuid)
returns void language plpgsql security definer set search_path=public as $$
declare k uuid;
begin
  for k in select player_key from public.rooms where group_id=p_group loop
    perform realtime.send(jsonb_build_object('at',clock_timestamp()),'refresh','room:'||k::text,false);
  end loop;
end $$;
revoke all on function public.send_refresh_group(uuid) from public,anon,authenticated;

revoke all on function public.start_patient_session(uuid,text,text,text) from public;
grant execute on function public.start_patient_session(uuid,text,text,text) to anon,authenticated;

drop function if exists public.staff_room_list();

create or replace function public.staff_room_list()
returns table(
  id uuid,name text,sort_order int,default_tags text[],session_tags text[],
  session_started_at timestamptz,session_timeout_min int,session_expires_at timestamptz,
  session_age_group text,session_gender text,session_treatment text,last_seen_at timestamptz,
  group_id uuid,group_name text,group_kind text,room_mode text
) language plpgsql stable security definer set search_path=public as $$
begin
  if not public.is_member() then raise exception 'not allowed'; end if;
  return query
  select r.id,r.name,r.sort_order,r.default_tags,r.session_tags,r.session_started_at,r.session_timeout_min,
    case when r.session_started_at is not null and r.session_timeout_min>0 then r.session_started_at+make_interval(mins=>r.session_timeout_min) else null end,
    r.session_age_group,r.session_gender,r.session_treatment,r.last_seen_at,
    r.group_id,g.name,g.kind,r.room_mode
  from public.rooms r left join public.signage_groups g on g.id=r.group_id
  order by coalesce(g.sort_order,2147483647),g.name nulls last,r.sort_order,r.created_at;
end $$;
revoke all on function public.staff_room_list() from public;
grant execute on function public.staff_room_list() to anon,authenticated;


create or replace function public.admin_set_group_broadcast(p_group uuid,p_active boolean,p_video_ids uuid[],p_notice text default null,p_delay_ms int default 2000)
returns void language plpgsql security definer set search_path=public as $$
declare v_ids uuid[]; v_before jsonb; v_after jsonb; v_label text;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  select name into v_label from public.signage_groups where id=p_group;
  if v_label is null then raise exception 'group not found'; end if;
  insert into public.group_broadcasts(group_id) values(p_group) on conflict(group_id) do nothing;
  select to_jsonb(g) into v_before from public.group_broadcasts g where group_id=p_group;
  if coalesce(p_active,false) then
    select coalesce(array_agg(v.id order by array_position(p_video_ids,v.id)),'{}'::uuid[]) into v_ids
    from public.videos v where v.id=any(coalesce(p_video_ids,'{}'::uuid[])) and v.active and (v.source<>'local' or v.available);
  else v_ids:=coalesce(p_video_ids,'{}'::uuid[]); end if;
  update public.group_broadcasts set
    active=coalesce(p_active,false) and coalesce(array_length(v_ids,1),0)>0,
    video_ids=v_ids,notice_text=nullif(trim(coalesce(p_notice,'')),''),
    effective_at=case when coalesce(p_active,false) and coalesce(array_length(v_ids,1),0)>0 then clock_timestamp()+make_interval(secs=>greatest(0,least(coalesce(p_delay_ms,2000),10000))/1000.0) else null end,
    revision=revision+1,updated_at=clock_timestamp() where group_id=p_group;
  select to_jsonb(g) into v_after from public.group_broadcasts g where group_id=p_group;
  insert into public.control_history(scope_type,scope_id,action,label,before_state,after_state) values('group',p_group,case when p_active then 'start' else 'stop' end,v_label,v_before,v_after);
end $$;

-- canonical admin_set_rooms_manual definition is declared later in this schema.



create or replace function public.admin_create_schedule(p_scope_type text,p_group uuid,p_video_ids uuid[],p_notice text,p_starts_at timestamptz,p_ends_at timestamptz)
returns uuid language plpgsql security definer set search_path=public as $$
declare v_id uuid; v_ids uuid[]; v_label text;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  if p_scope_type not in ('hospital','group') then raise exception 'invalid scope'; end if;
  if p_ends_at<=p_starts_at then raise exception '종료시각은 시작시각 이후여야 합니다'; end if;
  if p_scope_type='group' and p_group is null then raise exception 'group required'; end if;
  select coalesce(array_agg(v.id order by array_position(p_video_ids,v.id)),'{}'::uuid[]) into v_ids from public.videos v
  where v.id=any(coalesce(p_video_ids,'{}'::uuid[])) and v.active and (v.source<>'local' or v.available);
  if coalesce(array_length(v_ids,1),0)=0 then raise exception 'video required'; end if;
  if p_scope_type='group' then select name into v_label from public.signage_groups where id=p_group; else v_label:='전체 병원'; end if;
  insert into public.broadcast_schedules(scope_type,group_id,video_ids,notice_text,starts_at,ends_at)
  values(p_scope_type,case when p_scope_type='group' then p_group else null end,v_ids,nullif(trim(coalesce(p_notice,'')),''),p_starts_at,p_ends_at) returning id into v_id;
  insert into public.control_history(scope_type,scope_id,action,label,after_state) values('schedule',v_id,'schedule_create',v_label,(select to_jsonb(s) from public.broadcast_schedules s where id=v_id));
  return v_id;
end $$;

create or replace function public.admin_delete_schedule(p_id uuid)
returns void language plpgsql security definer set search_path=public as $$
declare v_before jsonb; v_label text;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  select to_jsonb(s),case when s.scope_type='hospital' then '전체 병원' else coalesce(g.name,'그룹') end into v_before,v_label
  from public.broadcast_schedules s left join public.signage_groups g on g.id=s.group_id where s.id=p_id;
  delete from public.broadcast_schedules where id=p_id;
  if v_before is not null then insert into public.control_history(scope_type,scope_id,action,label,before_state) values('schedule',p_id,'schedule_delete',v_label,v_before); end if;
end $$;

create or replace function public.admin_undo_control(p_history bigint)
returns void language plpgsql security definer set search_path=public as $$
declare h public.control_history; item jsonb;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  select * into h from public.control_history where id=p_history;
  if not found or h.before_state is null then raise exception '복귀할 상태가 없습니다'; end if;
  if h.scope_type='hospital' then
    update public.broadcast set active=coalesce((h.before_state->>'active')::boolean,false),video_ids=coalesce(ARRAY(SELECT (jsonb_array_elements_text(h.before_state->'video_ids'))::uuid),'{}'::uuid[]),notice_text=h.before_state->>'notice_text',effective_at=null,revision=revision+1,updated_at=clock_timestamp() where id=1;
  elsif h.scope_type='group' then
    insert into public.group_broadcasts(group_id) values(h.scope_id) on conflict(group_id) do nothing;
    update public.group_broadcasts set active=coalesce((h.before_state->>'active')::boolean,false),video_ids=coalesce(ARRAY(SELECT (jsonb_array_elements_text(h.before_state->'video_ids'))::uuid),'{}'::uuid[]),notice_text=h.before_state->>'notice_text',effective_at=null,revision=revision+1,updated_at=clock_timestamp() where group_id=h.scope_id;
  elsif h.scope_type='rooms' then
    for item in select * from jsonb_array_elements(h.before_state) loop
      update public.rooms set manual_active=coalesce((item->>'manual_active')::boolean,false),manual_video_ids=coalesce(ARRAY(SELECT (jsonb_array_elements_text(item->'manual_video_ids'))::uuid),'{}'::uuid[]),manual_updated_at=clock_timestamp() where id=(item->>'id')::uuid;
    end loop;
  else raise exception '이 이력은 직접 복귀할 수 없습니다'; end if;
  insert into public.control_history(scope_type,scope_id,action,label,before_state,after_state) values(h.scope_type,h.scope_id,'undo',coalesce(h.label,'직전 상태'),h.after_state,h.before_state);
end $$;

revoke all on function public.admin_set_group_broadcast(uuid,boolean,uuid[],text,int) from public;

revoke all on function public.admin_create_schedule(text,uuid,uuid[],text,timestamptz,timestamptz) from public;
revoke all on function public.admin_delete_schedule(uuid) from public;
revoke all on function public.admin_undo_control(bigint) from public;
grant execute on function public.admin_set_group_broadcast(uuid,boolean,uuid[],text,int) to anon,authenticated;

grant execute on function public.admin_create_schedule(text,uuid,uuid[],text,timestamptz,timestamptz) to anon,authenticated;
grant execute on function public.admin_delete_schedule(uuid) to anon,authenticated;
grant execute on function public.admin_undo_control(bigint) to anon,authenticated;

-- v2.6 플레이어 상태: 전체 > 개별 > 그룹 > 맞춤 > 기본 + 예약 송출


create or replace function public.notify_group_broadcast_change()
returns trigger language plpgsql security definer set search_path=public as $$
begin perform public.send_refresh_group(new.group_id); return new; end $$;
create or replace function public.notify_schedule_change()
returns trigger language plpgsql security definer set search_path=public as $$
begin
  if tg_op='DELETE' then
    if old.scope_type='hospital' then perform public.send_refresh_all_rooms(); else perform public.send_refresh_group(old.group_id); end if;
    return old;
  end if;
  if new.scope_type='hospital' then perform public.send_refresh_all_rooms(); else perform public.send_refresh_group(new.group_id); end if;
  return new;
end $$;

drop trigger if exists group_broadcasts_notify on public.group_broadcasts;
create trigger group_broadcasts_notify after insert or update on public.group_broadcasts for each row execute function public.notify_group_broadcast_change();
drop trigger if exists schedules_notify on public.broadcast_schedules;
create trigger schedules_notify after insert or update or delete on public.broadcast_schedules for each row execute function public.notify_schedule_change();

do $$ begin
  begin alter publication supabase_realtime add table public.group_broadcasts; exception when duplicate_object then null; end;
end $$;


create or replace function public.admin_stop_broadcast(p_resume text default 'previous')
returns void language plpgsql security definer set search_path=public as $$
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  if p_resume not in ('previous','default') then raise exception 'invalid resume mode'; end if;
  perform public.admin_set_broadcast(false,(select video_ids from public.broadcast where id=1),(select notice_text from public.broadcast where id=1),0);
  if p_resume='default' then
    update public.group_broadcasts set active=false,effective_at=null,revision=revision+1,updated_at=clock_timestamp() where active;
    update public.rooms set manual_active=false,manual_video_ids='{}',manual_updated_at=clock_timestamp(),session_tags='{}',session_started_at=null,session_age_group=null,session_gender=null,session_treatment=null
    where manual_active or session_started_at is not null;
  end if;
end $$;
