create or replace function public.apply_room_video_rules(p_room uuid,p_playlist jsonb)
returns jsonb language sql stable security definer set search_path=public as $$
  select coalesce(jsonb_agg(x.item order by coalesce(rr.sort_order,(x.ord*10)::int),x.ord),'[]'::jsonb)
  from jsonb_array_elements(coalesce(p_playlist,'[]'::jsonb)) with ordinality as x(item,ord)
  left join public.room_video_rules rr on rr.room_id=p_room and rr.video_id=(x.item->>'id')::uuid
  where coalesce(rr.enabled,true)
    and (rr.starts_at is null or rr.starts_at<=clock_timestamp())
    and (rr.ends_at is null or rr.ends_at>clock_timestamp())
$$;

create or replace function public.notify_room_video_rule()
returns trigger language plpgsql security definer set search_path=public as $$
declare v_room uuid; v_key uuid;
begin
  if tg_op='DELETE' then v_room:=old.room_id; else v_room:=new.room_id; end if;
  select player_key into v_key from public.rooms where id=v_room;
  if v_key is not null then perform realtime.send(jsonb_build_object('at',clock_timestamp()),'refresh','room:'||v_key::text,false); end if;
  if tg_op='DELETE' then return old; else return new; end if;
end $$;
drop trigger if exists room_video_rules_notify on public.room_video_rules;
create trigger room_video_rules_notify after insert or update or delete on public.room_video_rules for each row execute function public.notify_room_video_rule();


create or replace function public.admin_set_room_video_rule(p_room uuid,p_video uuid,p_enabled boolean,p_starts_at timestamptz default null,p_ends_at timestamptz default null)
returns void language plpgsql security definer set search_path=public as $$
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  if p_starts_at is not null and p_ends_at is not null and p_ends_at<=p_starts_at then raise exception '종료 시각은 시작 시각보다 뒤여야 합니다'; end if;
  if not exists(select 1 from public.rooms where id=p_room) then raise exception '공간을 찾을 수 없습니다'; end if;
  if not exists(select 1 from public.videos where id=p_video) then raise exception '영상을 찾을 수 없습니다'; end if;
  insert into public.room_video_rules(room_id,video_id,enabled,starts_at,ends_at,updated_at)
  values(p_room,p_video,coalesce(p_enabled,true),p_starts_at,p_ends_at,clock_timestamp())
  on conflict(room_id,video_id) do update set enabled=excluded.enabled,starts_at=excluded.starts_at,ends_at=excluded.ends_at,updated_at=clock_timestamp();
end $$;

create or replace function public.admin_set_room_video_order(p_room uuid,p_video_ids uuid[])
returns void language plpgsql security definer set search_path=public as $$
declare v_id uuid; v_pos int:=0;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  foreach v_id in array coalesce(p_video_ids,'{}'::uuid[]) loop
    v_pos:=v_pos+10;
    insert into public.room_video_rules(room_id,video_id,sort_order,updated_at) values(p_room,v_id,v_pos,clock_timestamp())
    on conflict(room_id,video_id) do update set sort_order=excluded.sort_order,updated_at=clock_timestamp();
  end loop;
end $$;

create or replace function public.admin_clear_room_video_rules(p_room uuid)
returns void language plpgsql security definer set search_path=public as $$
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  delete from public.room_video_rules where room_id=p_room;
end $$;

create or replace function public.admin_prune_player_events(p_days int default 30)
returns bigint language plpgsql security definer set search_path=public as $$
declare v_count bigint;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  p_days:=greatest(7,least(coalesce(p_days,30),365));
  delete from public.player_events where occurred_at<clock_timestamp()-make_interval(days=>p_days);
  get diagnostics v_count=row_count;
  return v_count;
end $$;


