-- v2.21.8 realtime publication hardening
-- Clinic Signage v2.21.8
-- Ensure tables used for immediate player/admin updates are in Supabase Realtime publication.
-- Safe to re-run: tables already present are skipped.

do $$
declare
  t text;
  wanted text[] := array[
    'rooms',
    'broadcast',
    'group_broadcasts',
    'room_video_rules',
    'playlist_items',
    'playlists',
    'videos',
    'broadcast_schedules'
  ];
begin
  foreach t in array wanted loop
    if to_regclass(format('public.%I', t)) is not null
       and not exists (
         select 1
         from pg_publication_tables
         where pubname = 'supabase_realtime'
           and schemaname = 'public'
           and tablename = t
       ) then
      execute format('alter publication supabase_realtime add table public.%I', t);
    end if;
  end loop;
end $$;



-- =====================================================================
-- Clinic Signage v2.24.0 · 보안 핫픽스 (가장 먼저, 반드시 실행)
--
-- 1) PIN 없이 관리자/스텝 RPC 호출이 가능한 문제
--    is_admin()/is_member() 는 세션이 없으면 false 가 아니라 NULL 을 반환합니다.
--    모든 관리 함수가 `if not public.is_admin() then raise ...` 형태라서
--    NOT NULL = NULL → IF 조건 불성립 → 예외 없이 통과합니다.
--    결과: 웹 JS 에 공개된 anon key 만으로 PIN 없이 전체 송출 시작/공지 문구 변경/
--          영상 규칙 변경 등 admin_* · staff_* RPC 46곳이 모두 실행됩니다.
--    (RLS 정책은 NULL 을 거부로 처리하므로 테이블 직접 접근은 안전했습니다.)
--    수정: 두 함수가 항상 true/false 만 반환하도록 coalesce. 호출부 46곳은 수정 불필요.
--
-- 2) admin_change_pin 이 crypt() 를 찾지 못하는 문제
--    pgcrypto 는 extensions 스키마에 있는데 search_path=public 으로 고정되어 있어
--    관리자 화면의 PIN 변경이 "function crypt(...) does not exist" 로 실패합니다.
--
-- 여러 번 실행해도 안전합니다.
-- =====================================================================




-- 확인용 (SQL Editor 에서 세션 헤더 없이 실행 → 둘 다 false 여야 정상)
-- select public.is_admin(), public.is_member();


-- =====================================================================
-- Clinic Signage v2.24.1 · 저비용 송출 상태 확인 (Realtime 상태 브로드캐스트 제거)
--
-- 바뀌는 점
--   1) player_report         : 플레이어 상태 보고 (이벤트 시 + 60초 presence). 화이트리스트/크기 제한,
--                              변경 지문(status_fp)으로 "실제 변경" 시각(changed_at)만 갱신.
--   2) signage_live_status   : 관리자/스텝용 상태 조회. p_since 이후 변경된 행만 반환 + 전체 last_seen 목록.
--                              PIN 세션 검증(is_member). 관리자 송출 확인(ack)과 30초 delta 조회에 사용.
--   3) player_get_state_lite : player_get_state 결과에서 썸네일(base64)을 제거해 플레이어 egress 절감.
--   4) player_live_status 를 supabase_realtime publication 에서 제외 (더 이상 구독자가 없음).
--
-- 안전성
--   - 기존 함수(player_get_state, player_live_ping, player_heartbeat, signal_signage_rooms)는 수정하지 않습니다.
--   - 프론트엔드는 새 함수가 없으면 기존 함수로 자동 fallback 하므로, SQL/프론트 배포 순서는 무관합니다.
--   - 여러 번 실행해도 안전합니다.
-- =====================================================================

-- 1. player_live_status: 기존 테이블을 유지하면서 필요한 컬럼만 보강 --------------------------------
create table if not exists public.player_live_status (
  room_id uuid primary key references public.rooms(id) on delete cascade,
  last_seen_at timestamptz,
  player_status jsonb,
  updated_at timestamptz not null default now()
);
alter table public.player_live_status add column if not exists last_seen_at timestamptz;
alter table public.player_live_status add column if not exists player_status jsonb;
alter table public.player_live_status add column if not exists updated_at timestamptz default now();
alter table public.player_live_status add column if not exists changed_at timestamptz;
alter table public.player_live_status add column if not exists status_fp text;
create unique index if not exists player_live_status_room_uidx on public.player_live_status(room_id);
create index if not exists player_live_status_changed_idx on public.player_live_status(changed_at);
update public.player_live_status
   set changed_at = coalesce(updated_at, last_seen_at, now()),
       player_status = case when player_status ? 'thumbnail' then player_status - 'thumbnail' else player_status end
 where changed_at is null or player_status ? 'thumbnail';

alter table public.player_live_status enable row level security;
drop policy if exists player_live_status_member_select on public.player_live_status;
-- canonical site-scoped live-status policy is defined after site foundation.
grant select on public.player_live_status to anon, authenticated;

-- 2. 플레이어 상태 보고 ------------------------------------------------------------------------------
create or replace function public.player_report(p_key uuid, p_status jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_room uuid;
  v_now timestamptz := clock_timestamp();
  v_clean jsonb;
  v_fp text;
  v_prev_fp text;
  v_prev_seen timestamptz;
  v_synced text;
  ts_re constant text := '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9:.]+(Z|[+-][0-9]{2}(:?[0-9]{2})?)?$';
begin
  select id into v_room from public.rooms where player_key = p_key;
  if v_room is null then return null; end if;
  if p_status is null or jsonb_typeof(p_status) <> 'object' or pg_column_size(p_status) > 8192 then
    return jsonb_build_object('ok', false, 'error', 'invalid_status', 'server_time', v_now);
  end if;

  v_synced := case when jsonb_typeof(p_status->'synced_at') = 'string' and (p_status->>'synced_at') ~ ts_re
                   then left(p_status->>'synced_at', 40) end;

  v_clean := jsonb_strip_nulls(jsonb_build_object(
    'video_id',        case when jsonb_typeof(p_status->'video_id') = 'string' then left(p_status->>'video_id', 64) end,
    'title',           left(coalesce(p_status->>'title', ''), 160),
    'mode',            left(coalesce(p_status->>'mode', ''), 32),
    'playback_state',  left(coalesce(p_status->>'playback_state', ''), 32),
    'current_time',    case when jsonb_typeof(p_status->'current_time') = 'number' then greatest(0, least((p_status->>'current_time')::numeric, 86400)) else 0 end,
    'duration',        case when jsonb_typeof(p_status->'duration') = 'number' then greatest(0, least((p_status->>'duration')::numeric, 86400)) else 0 end,
    'muted',           case when jsonb_typeof(p_status->'muted') = 'boolean' then (p_status->>'muted')::boolean else false end,
    'volume',          case when jsonb_typeof(p_status->'volume') = 'number' then greatest(0, least((p_status->>'volume')::numeric, 100))::int else 0 end,
    'online',          case when jsonb_typeof(p_status->'online') = 'boolean' then (p_status->>'online')::boolean else true end,
    'error',           nullif(left(coalesce(p_status->>'error', ''), 300), ''),
    'source',          left(coalesce(p_status->>'source', ''), 64),
    'recovery_stage',  case when jsonb_typeof(p_status->'recovery_stage') = 'number' then greatest(0, least((p_status->>'recovery_stage')::numeric, 9))::int end,
    'playlist_video_ids', coalesce((
        select jsonb_agg(left(x.value, 64) order by x.ord)
          from jsonb_array_elements_text(case when jsonb_typeof(p_status->'playlist_video_ids') = 'array' then p_status->'playlist_video_ids' else '[]'::jsonb end) with ordinality as x(value, ord)
         where x.ord <= 20), '[]'::jsonb),
    'playlist_titles', coalesce((
        select jsonb_agg(left(x.value, 120) order by x.ord)
          from jsonb_array_elements_text(case when jsonb_typeof(p_status->'playlist_titles') = 'array' then p_status->'playlist_titles' else '[]'::jsonb end) with ordinality as x(value, ord)
         where x.ord <= 12), '[]'::jsonb),
    'playlist_count',  case when jsonb_typeof(p_status->'playlist_count') = 'number' then greatest(0, least((p_status->>'playlist_count')::numeric, 500))::int else 0 end,
    'current_index',   case when jsonb_typeof(p_status->'current_index') = 'number' then greatest(0, least((p_status->>'current_index')::numeric, 499))::int else 0 end,
    'next_title',      nullif(left(coalesce(p_status->>'next_title', ''), 160), ''),
    'app_version',     left(coalesce(p_status->>'app_version', ''), 24),
    'sync_revision',   nullif(left(coalesce(p_status->>'sync_revision', ''), 160), ''),
    'offline_cache_ready', case when jsonb_typeof(p_status->'offline_cache_ready')='boolean' then (p_status->>'offline_cache_ready')::boolean else false end,
    'offline_cache_count', case when jsonb_typeof(p_status->'offline_cache_count')='number' then greatest(0,least((p_status->>'offline_cache_count')::int,500)) else 0 end,
    'offline_cache_total', case when jsonb_typeof(p_status->'offline_cache_total')='number' then greatest(0,least((p_status->>'offline_cache_total')::int,500)) else 0 end,
    'offline_cache_error', nullif(left(coalesce(p_status->>'offline_cache_error',''),160),''),
    'active_hash',left(coalesce(p_status->>'active_hash',''),100),
    'pending_hash',left(coalesce(p_status->>'pending_hash',''),100),
    'pending_count',case when jsonb_typeof(p_status->'pending_count')='number' then greatest(0,least((p_status->>'pending_count')::int,500)) end,
    'pending_total',case when jsonb_typeof(p_status->'pending_total')='number' then greatest(0,least((p_status->>'pending_total')::int,500)) end,
    'storage_persisted',case when jsonb_typeof(p_status->'storage_persisted')='boolean' then (p_status->>'storage_persisted')::boolean end,
        'failed_videos',coalesce((select jsonb_agg(jsonb_build_object('id',left(coalesce(x.item->>'id',''),100),'title',left(coalesce(x.item->>'title',''),60),'code',left(coalesce(x.item->>'code',''),40))) from jsonb_array_elements(case when jsonb_typeof(p_status->'failed_videos')='array' then p_status->'failed_videos' else '[]'::jsonb end) with ordinality as x(item,ord) where x.ord<=5),'[]'::jsonb),
    'operating_active', case when jsonb_typeof(p_status->'operating_active')='boolean' then (p_status->>'operating_active')::boolean else true end,
    'priority', nullif(left(coalesce(p_status->>'priority',''),32),''),
    'update_pending_version', nullif(left(coalesce(p_status->>'update_pending_version',''),24),''),
    'update_error', nullif(left(coalesce(p_status->>'update_error',''),160),''),
    'failed_video_count', case when jsonb_typeof(p_status->'failed_video_count')='number' then greatest(0,least((p_status->>'failed_video_count')::int,500)) else 0 end,
    'synced_at',       v_synced
  )) || jsonb_build_object('reported_at', v_now);

  -- 재생 위치/보고 시각을 제외한 "의미 있는 변경" 지문
  v_fp := md5((v_clean - 'current_time' - 'reported_at' - 'pending_count')::text);

  select status_fp, last_seen_at into v_prev_fp, v_prev_seen
    from public.player_live_status where room_id = v_room;

  -- 같은 내용이 짧은 간격으로 반복되면 쓰기 생략 (오동작 플레이어 보호)
  if v_prev_fp is not distinct from v_fp and v_prev_seen is not null and v_prev_seen > v_now - interval '5 seconds' then
    return jsonb_build_object('ok', true, 'skipped', true, 'server_time', v_now);
  end if;

  insert into public.player_live_status as s (room_id, last_seen_at, player_status, updated_at, changed_at, status_fp)
  values (v_room, v_now, v_clean, v_now, v_now, v_fp)
  on conflict (room_id) do update set
    last_seen_at  = excluded.last_seen_at,
    player_status = excluded.player_status,
    updated_at    = excluded.updated_at,
    changed_at    = case when s.status_fp is distinct from excluded.status_fp then excluded.changed_at else coalesce(s.changed_at, excluded.changed_at) end,
    status_fp     = excluded.status_fp;

  return jsonb_build_object('ok', true, 'server_time', v_now);
end $$;
revoke all on function public.player_report(uuid, jsonb) from public;
grant execute on function public.player_report(uuid, jsonb) to anon, authenticated;

-- 3. 관리자/스텝 상태 조회 (delta + ack) ---------------------------------------------------------------

-- canonical: earlier duplicate signage_live_status removed; final definition appears below.


-- 4. 플레이어용 상태 (썸네일 제거) -------------------------------------------------------------------
create or replace function public.player_get_state_lite(p_key uuid)
returns jsonb language plpgsql security definer set search_path = public as $$
declare s jsonb;
begin
  s := public.player_get_state(p_key);
  if s is null then return null; end if;
  return s || jsonb_build_object(
    'playlist', coalesce((
      select jsonb_agg(case when jsonb_typeof(x.e) = 'object' then x.e - 'thumbnail' else x.e end order by x.o)
        from jsonb_array_elements(case when jsonb_typeof(s->'playlist') = 'array' then s->'playlist' else '[]'::jsonb end) with ordinality as x(e, o)
    ), '[]'::jsonb),
    'emergency_video', case when jsonb_typeof(s->'emergency_video') = 'object' then (s->'emergency_video') - 'thumbnail' else coalesce(s->'emergency_video', 'null'::jsonb) end
  );
end $$;
revoke all on function public.player_get_state_lite(uuid) from public;
grant execute on function public.player_get_state_lite(uuid) to anon, authenticated;

-- 5. Realtime publication 정리 ----------------------------------------------------------------------
-- 플레이어 상태는 더 이상 postgres_changes 로 구독하지 않습니다. 보고 1회마다 생기던 WAL 디코딩/RLS 평가 제거.
do $$
begin
  if exists (select 1 from pg_publication_tables
              where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = 'player_live_status') then
    alter publication supabase_realtime drop table public.player_live_status;
  end if;
end $$;

-- 참고(선택): rooms 는 player_heartbeat 가 60초마다 갱신하지만, 관리자 화면의 rooms postgres_changes 구독은
-- PIN 세션 RLS(is_admin) 때문에 Realtime 에서 통과하지 못해 실제로 전달되지 않았습니다. v2.24 프론트는 rooms 를
-- 구독하지 않으므로 아래를 실행해도 됩니다. 플레이어 깨우기는 room:{key} realtime.send 트리거가 담당합니다.
-- alter publication supabase_realtime drop table public.rooms;


-- =====================================================================
-- Clinic Signage v2.24.2 · PIN 무차별 대입 방어 보강 (권장)
--
-- 문제
--   기존 pin_login 은 브라우저가 보내는 p_client_id 기준으로만 5회 실패 잠금을 겁니다.
--   client_id 는 클라이언트가 마음대로 바꿀 수 있으므로, 요청마다 새 값을 보내면 잠금이 걸리지 않습니다.
--   스텝 PIN 4자리(1만 가지)는 수십 분 안에 전수 대입이 가능합니다.
--
-- 변경
--   - 기존 client_id 잠금(5회/5분)은 그대로 유지
--   - 요청 IP 기준 잠금 추가: 15분 안에 20회 실패 → 15분 잠금
--   - IP 헤더를 못 읽는 환경이면 'ip:unknown' 하나로 묶여 전역 잠금처럼 동작
--     (병원 내부 직원들은 보통 같은 공인 IP 를 쓰므로 정상 사용자의 오입력 몇 번은 영향 없음)
--   - PIN 원문/해시 처리, 세션 12시간, 반환 형식은 기존과 동일
--
-- 실행 전 현재 정의 백업:  select pg_get_functiondef('public.pin_login(text,text)'::regprocedure);
-- =====================================================================

create or replace function public.pin_request_ip()
returns text language sql stable security definer set search_path = public as $$
  select nullif(left(trim(coalesce(
           h->>'cf-connecting-ip',
           h->>'x-real-ip',
           split_part(coalesce(h->>'x-forwarded-for', ''), ',', 1)
         )), 64), '')
    from (select coalesce(nullif(current_setting('request.headers', true), ''), '{}')::jsonb as h) x;
$$;
revoke all on function public.pin_request_ip() from public, anon, authenticated;



-- =====================================================================
-- Required player control signal channel (canonical)
-- =====================================================================
-- Clinic Signage v2.21.10 — reliable player wake-up channel
-- Safe to rerun.
-- Root cause fixed: player pages use the anon role, while public.rooms and other control
-- tables are protected by member/admin RLS. Postgres Realtime therefore could not deliver
-- those row changes to anonymous players. A dedicated non-sensitive signal table is used
-- as the only canonical player wake-up stream.

create table if not exists public.player_control_signals (
  room_id uuid primary key references public.rooms(id) on delete cascade,
  revision bigint not null default 0,
  updated_at timestamptz not null default now()
);

alter table public.player_control_signals enable row level security;

drop policy if exists player_control_signals_read on public.player_control_signals;
drop policy if exists player_control_signals_read_disabled on public.player_control_signals;
create policy player_control_signals_read_disabled
  on public.player_control_signals
  for select
  to anon, authenticated
  using (false);

-- No direct INSERT/UPDATE/DELETE policy is intentionally provided. Writes only occur
-- through the SECURITY DEFINER function below after member/admin authorization.

insert into public.player_control_signals(room_id,revision,updated_at)
select r.id,0,now()
from public.rooms r
on conflict (room_id) do nothing;


-- canonical: earlier duplicate signal_signage_rooms removed; final definition appears below.



-- Realtime publication for the dedicated player-safe signal table.
do $$
begin
  if exists(select 1 from pg_publication where pubname='supabase_realtime')
     and not exists(
       select 1 from pg_publication_tables
       where pubname='supabase_realtime'
         and schemaname='public'
         and tablename='player_control_signals'
     ) then
    execute 'alter publication supabase_realtime add table public.player_control_signals';
  end if;
end $$;

-- Ensure future rooms get a signal row even before their first control action.
create or replace function public.ensure_player_control_signal()
returns trigger
language plpgsql
security definer
set search_path=public
as $$
begin
  insert into public.player_control_signals(room_id,revision,updated_at)
  values(new.id,0,now())
  on conflict (room_id) do nothing;
  return new;
end $$;

drop trigger if exists rooms_ensure_player_control_signal on public.rooms;
create trigger rooms_ensure_player_control_signal
after insert on public.rooms
for each row execute function public.ensure_player_control_signal();

-- ===== v2.27.0 canonical timed output =====
-- Clinic Signage v2.27.0 — timed hospital and per-room output
-- Safe to run repeatedly after v2.25.0+ canonical schema.

alter table public.broadcast add column if not exists starts_at timestamptz;
alter table public.broadcast add column if not exists ends_at timestamptz;
alter table public.rooms add column if not exists manual_starts_at timestamptz;
alter table public.rooms add column if not exists manual_ends_at timestamptz;

do $$ begin
  if not exists(select 1 from pg_constraint where conname='broadcast_time_window_check') then
    alter table public.broadcast add constraint broadcast_time_window_check check(ends_at is null or starts_at is null or ends_at>starts_at);
  end if;
  if not exists(select 1 from pg_constraint where conname='rooms_manual_time_window_check') then
    alter table public.rooms add constraint rooms_manual_time_window_check check(manual_ends_at is null or manual_starts_at is null or manual_ends_at>manual_starts_at);
  end if;
end $$;

create or replace function public.admin_set_broadcast(p_active boolean,p_video_ids uuid[],p_notice text default null,p_delay_ms int default 3000)
returns void language plpgsql security definer set search_path=public as $$
declare v_ids uuid[]; v_before jsonb; v_after jsonb;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  select to_jsonb(b) into v_before from public.broadcast b where id=1;
  if coalesce(p_active,false) then
    select coalesce(array_agg(v.id order by array_position(p_video_ids,v.id)),'{}'::uuid[]) into v_ids
    from public.videos v where v.id=any(coalesce(p_video_ids,'{}'::uuid[])) and v.active and (v.source<>'local' or v.available);
  else v_ids:=coalesce(p_video_ids,'{}'::uuid[]); end if;
  update public.broadcast set
    active=coalesce(p_active,false) and coalesce(array_length(v_ids,1),0)>0,
    video_ids=v_ids,notice_text=nullif(trim(coalesce(p_notice,'')),''),
    starts_at=null,ends_at=null,
    effective_at=case when coalesce(p_active,false) and coalesce(array_length(v_ids,1),0)>0 then clock_timestamp()+make_interval(secs=>greatest(0,least(coalesce(p_delay_ms,3000),10000))/1000.0) else null end,
    revision=revision+1,updated_at=clock_timestamp() where id=1;
  select to_jsonb(b) into v_after from public.broadcast b where id=1;
  insert into public.control_history(scope_type,action,label,before_state,after_state) values('hospital',case when p_active then 'start' else 'stop' end,'전체 병원',v_before,v_after);
end $$;

create or replace function public.admin_set_broadcast_timed(p_active boolean,p_video_ids uuid[],p_notice text default null,p_starts_at timestamptz default null,p_ends_at timestamptz default null)
returns void language plpgsql security definer set search_path=public as $$
declare v_ids uuid[]; v_before jsonb; v_after jsonb; v_start timestamptz;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  if p_starts_at is not null and p_ends_at is not null and p_ends_at<=p_starts_at then raise exception '종료시각은 시작시각 이후여야 합니다'; end if;
  if p_ends_at is not null and p_starts_at is null and p_ends_at<=clock_timestamp() then raise exception '종료시각은 현재 이후여야 합니다'; end if;
  select to_jsonb(b) into v_before from public.broadcast b where id=1;
  if coalesce(p_active,false) then
    select coalesce(array_agg(v.id order by array_position(p_video_ids,v.id)),'{}'::uuid[]) into v_ids from public.videos v
    where v.id=any(coalesce(p_video_ids,'{}'::uuid[])) and v.active and (v.source<>'local' or v.available);
  else v_ids:=coalesce(p_video_ids,'{}'::uuid[]); end if;
  v_start:=case when coalesce(p_active,false) then p_starts_at else null end;
  update public.broadcast set
    active=coalesce(p_active,false) and coalesce(array_length(v_ids,1),0)>0,video_ids=v_ids,notice_text=nullif(trim(coalesce(p_notice,'')),''),
    starts_at=v_start,ends_at=case when coalesce(p_active,false) then p_ends_at else null end,
    effective_at=case when coalesce(p_active,false) and coalesce(array_length(v_ids,1),0)>0 then coalesce(v_start,clock_timestamp()) else null end,
    revision=revision+1,updated_at=clock_timestamp() where id=1;
  select to_jsonb(b) into v_after from public.broadcast b where id=1;
  insert into public.control_history(scope_type,action,label,before_state,after_state) values('hospital',case when p_active then 'timed_start' else 'stop' end,'전체 병원',v_before,v_after);
end $$;

create or replace function public.admin_set_rooms_manual(p_rooms uuid[],p_video_ids uuid[],p_active boolean)
returns void language plpgsql security definer set search_path=public as $$
declare v_ids uuid[]; v_before jsonb; v_after jsonb; v_count int;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  if coalesce(array_length(p_rooms,1),0)=0 then return; end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'manual_active',r.manual_active,'manual_video_ids',r.manual_video_ids,'manual_starts_at',r.manual_starts_at,'manual_ends_at',r.manual_ends_at)),'[]'::jsonb),count(*) into v_before,v_count from public.rooms r where r.id=any(p_rooms);
  if p_active then
    select coalesce(array_agg(v.id order by array_position(p_video_ids,v.id)),'{}'::uuid[]) into v_ids from public.videos v
    where v.id=any(coalesce(p_video_ids,'{}'::uuid[])) and v.active and (v.source<>'local' or v.available);
  else v_ids:='{}'::uuid[]; end if;
  update public.rooms set manual_video_ids=v_ids,manual_active=p_active and coalesce(array_length(v_ids,1),0)>0,manual_starts_at=null,manual_ends_at=null,manual_updated_at=clock_timestamp() where id=any(p_rooms);
  select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'manual_active',r.manual_active,'manual_video_ids',r.manual_video_ids,'manual_starts_at',r.manual_starts_at,'manual_ends_at',r.manual_ends_at)),'[]'::jsonb) into v_after from public.rooms r where r.id=any(p_rooms);
  insert into public.control_history(scope_type,action,label,before_state,after_state) values('rooms',case when p_active then 'manual_start' else 'manual_clear' end,v_count||'개 공간',v_before,v_after);
end $$;

create or replace function public.admin_set_rooms_manual_timed(p_rooms uuid[],p_video_ids uuid[],p_active boolean,p_starts_at timestamptz default null,p_ends_at timestamptz default null)
returns void language plpgsql security definer set search_path=public as $$
declare v_ids uuid[]; v_before jsonb; v_after jsonb; v_count int;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  if coalesce(array_length(p_rooms,1),0)=0 then return; end if;
  if p_starts_at is not null and p_ends_at is not null and p_ends_at<=p_starts_at then raise exception '종료시각은 시작시각 이후여야 합니다'; end if;
  if p_ends_at is not null and p_starts_at is null and p_ends_at<=clock_timestamp() then raise exception '종료시각은 현재 이후여야 합니다'; end if;
  select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'manual_active',r.manual_active,'manual_video_ids',r.manual_video_ids,'manual_starts_at',r.manual_starts_at,'manual_ends_at',r.manual_ends_at)),'[]'::jsonb),count(*) into v_before,v_count from public.rooms r where r.id=any(p_rooms);
  if p_active then
    select coalesce(array_agg(v.id order by array_position(p_video_ids,v.id)),'{}'::uuid[]) into v_ids from public.videos v
    where v.id=any(coalesce(p_video_ids,'{}'::uuid[])) and v.active and (v.source<>'local' or v.available);
  else v_ids:='{}'::uuid[]; end if;
  update public.rooms set manual_video_ids=v_ids,manual_active=p_active and coalesce(array_length(v_ids,1),0)>0,
    manual_starts_at=case when p_active then p_starts_at else null end,manual_ends_at=case when p_active then p_ends_at else null end,manual_updated_at=clock_timestamp()
  where id=any(p_rooms);
  select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'manual_active',r.manual_active,'manual_video_ids',r.manual_video_ids,'manual_starts_at',r.manual_starts_at,'manual_ends_at',r.manual_ends_at)),'[]'::jsonb) into v_after from public.rooms r where r.id=any(p_rooms);
  insert into public.control_history(scope_type,action,label,before_state,after_state) values('rooms',case when p_active then 'manual_timed' else 'manual_clear' end,v_count||'개 공간',v_before,v_after);
end $$;

create or replace function public.player_get_state(p_key uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
declare
  r public.rooms; b public.broadcast; s public.app_settings; gb public.group_broadcasts; hs public.broadcast_schedules; gs public.broadcast_schedules;
  v_mode text; v_expires timestamptz; v_playlist jsonb:='[]'::jsonb; v_emergency jsonb; v_playlist_id uuid;
  v_notice text; v_effective timestamptz; v_revision text:='0'; v_next_transition timestamptz; v_operating jsonb; v_operating_end timestamptz;
begin
  select * into r from public.rooms where player_key=p_key; if not found then return null; end if;
  select * into b from public.broadcast where id=1; select * into s from public.app_settings where id=1;
  if coalesce(r.display_control_mode,'remote')='manual' then
    return jsonb_build_object('room',jsonb_build_object('id',r.id,'name',r.name,'group_id',r.group_id,'room_mode',r.room_mode,'force_mute',true,'volume',0,'paused',true,'overlay_text',null,'reload_nonce',r.reload_nonce),'mode','closed','priority','manual','manual_control',true,'playlist','[]'::jsonb,'emergency_video',null,'operating',jsonb_build_object('active',false,'reason','manual_display'),'sync_revision','manual:'||r.id::text,'next_transition_at',null,'media_server_url',coalesce(s.media_server_url,''),'server_time',clock_timestamp());
  end if;
  v_operating:=public.signage_room_operating_status(r.id,clock_timestamp());
  if coalesce((v_operating->>'active')::boolean,false)=false then
    return jsonb_build_object('room',jsonb_build_object('id',r.id,'name',r.name,'group_id',r.group_id,'room_mode',r.room_mode,'force_mute',r.force_mute,'volume',r.volume,'paused',r.paused,'overlay_text',r.overlay_text,'reload_nonce',r.reload_nonce),'mode','closed','priority','closed','playlist','[]'::jsonb,'emergency_video',null,'operating',v_operating,'sync_revision','closed:'||coalesce(v_operating->>'next_start_at','none'),'next_transition_at',v_operating->>'next_start_at','media_server_url',coalesce(s.media_server_url,''),'server_time',clock_timestamp());
  end if;
  v_operating_end:=nullif(v_operating->>'current_end_at','')::timestamptz;
  if r.group_id is not null then select * into gb from public.group_broadcasts where group_id=r.group_id; end if;
  select * into hs from public.broadcast_schedules x where x.enabled and x.scope_type='hospital' and x.starts_at<=clock_timestamp() and x.ends_at>clock_timestamp() order by x.starts_at desc limit 1;
  if r.group_id is not null then select * into gs from public.broadcast_schedules x where x.enabled and x.scope_type='group' and x.group_id=r.group_id and x.starts_at<=clock_timestamp() and x.ends_at>clock_timestamp() order by x.starts_at desc limit 1; end if;
  select min(t) into v_next_transition from (
    select starts_at t from public.broadcast_schedules x where x.enabled and x.starts_at>clock_timestamp() and (x.scope_type='hospital' or (x.scope_type='group' and x.group_id=r.group_id))
    union all select ends_at t from public.broadcast_schedules x where x.enabled and x.ends_at>clock_timestamp() and (x.scope_type='hospital' or (x.scope_type='group' and x.group_id=r.group_id))
    union all select b.starts_at where b.active and b.starts_at is not null and b.starts_at>clock_timestamp()
    union all select b.ends_at where b.active and b.ends_at is not null and b.ends_at>clock_timestamp()
    union all select r.manual_starts_at where r.manual_active and r.manual_starts_at is not null and r.manual_starts_at>clock_timestamp()
    union all select r.manual_ends_at where r.manual_active and r.manual_ends_at is not null and r.manual_ends_at>clock_timestamp()
    union all select starts_at t from public.room_video_rules rr where rr.room_id=r.id and rr.starts_at>clock_timestamp()
    union all select ends_at t from public.room_video_rules rr where rr.room_id=r.id and rr.ends_at>clock_timestamp()
  ) q;
  if v_operating_end is not null and (v_next_transition is null or v_operating_end<v_next_transition) then v_next_transition:=v_operating_end; end if;
  if r.session_started_at is not null and r.session_timeout_min>0 then v_expires:=r.session_started_at+make_interval(mins=>r.session_timeout_min); end if;

  if b.active and (b.starts_at is null or b.starts_at<=clock_timestamp()) and (b.ends_at is null or b.ends_at>clock_timestamp()) and coalesce(array_length(b.video_ids,1),0)>0 then
    select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'title',v.title,'source',v.source,'file_path',v.file_path,'url',v.url,'size',v.size_bytes,'file_modified_at',v.file_modified_at,'thumbnail',v.thumbnail_data_url) order by array_position(b.video_ids,v.id)),'[]'::jsonb) into v_playlist from public.videos v where v.id=any(b.video_ids) and v.active and (v.source<>'local' or v.available);
    if jsonb_array_length(v_playlist)>0 then v_mode:='broadcast';v_notice:=b.notice_text;v_effective:=b.effective_at;v_revision:='b:'||b.revision; end if;
  end if;
  if v_mode is null and hs.id is not null then
    select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'title',v.title,'source',v.source,'file_path',v.file_path,'url',v.url,'size',v.size_bytes,'file_modified_at',v.file_modified_at,'thumbnail',v.thumbnail_data_url) order by array_position(hs.video_ids,v.id)),'[]'::jsonb) into v_playlist from public.videos v where v.id=any(hs.video_ids) and v.active and (v.source<>'local' or v.available);
    if jsonb_array_length(v_playlist)>0 then v_mode:='broadcast_schedule';v_notice:=hs.notice_text;v_effective:=hs.starts_at;v_revision:='hs:'||hs.id::text||':'||extract(epoch from hs.starts_at)::bigint; end if;
  end if;
  if v_mode is null and r.manual_active and (r.manual_starts_at is null or r.manual_starts_at<=clock_timestamp()) and (r.manual_ends_at is null or r.manual_ends_at>clock_timestamp()) and coalesce(array_length(r.manual_video_ids,1),0)>0 then
    select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'title',v.title,'source',v.source,'file_path',v.file_path,'url',v.url,'size',v.size_bytes,'file_modified_at',v.file_modified_at,'thumbnail',v.thumbnail_data_url) order by array_position(r.manual_video_ids,v.id)),'[]'::jsonb) into v_playlist from public.videos v where v.id=any(r.manual_video_ids) and v.active and (v.source<>'local' or v.available);
    if jsonb_array_length(v_playlist)>0 then v_mode:='manual';v_revision:='m:'||coalesce(extract(epoch from r.manual_updated_at)::bigint,0); end if;
  end if;
  if v_mode is null and gb.group_id is not null and gb.active and coalesce(array_length(gb.video_ids,1),0)>0 then
    select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'title',v.title,'source',v.source,'file_path',v.file_path,'url',v.url,'size',v.size_bytes,'file_modified_at',v.file_modified_at,'thumbnail',v.thumbnail_data_url) order by array_position(gb.video_ids,v.id)),'[]'::jsonb) into v_playlist from public.videos v where v.id=any(gb.video_ids) and v.active and (v.source<>'local' or v.available);
    if jsonb_array_length(v_playlist)>0 then v_mode:='group';v_notice:=gb.notice_text;v_effective:=gb.effective_at;v_revision:='g:'||gb.revision; end if;
  end if;
  if v_mode is null and gs.id is not null then
    select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'title',v.title,'source',v.source,'file_path',v.file_path,'url',v.url,'size',v.size_bytes,'file_modified_at',v.file_modified_at,'thumbnail',v.thumbnail_data_url) order by array_position(gs.video_ids,v.id)),'[]'::jsonb) into v_playlist from public.videos v where v.id=any(gs.video_ids) and v.active and (v.source<>'local' or v.available);
    if jsonb_array_length(v_playlist)>0 then v_mode:='group_schedule';v_notice:=gs.notice_text;v_effective:=gs.starts_at;v_revision:='gs:'||gs.id::text||':'||extract(epoch from gs.starts_at)::bigint; end if;
  end if;

  if v_mode is null and r.room_mode in ('treatment','consultation') and r.session_treatment is not null and r.session_started_at is not null and (v_expires is null or v_expires>clock_timestamp()) then
    select p.id into v_playlist_id from public.playlists p where p.active and p.kind='patient' and (p.site_id is null or p.site_id=r.site_id)
      and (coalesce(array_length(p.target_treatment,1),0)=0 or r.session_treatment=any(p.target_treatment))
      and (coalesce(array_length(p.target_age,1),0)=0 or (r.session_age_group is not null and r.session_age_group=any(p.target_age)))
      and (coalesce(array_length(p.target_gender,1),0)=0 or (r.session_gender is not null and r.session_gender=any(p.target_gender)))
    order by (case when p.site_id=r.site_id then 1000 else 0 end + case when coalesce(array_length(p.target_treatment,1),0)>0 then 100 else 0 end + case when coalesce(array_length(p.target_age,1),0)>0 then 10 else 0 end + case when coalesce(array_length(p.target_gender,1),0)>0 then 5 else 0 end) desc,p.sort_order,p.created_at limit 1;
    if v_playlist_id is not null then
      select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'title',v.title,'source',v.source,'file_path',v.file_path,'url',v.url,'size',v.size_bytes,'file_modified_at',v.file_modified_at,'thumbnail',v.thumbnail_data_url) order by pi.sort_order,pi.created_at),'[]'::jsonb) into v_playlist from public.playlist_items pi join public.videos v on v.id=pi.video_id where pi.playlist_id=v_playlist_id and v.active and (v.site_id is null or v.site_id=r.site_id) and (v.source<>'local' or v.available);
      if jsonb_array_length(v_playlist)>0 then v_mode:='patient';v_revision:='pp:'||v_playlist_id::text||':'||coalesce(extract(epoch from r.session_started_at)::bigint,0); end if;
    end if;
    if v_mode is null then
      with candidates as (select v.*,(case when coalesce(array_length(v.target_treatment,1),0)>0 then 100 else 0 end + case when coalesce(array_length(v.target_age,1),0)>0 then 10 else 0 end + case when coalesce(array_length(v.target_gender,1),0)>0 then 5 else 0 end) score from public.videos v where v.active and (v.site_id is null or v.site_id=r.site_id) and (v.source<>'local' or v.available) and (coalesce(array_length(v.target_treatment,1),0)=0 or r.session_treatment=any(v.target_treatment)) and (coalesce(array_length(v.target_age,1),0)=0 or (r.session_age_group is not null and r.session_age_group=any(v.target_age))) and (coalesce(array_length(v.target_gender,1),0)=0 or (r.session_gender is not null and r.session_gender=any(v.target_gender)))), best as (select max(score) score from candidates)
      select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'title',c.title,'source',c.source,'file_path',c.file_path,'url',c.url,'size',c.size_bytes,'file_modified_at',c.file_modified_at) order by c.sort_order,c.created_at),'[]'::jsonb) into v_playlist from candidates c cross join best where c.score=best.score;
      if jsonb_array_length(v_playlist)>0 then v_mode:='patient';v_revision:='legacy-p:'||coalesce(extract(epoch from r.session_started_at)::bigint,0); end if;
    end if;
  end if;

  if v_mode is null then
    v_mode:='default';v_expires:=null;
    v_playlist_id:=r.default_playlist_id;
    if v_playlist_id is null and r.group_id is not null then select default_playlist_id into v_playlist_id from public.signage_groups where id=r.group_id; end if;
    if v_playlist_id is null then select id into v_playlist_id from public.playlists where active and kind='default' and (site_id is null or site_id=r.site_id) order by coalesce(site_id=r.site_id,false) desc,sort_order,created_at limit 1; end if;
    if v_playlist_id is not null then select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'title',v.title,'source',v.source,'file_path',v.file_path,'url',v.url,'size',v.size_bytes,'file_modified_at',v.file_modified_at,'thumbnail',v.thumbnail_data_url) order by pi.sort_order,pi.created_at),'[]'::jsonb) into v_playlist from public.playlist_items pi join public.videos v on v.id=pi.video_id where pi.playlist_id=v_playlist_id and v.active and (v.site_id is null or v.site_id=r.site_id) and (v.source<>'local' or v.available); end if;
    if jsonb_array_length(v_playlist)=0 then select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'title',v.title,'source',v.source,'file_path',v.file_path,'url',v.url,'size',v.size_bytes,'file_modified_at',v.file_modified_at,'thumbnail',v.thumbnail_data_url) order by v.sort_order,v.created_at),'[]'::jsonb) into v_playlist from public.videos v where v.active and (v.site_id is null or v.site_id=r.site_id) and (v.source<>'local' or v.available) and v.tags&&r.default_tags; end if;
    v_revision:='d:'||coalesce(v_playlist_id::text,'legacy');
  end if;
  if v_mode in ('manual','patient','default') then
    v_playlist:=public.apply_room_video_rules(r.id,v_playlist);
    v_revision:=v_revision||':rr:'||coalesce((select extract(epoch from max(updated_at))::bigint::text from public.room_video_rules where room_id=r.id),'0');
  end if;
  if s.emergency_video_id is not null then select jsonb_build_object('id',v.id,'title',v.title,'source',v.source,'file_path',v.file_path,'url',v.url,'size',v.size_bytes,'file_modified_at',v.file_modified_at,'thumbnail',v.thumbnail_data_url) into v_emergency from public.videos v where v.id=s.emergency_video_id and v.active and (v.source<>'local' or v.available); end if;
  return jsonb_build_object('room',jsonb_build_object('id',r.id,'name',r.name,'group_id',r.group_id,'room_mode',r.room_mode,'force_mute',r.force_mute,'volume',r.volume,'paused',r.paused,'overlay_text',r.overlay_text,'reload_nonce',r.reload_nonce),'mode',v_mode,'priority',v_mode,'operating',v_operating,'session_expires_at',case when v_mode='patient' then v_expires end,'notice_text',v_notice,'playlist',v_playlist,'emergency_video',v_emergency,'sync_effective_at',v_effective,'sync_revision',v_revision,'next_transition_at',v_next_transition,'media_server_url',coalesce(s.media_server_url,''),'server_time',clock_timestamp());
end $$;


create or replace function public.admin_add_room_video(p_room uuid,p_video uuid)
returns void language plpgsql security definer set search_path=public as $$
declare
  r public.rooms; v_ids uuid[]; v_title text; v_playlist uuid; v_before jsonb; v_keep_window boolean;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  select * into r from public.rooms where id=p_room for update;
  if not found then raise exception '공간을 찾을 수 없습니다'; end if;
  select title into v_title from public.videos where id=p_video and active and (source<>'local' or available);
  if v_title is null then raise exception '사용 가능한 영상이 아닙니다'; end if;
  v_keep_window:=r.manual_active and (r.manual_ends_at is null or r.manual_ends_at>clock_timestamp());
  v_before:=jsonb_build_object('manual_active',r.manual_active,'manual_video_ids',r.manual_video_ids,'manual_starts_at',r.manual_starts_at,'manual_ends_at',r.manual_ends_at,'default_playlist_id',r.default_playlist_id);
  if v_keep_window and coalesce(array_length(r.manual_video_ids,1),0)>0 then
    v_ids:=r.manual_video_ids;
  else
    v_playlist:=r.default_playlist_id;
    if v_playlist is null then select id into v_playlist from public.playlists where active and kind='default' order by sort_order,created_at limit 1; end if;
    select coalesce(array_agg(v.id order by pi.sort_order,pi.created_at),'{}'::uuid[]) into v_ids
      from public.playlist_items pi join public.videos v on v.id=pi.video_id
     where pi.playlist_id=v_playlist and v.active and (v.source<>'local' or v.available);
  end if;
  if not (p_video=any(coalesce(v_ids,'{}'::uuid[]))) then v_ids:=array_append(coalesce(v_ids,'{}'::uuid[]),p_video); end if;
  update public.rooms set manual_video_ids=v_ids,manual_active=true,
    manual_starts_at=case when v_keep_window then r.manual_starts_at else null end,
    manual_ends_at=case when v_keep_window then r.manual_ends_at else null end,
    manual_updated_at=clock_timestamp() where id=p_room;
  insert into public.control_history(scope_type,scope_id,action,label,before_state,after_state)
  values('rooms',p_room,'video_add',v_title,v_before,(select jsonb_build_object('manual_active',manual_active,'manual_video_ids',manual_video_ids,'manual_starts_at',manual_starts_at,'manual_ends_at',manual_ends_at,'default_playlist_id',default_playlist_id) from public.rooms where id=p_room));
end $$;

revoke all on function public.admin_set_broadcast_timed(boolean,uuid[],text,timestamptz,timestamptz) from public;
revoke all on function public.admin_set_rooms_manual_timed(uuid[],uuid[],boolean,timestamptz,timestamptz) from public;
grant execute on function public.admin_set_broadcast_timed(boolean,uuid[],text,timestamptz,timestamptz) to anon,authenticated;
grant execute on function public.admin_set_rooms_manual_timed(uuid[],uuid[],boolean,timestamptz,timestamptz) to anon,authenticated;



-- =====================================================================
-- Clinic Signage v2.29.1 · operating schedule, low-activity, health canonical additions
-- Safe to rerun. Existing player_report / signage_live_status / ACK / frame-presence remain intact.
-- =====================================================================
alter table public.app_settings add column if not exists early_closed_date date;
alter table public.rooms add column if not exists operating_override boolean not null default false;
alter table public.rooms add column if not exists operating_weekday_enabled boolean not null default true;
alter table public.rooms add column if not exists operating_weekday_start time not null default '09:00';
alter table public.rooms add column if not exists operating_weekday_end time not null default '20:00';
alter table public.rooms add column if not exists operating_saturday_enabled boolean not null default true;
alter table public.rooms add column if not exists operating_saturday_start time not null default '09:00';
alter table public.rooms add column if not exists operating_saturday_end time not null default '17:00';
alter table public.rooms add column if not exists operating_sunday_enabled boolean not null default false;
alter table public.rooms add column if not exists operating_sunday_start time not null default '09:00';
alter table public.rooms add column if not exists operating_sunday_end time not null default '17:00';

create or replace function public.signage_room_operating_window(p_room uuid,p_day date)
returns table(is_open boolean,start_time time,end_time time,planned_seconds int)
language plpgsql stable security definer set search_path=public as $$
declare r public.rooms; s public.app_settings; dow int;
begin
  select * into r from public.rooms where id=p_room;
  if r.id is null then is_open:=false;start_time:='00:00';end_time:='00:00';planned_seconds:=0;return next;return;end if;
  select * into s from public.app_settings where id=1;
  dow:=extract(isodow from p_day)::int;
  if r.operating_override then
    if dow between 1 and 5 then is_open:=r.operating_weekday_enabled;start_time:=r.operating_weekday_start;end_time:=r.operating_weekday_end;
    elsif dow=6 then is_open:=r.operating_saturday_enabled;start_time:=r.operating_saturday_start;end_time:=r.operating_saturday_end;
    else is_open:=r.operating_sunday_enabled;start_time:=r.operating_sunday_start;end_time:=r.operating_sunday_end; end if;
  else
    if dow between 1 and 5 then is_open:=s.operating_weekday_enabled;start_time:=s.operating_weekday_start;end_time:=s.operating_weekday_end;
    elsif dow=6 then is_open:=s.operating_saturday_enabled;start_time:=s.operating_saturday_start;end_time:=s.operating_saturday_end;
    else is_open:=s.operating_sunday_enabled;start_time:=s.operating_sunday_start;end_time:=s.operating_sunday_end; end if;
  end if;
  if s.early_closed_date=p_day then is_open:=false; end if;
  if not coalesce(is_open,false) or start_time is null or end_time is null or end_time<=start_time then is_open:=false;planned_seconds:=0;
  else planned_seconds:=extract(epoch from (end_time-start_time))::int;end if;
  return next;
end $$;

create or replace function public.signage_room_operating_status(p_room uuid,p_at timestamptz default clock_timestamp())
returns jsonb language plpgsql stable security definer set search_path=public as $$
declare local_now timestamp:=p_at at time zone 'Asia/Seoul'; d date; t time; w record; active boolean:=false; next_start timestamptz; current_end timestamptz; current_start time; current_end_time time; i int;
begin
  d:=local_now::date;t:=local_now::time;
  select * into w from public.signage_room_operating_window(p_room,d);
  active:=coalesce(w.is_open,false) and t>=w.start_time and t<w.end_time;
  current_start:=w.start_time;current_end_time:=w.end_time;
  if active then current_end:=((d+current_end_time) at time zone 'Asia/Seoul'); end if;
  for i in 0..8 loop
    select * into w from public.signage_room_operating_window(p_room,d+i);
    if w.is_open then
      if i>0 or t<w.start_time then next_start:=(((d+i)+w.start_time) at time zone 'Asia/Seoul');exit;end if;
    end if;
  end loop;
  return jsonb_build_object('active',active,'start_time',case when active then to_char(local_now::date+current_start,'HH24:MI') else null end,'end_time',case when active then to_char(local_now::date+current_end_time,'HH24:MI') else null end,'current_end_at',current_end,'next_start_at',next_start,'low_activity',not active);
end $$;

create or replace function public.admin_close_today()
returns void language plpgsql security definer set search_path=public as $$
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  update public.app_settings set early_closed_date=(clock_timestamp() at time zone 'Asia/Seoul')::date,updated_at=clock_timestamp() where id=1;
  perform public.signal_signage_rooms(null,null,true);
end $$;
create or replace function public.admin_reopen_today()
returns void language plpgsql security definer set search_path=public as $$
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  update public.app_settings set early_closed_date=null,updated_at=clock_timestamp() where id=1;
  perform public.signal_signage_rooms(null,null,true);
end $$;

create or replace function public.admin_prune_signage_logs(p_event_days int default 30,p_daily_days int default 400)
returns jsonb language plpgsql security definer set search_path=public as $$
declare removed_events bigint:=0;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  p_event_days:=greatest(7,least(coalesce(p_event_days,30),365));
  delete from public.player_events where occurred_at<clock_timestamp()-make_interval(days=>p_event_days);
  get diagnostics removed_events=row_count;
  -- room_playback_daily is aggregate/statistical data and is intentionally retained long-term.
  return jsonb_build_object('player_events_deleted',removed_events,'playback_daily_deleted',0,'event_days',p_event_days,'daily_retention','long_term');
end $$;

revoke all on function public.signage_room_operating_window(uuid,date) from public;
revoke all on function public.signage_room_operating_status(uuid,timestamptz) from public;
revoke all on function public.admin_close_today() from public;
revoke all on function public.admin_reopen_today() from public;
revoke all on function public.admin_prune_signage_logs(int,int) from public;
grant execute on function public.signage_room_operating_window(uuid,date) to anon,authenticated;
