-- Clinic Signage v2.34.32 · canonical runtime repairs
-- Clinic Signage v2.34.32 · hospital runtime / canonical install repairs

-- 1) Building asset support must exist on both upgraded and fresh installs.
alter table public.site_settings add column if not exists building_asset jsonb;
update public.site_settings set building_asset=coalesce(building_asset,'{}'::jsonb);
alter table public.site_settings alter column building_asset set default '{}'::jsonb;
alter table public.site_settings alter column building_asset set not null;

create or replace function public.hospital_building_asset(p_site uuid)
returns jsonb language plpgsql stable security definer set search_path=public as $$
declare v_site uuid; v_asset jsonb;
begin
  if not public.is_member() then raise exception 'not allowed'; end if;
  v_site:=case when public.is_admin() then p_site else public.pin_session_site_id() end;
  if v_site is null or not public.can_manage_site(v_site) then raise exception 'not allowed'; end if;
  select coalesce(building_asset,'{}'::jsonb) into v_asset from public.site_settings where site_id=v_site;
  return coalesce(v_asset,'{}'::jsonb);
end $$;
revoke all on function public.hospital_building_asset(uuid) from public;
grant execute on function public.hospital_building_asset(uuid) to anon,authenticated;

create or replace function public.hospital_set_building_asset(p_site uuid,p_asset jsonb)
returns void language plpgsql security definer set search_path=public as $$
begin
  if not public.can_manage_site(p_site) then raise exception 'not allowed'; end if;
  insert into public.site_settings(site_id,building_asset,updated_at)
  values(p_site,coalesce(p_asset,'{}'::jsonb),clock_timestamp())
  on conflict(site_id) do update set building_asset=excluded.building_asset,updated_at=clock_timestamp();
end $$;
revoke all on function public.hospital_set_building_asset(uuid,jsonb) from public;
grant execute on function public.hospital_set_building_asset(uuid,jsonb) to anon,authenticated;

-- 2) Normalize legacy TIME::text values (HH:MM:SS) to the UI/API contract (HH:MM).
update public.site_settings
set operating_config = jsonb_strip_nulls(operating_config || jsonb_build_object(
  'weekday_start', case when coalesce(operating_config->>'weekday_start','') ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9](?:[.][0-9]+)?)?$' then left(operating_config->>'weekday_start',5) else operating_config->>'weekday_start' end,
  'weekday_end', case when coalesce(operating_config->>'weekday_end','') ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9](?:[.][0-9]+)?)?$' then left(operating_config->>'weekday_end',5) else operating_config->>'weekday_end' end,
  'saturday_start', case when coalesce(operating_config->>'saturday_start','') ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9](?:[.][0-9]+)?)?$' then left(operating_config->>'saturday_start',5) else operating_config->>'saturday_start' end,
  'saturday_end', case when coalesce(operating_config->>'saturday_end','') ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9](?:[.][0-9]+)?)?$' then left(operating_config->>'saturday_end',5) else operating_config->>'saturday_end' end,
  'sunday_start', case when coalesce(operating_config->>'sunday_start','') ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9](?:[.][0-9]+)?)?$' then left(operating_config->>'sunday_start',5) else operating_config->>'sunday_start' end,
  'sunday_end', case when coalesce(operating_config->>'sunday_end','') ~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9](?:[.][0-9]+)?)?$' then left(operating_config->>'sunday_end',5) else operating_config->>'sunday_end' end
)), updated_at=clock_timestamp()
where operating_config is not null;

create or replace function public.hospital_save_operating_config(p_site uuid,p_config jsonb)
returns void language plpgsql security definer set search_path=public as $$
declare c jsonb; oldc jsonb; k text; v text;
begin
  if not public.can_manage_site(p_site) then raise exception 'not allowed'; end if;
  foreach k in array array['weekday_start','weekday_end','saturday_start','saturday_end','sunday_start','sunday_end'] loop
    v:=coalesce(p_config->>k,'');
    if v !~ '^(?:[01][0-9]|2[0-3]):[0-5][0-9](?::[0-5][0-9](?:[.][0-9]+)?)?$' then raise exception '% must be HH:MM',k; end if;
    p_config:=jsonb_set(p_config,array[k],to_jsonb(left(v,5)),true);
  end loop;
  foreach k in array array['weekday_enabled','saturday_enabled','sunday_enabled'] loop
    v:=lower(coalesce(p_config->>k,'')); if v not in ('true','false') then raise exception '% must be boolean',k; end if;
  end loop;
  select coalesce(operating_config,'{}'::jsonb) into oldc from public.site_settings where site_id=p_site;
  c:=jsonb_strip_nulls(jsonb_build_object(
    'weekday_enabled',(p_config->>'weekday_enabled')::boolean,'weekday_start',p_config->>'weekday_start','weekday_end',p_config->>'weekday_end',
    'saturday_enabled',(p_config->>'saturday_enabled')::boolean,'saturday_start',p_config->>'saturday_start','saturday_end',p_config->>'saturday_end',
    'sunday_enabled',(p_config->>'sunday_enabled')::boolean,'sunday_start',p_config->>'sunday_start','sunday_end',p_config->>'sunday_end',
    'early_closed_date',coalesce(nullif(p_config->>'early_closed_date',''),nullif(oldc->>'early_closed_date','')),
    'emergency_video_id',nullif(p_config->>'emergency_video_id','')
  ));
  insert into public.site_settings(site_id,operating_config,updated_at) values(p_site,c,clock_timestamp())
  on conflict(site_id) do update set operating_config=excluded.operating_config,updated_at=clock_timestamp();
  perform public.signal_site_rooms(p_site);
end $$;
revoke all on function public.hospital_save_operating_config(uuid,jsonb) from public;
grant execute on function public.hospital_save_operating_config(uuid,jsonb) to anon,authenticated;

insert into public.schema_version(version,applied_at)
values('2.34.32',clock_timestamp())
on conflict(version) do update set applied_at=excluded.applied_at;

notify pgrst,'reload schema';

-- Clinic Signage v2.34.42
-- Copy floor-space geometry and display map positions. Positioned source displays map by order; missing target displays are auto-created.
create or replace function public.hospital_copy_floor_layout(
  p_site uuid,
  p_source_group uuid,
  p_target_groups uuid[],
  p_copy_spaces boolean default true,
  p_copy_displays boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
  v_target uuid;
  v_target_name text;
  v_spaces_copied boolean;
  v_displays_copied boolean;
  v_displays_created integer;
  v_displays_updated integer;
  v_applied jsonb := '[]'::jsonb;
  v_skipped jsonb := '[]'::jsonb;
  v_prefix text;
  v_source_count integer;
  v_source record;
  v_target_room_id uuid;
  v_target_match_count integer;
  v_target_display_name text;
  v_duplicate_key text;
begin
  if p_site is null or p_source_group is null or coalesce(array_length(p_target_groups,1),0)=0 then
    raise exception 'INVALID_ARGUMENT';
  end if;
  if public.pin_session_role() not in ('admin','staff') or not public.can_manage_site(p_site) then
    raise exception 'not allowed';
  end if;
  if not exists(select 1 from public.signage_groups g where g.id=p_source_group and g.site_id=p_site) then
    raise exception 'SOURCE_FLOOR_NOT_FOUND';
  end if;
  if coalesce(p_copy_spaces,false)=false and coalesce(p_copy_displays,false)=false then
    raise exception 'NOTHING_TO_COPY';
  end if;

  if p_copy_displays then
    select count(*) into v_source_count
    from public.rooms r
    where r.site_id=p_site and r.group_id=p_source_group
      and r.map_x_pct is not null and r.map_y_pct is not null;

    select x.slot_key into v_duplicate_key
    from (
      select regexp_replace(lower(trim(r.name)), '^[^_]+_', '') as slot_key, count(*) as cnt
      from public.rooms r
      where r.site_id=p_site and r.group_id=p_source_group
        and r.map_x_pct is not null and r.map_y_pct is not null
      group by 1
      having count(*)>1
      limit 1
    ) x;
    if v_duplicate_key is not null then
      raise exception 'DUPLICATE_SOURCE_DISPLAY_KEY:%',v_duplicate_key;
    end if;
  else
    v_source_count:=0;
  end if;

  foreach v_target in array p_target_groups loop
    if v_target=p_source_group then continue; end if;

    select g.name into v_target_name
    from public.signage_groups g
    where g.id=v_target and g.site_id=p_site;

    if v_target_name is null then
      v_skipped:=v_skipped||jsonb_build_array(
        jsonb_build_object('id',v_target,'name','알 수 없는 층','reason','TARGET_FLOOR_NOT_FOUND')
      );
      continue;
    end if;

    v_spaces_copied:=false;
    v_displays_copied:=false;
    v_displays_created:=0;
    v_displays_updated:=0;

    if p_copy_spaces then
      delete from public.floor_spaces
      where site_id=p_site and group_id=v_target;

      insert into public.floor_spaces(
        site_id,group_id,name,space_type,x_pct,y_pct,width_pct,height_pct,sort_order
      )
      select p_site,v_target,fs.name,fs.space_type,fs.x_pct,fs.y_pct,fs.width_pct,fs.height_pct,fs.sort_order
      from public.floor_spaces fs
      where fs.site_id=p_site and fs.group_id=p_source_group
      order by fs.sort_order,fs.created_at;

      v_spaces_copied:=true;
    end if;

    if p_copy_displays then
      if v_source_count=0 then
        v_skipped:=v_skipped||jsonb_build_array(
          jsonb_build_object(
            'id',v_target,'name',v_target_name,'reason','SOURCE_HAS_NO_POSITIONED_DISPLAYS',
            'spaces_copied',v_spaces_copied,'displays_copied',false
          )
        );
      else
        v_prefix:=regexp_replace(v_target_name,'[[:space:]]+','','g');

        select x.slot_key into v_duplicate_key
        from (
          select regexp_replace(lower(trim(r.name)), '^[^_]+_', '') as slot_key, count(*) as cnt
          from public.rooms r
          where r.site_id=p_site and r.group_id=v_target
          group by 1
          having count(*)>1
          limit 1
        ) x;
        if v_duplicate_key is not null then
          raise exception 'DUPLICATE_TARGET_DISPLAY_KEY:%:%',v_target_name,v_duplicate_key;
        end if;

        for v_source in
          select r.id,r.name,r.sort_order,r.map_x_pct,r.map_y_pct,r.display_control_mode,
                 regexp_replace(lower(trim(r.name)), '^[^_]+_', '') as slot_key,
                 regexp_replace(trim(r.name), '^[^_]+_', '') as slot_label
          from public.rooms r
          where r.site_id=p_site and r.group_id=p_source_group
            and r.map_x_pct is not null and r.map_y_pct is not null
          order by r.name,r.created_at,r.id
        loop
          select count(*),(array_agg(r.id order by r.id))[1] into v_target_match_count,v_target_room_id
          from public.rooms r
          where r.site_id=p_site and r.group_id=v_target
            and regexp_replace(lower(trim(r.name)), '^[^_]+_', '')=v_source.slot_key;

          if v_target_match_count>1 then
            raise exception 'DUPLICATE_TARGET_DISPLAY_KEY:%:%',v_target_name,v_source.slot_key;
          elsif v_target_match_count=0 then
            v_target_display_name:=case
              when position('_' in trim(v_source.name))>0 then v_prefix||'_'||v_source.slot_label
              else v_prefix||'_'||trim(v_source.name)
            end;

            insert into public.rooms(
              site_id,group_id,name,sort_order,display_control_mode,manual_check_status,map_x_pct,map_y_pct
            ) values(
              p_site,v_target,v_target_display_name,v_source.sort_order,
              coalesce(v_source.display_control_mode,'remote'),
              case when coalesce(v_source.display_control_mode,'remote')='manual' then 'needs_check' else 'not_required' end,
              v_source.map_x_pct,v_source.map_y_pct
            ) returning id into v_target_room_id;
            v_displays_created:=v_displays_created+1;
          else
            update public.rooms r
            set map_x_pct=v_source.map_x_pct,map_y_pct=v_source.map_y_pct,floor_space_id=v_target_space_id
            where r.id=v_target_room_id;
            v_displays_updated:=v_displays_updated+1;
          end if;
        end loop;

        v_displays_copied:=true;
      end if;
    end if;

    if v_spaces_copied or v_displays_copied then
      perform public.audit_event(
        p_site,'update','floor_layout',v_target::text,'층 도면 배치 복사',
        null,jsonb_build_object(
          'source_group',p_source_group,'target_group',v_target,
          'spaces_copied',v_spaces_copied,'displays_copied',v_displays_copied,
          'displays_created',v_displays_created,'displays_updated',v_displays_updated,
          'display_match','name_slot_key'
        )
      );
      v_applied:=v_applied||jsonb_build_array(
        jsonb_build_object(
          'id',v_target,'name',v_target_name,
          'spaces_copied',v_spaces_copied,'displays_copied',v_displays_copied,
          'displays_created',v_displays_created,'displays_updated',v_displays_updated,
          'display_match','name_slot_key'
        )
      );
    end if;
  end loop;

  return jsonb_build_object('ok',true,'applied',v_applied,'skipped',v_skipped);
end
$$;

revoke all on function public.hospital_copy_floor_layout(uuid,uuid,uuid[],boolean,boolean) from public;
grant execute on function public.hospital_copy_floor_layout(uuid,uuid,uuid[],boolean,boolean) to anon,authenticated;

