on conflict(version) do update set applied_at=excluded.applied_at;
notify pgrst, 'reload schema';
commit;

-- Clinic Signage v2.34.56 — physical floor integrity + canonical display position save
begin;

-- A hospital floor must exist independently from whether a content strategy was configured.


-- Floor metadata is configured per hospital; no demonstration floors are inserted.

-- Position saving must canonicalize the display to the selected physical floor in the same statement.
drop function if exists public.staff_set_display_setup(uuid,text,numeric,numeric,text,uuid);
drop function if exists public.staff_set_display_setup(uuid,text,numeric,numeric,text,uuid,uuid);
create or replace function public.staff_set_display_setup(
  p_room uuid,
  p_mode text,
  p_x numeric,
  p_y numeric,
  p_note text default null,
  p_space uuid default null,
  p_group uuid default null
)
returns void language plpgsql security definer set search_path=public as $$
declare
  v_site uuid:=coalesce(public.pin_session_site_id(),public.default_site_id());
  v_before jsonb;
  v_after jsonb;
  v_current_group uuid;
  v_target_group uuid;
  v_room_site uuid;
begin
  if public.pin_session_role() not in ('admin','staff') or p_mode not in ('remote','manual','hybrid') then
    raise exception 'not allowed';
  end if;

  select to_jsonb(r),r.group_id,r.site_id
    into v_before,v_current_group,v_room_site
  from public.rooms r
  where r.id=p_room and r.site_id=v_site;

  if v_before is null and public.is_admin() then
    select to_jsonb(r),r.group_id,r.site_id
      into v_before,v_current_group,v_room_site
    from public.rooms r where r.id=p_room;
  end if;
  if v_before is null then raise exception '디스플레이를 찾을 수 없습니다'; end if;

  v_target_group:=coalesce(p_group,v_current_group);
  if not exists(
    select 1 from public.signage_groups g
    where g.id=v_target_group and g.site_id=v_room_site and g.kind='floor'
  ) then
    raise exception '올바른 층을 선택하세요';
  end if;

  if p_space is not null and not exists(
    select 1 from public.floor_spaces fs
    where fs.id=p_space and fs.site_id=v_room_site and fs.group_id=v_target_group
  ) then
    raise exception '같은 층의 공간만 선택할 수 있습니다';
  end if;

  update public.rooms
  set group_id=v_target_group,
      display_control_mode=p_mode,
      map_x_pct=case when p_x is null then null else greatest(0,least(100,p_x)) end,
      map_y_pct=case when p_y is null then null else greatest(0,least(100,p_y)) end,
      display_note=nullif(trim(coalesce(p_note,'')),''),
      floor_space_id=p_space
  where id=p_room;

  update public.rooms
  set manual_check_status=case
    when display_control_mode='manual' and manual_check_status='not_required' then 'needs_check'
    when display_control_mode<>'manual' then 'not_required'
    else manual_check_status end
  where id=p_room;

  select to_jsonb(r) into v_after from public.rooms r where r.id=p_room;
  perform public.audit_event(v_room_site,'update','display',p_room::text,'디스플레이 설정 변경',v_before,v_after);
end $$;
revoke all on function public.staff_set_display_setup(uuid,text,numeric,numeric,text,uuid,uuid) from public;
grant execute on function public.staff_set_display_setup(uuid,text,numeric,numeric,text,uuid,uuid) to anon,authenticated;

insert into public.schema_version(version,applied_at) values('2.34.56',clock_timestamp())
on conflict(version) do update set applied_at=excluded.applied_at;
notify pgrst, 'reload schema';
commit;
-- Clinic Signage v2.34.61 — staff floor-space permissions + layout-copy UUID fix + RPC cleanup
begin;

-- Hospital staff create/update floor spaces through RPCs that fire this trigger.
-- The trigger must be able to validate signage_groups even when RLS hides that table from staff.
alter function public.enforce_floor_space_group_site() security definer;

-- PostgreSQL has no min(uuid). Replace the layout-copy RPC with UUID-safe deterministic selection.
create or replace function public.hospital_copy_floor_layout(
  p_site uuid,
  p_source_group uuid,
  p_target_groups uuid[],
  p_copy_spaces boolean default true,
  p_copy_displays boolean default true
)
returns jsonb
language plpgsql
security definer
set search_path=public
as $$
declare
  v_target uuid;
  v_target_name text;
  v_spaces_copied boolean;
  v_displays_copied boolean;
  v_displays_created integer;
  v_displays_updated integer;
  v_applied jsonb := '[]'::jsonb;
  v_skipped jsonb := '[]'::jsonb;
  v_source_count integer;
  v_source record;
  v_target_room_id uuid;
  v_target_match_count integer;
  v_target_display_name text;
  v_duplicate_key text;
  v_source_key text;
  v_target_floor integer;
  v_target_space_id uuid;
begin
  if p_site is null or p_source_group is null or coalesce(array_length(p_target_groups,1),0)=0 then
    raise exception 'INVALID_ARGUMENT';
  end if;
  if public.pin_session_role() not in ('admin','staff') or not public.can_manage_site(p_site) then
    raise exception 'not allowed';
  end if;
  if not exists(select 1 from public.signage_groups g where g.id=p_source_group and g.site_id=p_site) then
    raise exception 'SOURCE_FLOOR_NOT_FOUND';
  end if;
  if coalesce(p_copy_spaces,false)=false and coalesce(p_copy_displays,false)=false then
    raise exception 'NOTHING_TO_COPY';
  end if;

  if p_copy_displays then
    select count(*) into v_source_count
    from public.rooms r
    where r.site_id=p_site and r.group_id=p_source_group
      and r.map_x_pct is not null and r.map_y_pct is not null;

    select x.slot_key into v_duplicate_key
    from (
      select public.hospital_display_slot_key(r.name) as slot_key, count(*) as cnt
      from public.rooms r
      where r.site_id=p_site and r.group_id=p_source_group
        and r.map_x_pct is not null and r.map_y_pct is not null
      group by 1
      having count(*)>1
      limit 1
    ) x;
    if v_duplicate_key is not null then
      raise exception 'DUPLICATE_SOURCE_DISPLAY_KEY:%',v_duplicate_key;
    end if;
  else
    v_source_count:=0;
  end if;

  foreach v_target in array p_target_groups loop
    if v_target=p_source_group then continue; end if;

    select g.name,g.floor_number into v_target_name,v_target_floor
    from public.signage_groups g
    where g.id=v_target and g.site_id=p_site;

    if v_target_name is null then
      v_skipped:=v_skipped||jsonb_build_array(
        jsonb_build_object('id',v_target,'name','알 수 없는 층','reason','TARGET_FLOOR_NOT_FOUND')
      );
      continue;
    end if;

    v_spaces_copied:=false;
    v_displays_copied:=false;
    v_displays_created:=0;
    v_displays_updated:=0;

    if p_copy_spaces then
      delete from public.floor_spaces where site_id=p_site and group_id=v_target;
      insert into public.floor_spaces(site_id,group_id,name,space_type,x_pct,y_pct,width_pct,height_pct,sort_order)
      select p_site,v_target,fs.name,fs.space_type,fs.x_pct,fs.y_pct,fs.width_pct,fs.height_pct,fs.sort_order
      from public.floor_spaces fs
      where fs.site_id=p_site and fs.group_id=p_source_group
      order by fs.sort_order,fs.created_at;
      v_spaces_copied:=true;
    end if;

    if p_copy_displays then
      if v_source_count=0 then
        v_skipped:=v_skipped||jsonb_build_array(
          jsonb_build_object('id',v_target,'name',v_target_name,'reason','SOURCE_HAS_NO_POSITIONED_DISPLAYS','spaces_copied',v_spaces_copied,'displays_copied',false)
        );
      else
        select x.slot_key into v_duplicate_key
        from (
          select public.hospital_display_slot_key(r.name) as slot_key, count(*) as cnt
          from public.rooms r
          where r.site_id=p_site and r.group_id=v_target
          group by 1
          having count(*)>1
          limit 1
        ) x;
        if v_duplicate_key is not null then
          raise exception 'DUPLICATE_TARGET_DISPLAY_KEY:%:%',v_target_name,v_duplicate_key;
        end if;

        for v_source in
          select r.id,r.name,r.sort_order,r.map_x_pct,r.map_y_pct,r.display_control_mode,r.floor_space_id,
                 public.hospital_display_slot_key(r.name) as slot_key
          from public.rooms r
          where r.site_id=p_site and r.group_id=p_source_group
            and r.map_x_pct is not null and r.map_y_pct is not null
          order by r.name,r.created_at,r.id
        loop
          v_source_key:=v_source.slot_key;
          v_target_space_id:=null;
          if v_source.floor_space_id is not null then
            select t.id into v_target_space_id
            from public.floor_spaces s
            join public.floor_spaces t
              on t.site_id=p_site and t.group_id=v_target
             and t.name=s.name and t.space_type=s.space_type and t.sort_order=s.sort_order
            where s.id=v_source.floor_space_id
            order by t.created_at,t.id
            limit 1;
          end if;
          select count(*),(array_agg(r.id order by r.id))[1] into v_target_match_count,v_target_room_id
          from public.rooms r
          where r.site_id=p_site and r.group_id=v_target
            and public.hospital_display_slot_key(r.name)=v_source_key;

          if v_target_match_count>1 then
            raise exception 'DUPLICATE_TARGET_DISPLAY_KEY:%:%',v_target_name,v_source_key;
          elsif v_target_match_count=0 then
            -- Preserve the source location code, but use the target floor as prefix when available.
            v_target_display_name:=case
              when v_target_floor is not null then
                v_target_floor::text||'F_'||regexp_replace(trim(v_source.name),'^[[:space:]]*[0-9]+[[:space:]]*(f|층)?[[:space:]_\-./]*','','i')
              else
                trim(v_target_name)||'_'||regexp_replace(trim(v_source.name),'^[[:space:]]*[0-9]+[[:space:]]*(f|층)?[[:space:]_\-./]*','','i')
            end;

            insert into public.rooms(site_id,group_id,name,sort_order,display_control_mode,manual_check_status,map_x_pct,map_y_pct,floor_space_id)
            values(
              p_site,v_target,v_target_display_name,v_source.sort_order,
              coalesce(v_source.display_control_mode,'remote'),
              case when coalesce(v_source.display_control_mode,'remote')='manual' then 'needs_check' else 'not_required' end,
              v_source.map_x_pct,v_source.map_y_pct,v_target_space_id
            ) returning id into v_target_room_id;
            v_displays_created:=v_displays_created+1;
          else
            update public.rooms r
            set map_x_pct=v_source.map_x_pct,map_y_pct=v_source.map_y_pct,floor_space_id=v_target_space_id
            where r.id=v_target_room_id;
            v_displays_updated:=v_displays_updated+1;
          end if;
        end loop;
        v_displays_copied:=true;
      end if;
    end if;

    if v_spaces_copied or v_displays_copied then
      perform public.audit_event(
        p_site,'update','floor_layout',v_target::text,'층 도면 배치 복사',null,
        jsonb_build_object('source_group',p_source_group,'target_group',v_target,'spaces_copied',v_spaces_copied,'displays_copied',v_displays_copied,'displays_created',v_displays_created,'displays_updated',v_displays_updated,'display_match','normalized_location_key')
      );
      v_applied:=v_applied||jsonb_build_array(
        jsonb_build_object('id',v_target,'name',v_target_name,'spaces_copied',v_spaces_copied,'displays_copied',v_displays_copied,'displays_created',v_displays_created,'displays_updated',v_displays_updated,'display_match','normalized_location_key')
      );
    end if;
  end loop;

  return jsonb_build_object('ok',true,'applied',v_applied,'skipped',v_skipped);
end
$$;

revoke all on function public.hospital_display_slot_key(text) from public;
grant execute on function public.hospital_display_slot_key(text) to anon,authenticated;
revoke all on function public.hospital_copy_floor_layout(uuid,uuid,uuid[],boolean,boolean) from public;
grant execute on function public.hospital_copy_floor_layout(uuid,uuid,uuid[],boolean,boolean) to anon,authenticated;

-- Keep one canonical display-setup signature only.
drop function if exists public.staff_set_display_setup(uuid,text,numeric,numeric,text,uuid);

insert into public.schema_version(version,applied_at) values('2.34.61',clock_timestamp())
on conflict(version) do update set applied_at=excluded.applied_at;
notify pgrst, 'reload schema';
commit;
begin;

create or replace function public.hospital_reception_state(p_site uuid)
returns jsonb language plpgsql stable security definer set search_path=public as $$
declare
  v_site uuid; v_rooms jsonb; v_groups jsonb; v_patients jsonb; v_broadcast jsonb; v_playlists jsonb; v_videos jsonb; v_items jsonb; v_rules jsonb; v_site_row jsonb; v_floorplans jsonb; v_spaces jsonb; v_versions jsonb; v_settings jsonb;
begin
  if not public.is_member() then raise exception 'not allowed'; end if;
  v_site:=case when public.is_admin() then p_site else public.pin_session_site_id() end;
  if v_site is null or (not public.is_admin() and p_site is not null and p_site<>v_site) or not public.can_manage_site(v_site) then raise exception 'not allowed'; end if;
  select to_jsonb(s) into v_site_row from public.sites s where s.id=v_site; if v_site_row is null then raise exception 'site not found'; end if;
  select coalesce(ss.floorplan_assets,'{}'::jsonb),coalesce(ss.operating_config,'{}'::jsonb) into v_floorplans,v_settings from public.site_settings ss where ss.site_id=v_site;
  select coalesce(jsonb_agg(to_jsonb(fs) order by fs.sort_order,fs.created_at),'[]'::jsonb) into v_spaces from public.floor_spaces fs where fs.site_id=v_site;
  select coalesce(jsonb_agg(to_jsonb(fv) order by fv.created_at desc),'[]'::jsonb) into v_versions from public.floorplan_versions fv where fv.site_id=v_site;
  select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'site_id',r.site_id,'name',r.name,'sort_order',r.sort_order,'group_id',r.group_id,'group_name',g.name,'room_mode',r.room_mode,'last_seen_at',r.last_seen_at,'player_status',coalesce(r.player_status,'{}'::jsonb),'session_timeout_min',r.session_timeout_min,'session_started_at',r.session_started_at,'session_age_group',r.session_age_group,'session_gender',r.session_gender,'session_treatment',r.session_treatment,'default_playlist_id',r.default_playlist_id,'manual_active',r.manual_active,'manual_video_ids',r.manual_video_ids,'map_x_pct',r.map_x_pct,'map_y_pct',r.map_y_pct,'display_control_mode',r.display_control_mode,'manual_check_status',r.manual_check_status,'manual_checked_at',r.manual_checked_at,'manual_checked_by',r.manual_checked_by,'display_note',r.display_note) order by coalesce(g.sort_order,2147483647),r.sort_order,r.created_at),'[]'::jsonb) into v_rooms from public.rooms r left join public.signage_groups g on g.id=r.group_id where r.site_id=v_site;
  select coalesce(jsonb_agg(jsonb_build_object('id',g.id,'site_id',g.site_id,'name',g.name,'kind',g.kind,'floor_number',g.floor_number,'care_type',g.care_type,'signage_purpose',g.signage_purpose,'target_audience',g.target_audience,'waiting_area_note',g.waiting_area_note,'signage_reason',g.signage_reason,'content_intro',g.content_intro,'content_topics',g.content_topics,'role_label',g.role_label,'default_playlist_id',g.default_playlist_id,'sort_order',g.sort_order) order by g.sort_order,g.floor_number,g.created_at),'[]'::jsonb) into v_groups from public.signage_groups g where g.site_id=v_site;
  select coalesce(jsonb_agg(to_jsonb(x) order by case x.status when 'in_progress' then 0 when 'assigned' then 1 when 'waiting' then 2 else 3 end,x.waiting_started_at),'[]'::jsonb) into v_patients from (select * from public.patient_sessions where site_id=v_site and (status in ('waiting','assigned','in_progress') or (status='completed' and completed_at>=date_trunc('day',clock_timestamp())))) x;
  select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'site_id',p.site_id,'name',p.name,'kind',p.kind,'active',p.active,'sort_order',p.sort_order,'target_treatment',p.target_treatment,'target_age',p.target_age,'target_gender',p.target_gender) order by p.sort_order,p.created_at),'[]'::jsonb) into v_playlists from public.playlists p where p.active and (p.site_id is null or p.site_id=v_site);
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',v.id,
    'site_id',v.site_id,
    'title',v.title,
    'active',v.active,
    'duration_sec',v.duration_sec,
    'thumbnail_data_url',v.thumbnail_data_url,
    'url',v.url,
    'source',v.source,
    'storage_path',v.storage_path,
    'file_path',v.file_path,
    'target_treatment',v.target_treatment,
    'target_age',v.target_age,
    'target_gender',v.target_gender
  ) order by v.sort_order,v.created_at),'[]'::jsonb) into v_videos
  from public.videos v
  where v.active and (v.site_id is null or v.site_id=v_site) and (v.source<>'local' or v.available);
  select coalesce(jsonb_agg(jsonb_build_object('playlist_id',pi.playlist_id,'video_id',pi.video_id,'sort_order',pi.sort_order) order by pi.playlist_id,pi.sort_order,pi.created_at),'[]'::jsonb) into v_items from public.playlist_items pi join public.playlists p on p.id=pi.playlist_id where p.site_id is null or p.site_id=v_site;
  select coalesce(jsonb_agg(jsonb_build_object('room_id',rr.room_id,'video_id',rr.video_id,'enabled',rr.enabled,'sort_order',rr.sort_order,'starts_at',rr.starts_at,'ends_at',rr.ends_at,'updated_at',rr.updated_at)),'[]'::jsonb) into v_rules from public.room_video_rules rr join public.rooms r on r.id=rr.room_id where r.site_id=v_site;
  select jsonb_build_object('active',active,'video_ids',video_ids,'notice_text',notice_text,'starts_at',starts_at,'ends_at',ends_at,'revision',revision) into v_broadcast from public.site_broadcasts where site_id=v_site;
  return jsonb_build_object('site',v_site_row,'site_settings',coalesce(v_settings,'{}'::jsonb),'floorplan_assets',coalesce(v_floorplans,'{}'::jsonb),'floorplan_versions',coalesce(v_versions,'[]'::jsonb),'spaces',coalesce(v_spaces,'[]'::jsonb),'rooms',v_rooms,'groups',v_groups,'patients',v_patients,'playlists',v_playlists,'videos',v_videos,'playlist_items',v_items,'room_video_rules',v_rules,'broadcast',coalesce(v_broadcast,'{}'::jsonb),'server_time',clock_timestamp());
end $$;

revoke all on function public.hospital_reception_state(uuid) from public;
grant execute on function public.hospital_reception_state(uuid) to anon,authenticated;

