-- ===== merged from v2.35.75-player-recovery-diagnostics.sql =====
-- Apply to a staging DB first. Preserves RLS and existing tables.
BEGIN;
create or replace function public.player_heartbeat(p_key uuid,p_status jsonb)
returns void language plpgsql security definer set search_path=public as $$
declare
  clean jsonb; v_room uuid; v_prev jsonb; v_last timestamptz; v_now timestamptz:=clock_timestamp();
  v_delta int:=0; v_day date; v_local_time time; v_start time; v_end time; v_open boolean:=false; v_in_hours boolean:=false;
  v_state text; v_mode text; v_prev_state text; v_prev_mode text; v_reconnect int:=0; v_error_transition int:=0;
begin
  select id,player_status,last_seen_at into v_room,v_prev,v_last from public.rooms where player_key=p_key for update;
  if v_room is null then return; end if;
  if p_status is null or jsonb_typeof(p_status)<>'object' or pg_column_size(p_status)>4096 then
    update public.rooms set heartbeat_rejected_count=heartbeat_rejected_count+1 where id=v_room; return;
  end if;
  clean=jsonb_build_object(
    'video_id',case when jsonb_typeof(p_status->'video_id')='string' then left(p_status->>'video_id',64) else null end,
    'title',left(coalesce(p_status->>'title',''),160),'mode',left(coalesce(p_status->>'mode',''),32),
    'playback_state',left(coalesce(p_status->>'playback_state',''),32),
    'current_time',case when jsonb_typeof(p_status->'current_time')='number' then greatest(0,least((p_status->>'current_time')::numeric,86400)) else 0 end,
    'duration',case when jsonb_typeof(p_status->'duration')='number' then greatest(0,least((p_status->>'duration')::numeric,86400)) else 0 end,
    'muted',case when jsonb_typeof(p_status->'muted')='boolean' then (p_status->>'muted')::boolean else false end,
    'volume',case when jsonb_typeof(p_status->'volume')='number' then greatest(0,least((p_status->>'volume')::int,100)) else 0 end,
    'online',case when jsonb_typeof(p_status->'online')='boolean' then (p_status->>'online')::boolean else false end,
    'error',left(coalesce(p_status->>'error',''),300),'source',left(coalesce(p_status->>'source',''),64),
    'playlist_titles',coalesce((select jsonb_agg(left(x.value,120) order by x.ord) from jsonb_array_elements_text(case when jsonb_typeof(p_status->'playlist_titles')='array' then p_status->'playlist_titles' else '[]'::jsonb end) with ordinality as x(value,ord) where x.ord<=12),'[]'::jsonb),
    'active_hash',left(coalesce(p_status->>'active_hash',''),100),
    'pending_hash',left(coalesce(p_status->>'pending_hash',''),100),
    'pending_count',case when jsonb_typeof(p_status->'pending_count')='number' then greatest(0,least((p_status->>'pending_count')::int,500)) end,
    'pending_total',case when jsonb_typeof(p_status->'pending_total')='number' then greatest(0,least((p_status->>'pending_total')::int,500)) end,
    'storage_persisted',case when jsonb_typeof(p_status->'storage_persisted')='boolean' then (p_status->>'storage_persisted')::boolean end,
    'offline_cache_error',left(coalesce(p_status->>'offline_cache_error',''),160),
    'failed_videos',coalesce((select jsonb_agg(jsonb_build_object('id',left(coalesce(x.item->>'id',''),100),'title',left(coalesce(x.item->>'title',''),60),'code',left(coalesce(x.item->>'code',''),40))) from jsonb_array_elements(case when jsonb_typeof(p_status->'failed_videos')='array' then p_status->'failed_videos' else '[]'::jsonb end) with ordinality as x(item,ord) where x.ord<=5),'[]'::jsonb),
    'playlist_count',case when jsonb_typeof(p_status->'playlist_count')='number' then greatest(0,least((p_status->>'playlist_count')::int,500)) else 0 end,
    'current_index',case when jsonb_typeof(p_status->'current_index')='number' then greatest(0,least((p_status->>'current_index')::int,499)) else 0 end,
    'next_title',left(coalesce(p_status->>'next_title',''),160),'app_version',left(coalesce(p_status->>'app_version',''),24),'reported_at',left(coalesce(p_status->>'reported_at',''),48)
  );
  v_state:=clean->>'playback_state'; v_mode:=clean->>'mode'; v_prev_state:=coalesce(v_prev->>'playback_state',''); v_prev_mode:=coalesce(v_prev->>'mode','');
  v_day:=(v_now at time zone 'Asia/Seoul')::date; v_local_time:=(v_now at time zone 'Asia/Seoul')::time;
  select is_open,start_time,end_time into v_open,v_start,v_end from public.signage_room_operating_window(v_room,v_day);
  v_in_hours:=v_open and v_local_time>=v_start and v_local_time<v_end;
  if v_last is not null then
    -- Up to one 5-minute telemetry interval, with margin for timer jitter.
    -- Older 60-second caps undercounted playback by ~80% at 5-minute intervals.
    v_delta:=greatest(0,least(360,extract(epoch from (v_now-v_last))::int));
    -- A normal 5-minute interval is not a reconnect.
    if extract(epoch from (v_now-v_last))>600 then v_reconnect:=1; end if;
  end if;
  if coalesce(clean->>'error','')<>'' and coalesce(v_prev->>'error','')='' then v_error_transition:=1; end if;
  if v_in_hours and v_delta>0 then
    insert into public.room_playback_daily(day,room_id,online_seconds,playing_seconds,default_seconds,custom_seconds,override_seconds,error_seconds,paused_seconds,reconnect_count,error_count,updated_at)
    values(v_day,v_room,v_delta,
      case when v_state in ('playing','emergency') then v_delta else 0 end,
      case when v_state in ('playing','emergency') and v_mode='default' then v_delta else 0 end,
      case when v_state in ('playing','emergency') and v_mode in ('patient','session') then v_delta else 0 end,
      case when v_state in ('playing','emergency') and v_mode in ('broadcast','broadcast_schedule','group','group_schedule','manual') then v_delta else 0 end,
      case when v_state='error' then v_delta else 0 end,
      case when v_state='paused' then v_delta else 0 end,v_reconnect,v_error_transition,v_now)
    on conflict(day,room_id) do update set
      online_seconds=room_playback_daily.online_seconds+excluded.online_seconds,
      playing_seconds=room_playback_daily.playing_seconds+excluded.playing_seconds,
      default_seconds=room_playback_daily.default_seconds+excluded.default_seconds,
      custom_seconds=room_playback_daily.custom_seconds+excluded.custom_seconds,
      override_seconds=room_playback_daily.override_seconds+excluded.override_seconds,
      error_seconds=room_playback_daily.error_seconds+excluded.error_seconds,
      paused_seconds=room_playback_daily.paused_seconds+excluded.paused_seconds,
      reconnect_count=room_playback_daily.reconnect_count+excluded.reconnect_count,
      error_count=room_playback_daily.error_count+excluded.error_count,updated_at=v_now;
  end if;
  if v_prev is null or v_state<>v_prev_state or v_mode<>v_prev_mode or coalesce(clean->>'video_id','')<>coalesce(v_prev->>'video_id','') or coalesce(clean->>'error','')<>coalesce(v_prev->>'error','') then
    insert into public.player_events(room_id,event_type,mode,playback_state,video_id,title,error)
    values(v_room,'state_change',nullif(v_mode,''),nullif(v_state,''),nullif(clean->>'video_id',''),nullif(clean->>'title',''),nullif(clean->>'error',''));
  end if;
  update public.rooms set last_seen_at=v_now,player_status=clean where id=v_room;
end $$;
create or replace function public.player_report(p_key uuid, p_status jsonb)
returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_room uuid;
  v_now timestamptz := clock_timestamp();
  v_clean jsonb;
  v_fp text;
  v_prev_fp text;
  v_prev_seen timestamptz;
  v_synced text;
  ts_re constant text := '^[0-9]{4}-[0-9]{2}-[0-9]{2}[T ][0-9:.]+(Z|[+-][0-9]{2}(:?[0-9]{2})?)?$';
begin
  select id into v_room from public.rooms where player_key = p_key;
  if v_room is null then return null; end if;
  if p_status is null or jsonb_typeof(p_status) <> 'object' or pg_column_size(p_status) > 8192 then
    return jsonb_build_object('ok', false, 'error', 'invalid_status', 'server_time', v_now);
  end if;

  v_synced := case when jsonb_typeof(p_status->'synced_at') = 'string' and (p_status->>'synced_at') ~ ts_re
                   then left(p_status->>'synced_at', 40) end;

  v_clean := jsonb_strip_nulls(jsonb_build_object(
    'video_id',        case when jsonb_typeof(p_status->'video_id') = 'string' then left(p_status->>'video_id', 64) end,
    'title',           left(coalesce(p_status->>'title', ''), 160),
    'mode',            left(coalesce(p_status->>'mode', ''), 32),
    'playback_state',  left(coalesce(p_status->>'playback_state', ''), 32),
    'current_time',    case when jsonb_typeof(p_status->'current_time') = 'number' then greatest(0, least((p_status->>'current_time')::numeric, 86400)) else 0 end,
    'duration',        case when jsonb_typeof(p_status->'duration') = 'number' then greatest(0, least((p_status->>'duration')::numeric, 86400)) else 0 end,
    'muted',           case when jsonb_typeof(p_status->'muted') = 'boolean' then (p_status->>'muted')::boolean else false end,
    'volume',          case when jsonb_typeof(p_status->'volume') = 'number' then greatest(0, least((p_status->>'volume')::numeric, 100))::int else 0 end,
    'online',          case when jsonb_typeof(p_status->'online') = 'boolean' then (p_status->>'online')::boolean else true end,
    'error',           nullif(left(coalesce(p_status->>'error', ''), 300), ''),
    'source',          left(coalesce(p_status->>'source', ''), 64),
    'recovery_stage',  case when jsonb_typeof(p_status->'recovery_stage') = 'number' then greatest(0, least((p_status->>'recovery_stage')::numeric, 9))::int end,
    'playlist_video_ids', coalesce((
        select jsonb_agg(left(x.value, 64) order by x.ord)
          from jsonb_array_elements_text(case when jsonb_typeof(p_status->'playlist_video_ids') = 'array' then p_status->'playlist_video_ids' else '[]'::jsonb end) with ordinality as x(value, ord)
         where x.ord <= 20), '[]'::jsonb),
    'playlist_titles', coalesce((
        select jsonb_agg(left(x.value, 120) order by x.ord)
          from jsonb_array_elements_text(case when jsonb_typeof(p_status->'playlist_titles') = 'array' then p_status->'playlist_titles' else '[]'::jsonb end) with ordinality as x(value, ord)
         where x.ord <= 12), '[]'::jsonb),
    'playlist_count',  case when jsonb_typeof(p_status->'playlist_count') = 'number' then greatest(0, least((p_status->>'playlist_count')::numeric, 500))::int else 0 end,
    'current_index',   case when jsonb_typeof(p_status->'current_index') = 'number' then greatest(0, least((p_status->>'current_index')::numeric, 499))::int else 0 end,
    'next_title',      nullif(left(coalesce(p_status->>'next_title', ''), 160), ''),
    'app_version',     left(coalesce(p_status->>'app_version', ''), 24),
    'sync_revision',   nullif(left(coalesce(p_status->>'sync_revision', ''), 160), ''),
    'offline_cache_ready', case when jsonb_typeof(p_status->'offline_cache_ready')='boolean' then (p_status->>'offline_cache_ready')::boolean else false end,
    'offline_cache_count', case when jsonb_typeof(p_status->'offline_cache_count')='number' then greatest(0,least((p_status->>'offline_cache_count')::int,500)) else 0 end,
    'offline_cache_total', case when jsonb_typeof(p_status->'offline_cache_total')='number' then greatest(0,least((p_status->>'offline_cache_total')::int,500)) else 0 end,
    'offline_cache_error', nullif(left(coalesce(p_status->>'offline_cache_error',''),160),''),
    'active_hash',left(coalesce(p_status->>'active_hash',''),100),
    'pending_hash',left(coalesce(p_status->>'pending_hash',''),100),
    'pending_count',case when jsonb_typeof(p_status->'pending_count')='number' then greatest(0,least((p_status->>'pending_count')::int,500)) end,
    'pending_total',case when jsonb_typeof(p_status->'pending_total')='number' then greatest(0,least((p_status->>'pending_total')::int,500)) end,
    'storage_persisted',case when jsonb_typeof(p_status->'storage_persisted')='boolean' then (p_status->>'storage_persisted')::boolean end,
        'failed_videos',coalesce((select jsonb_agg(jsonb_build_object('id',left(coalesce(x.item->>'id',''),100),'title',left(coalesce(x.item->>'title',''),60),'code',left(coalesce(x.item->>'code',''),40))) from jsonb_array_elements(case when jsonb_typeof(p_status->'failed_videos')='array' then p_status->'failed_videos' else '[]'::jsonb end) with ordinality as x(item,ord) where x.ord<=5),'[]'::jsonb),
    'operating_active', case when jsonb_typeof(p_status->'operating_active')='boolean' then (p_status->>'operating_active')::boolean else true end,
    'priority', nullif(left(coalesce(p_status->>'priority',''),32),''),
    'update_pending_version', nullif(left(coalesce(p_status->>'update_pending_version',''),24),''),
    'update_error', nullif(left(coalesce(p_status->>'update_error',''),160),''),
    'failed_video_count', case when jsonb_typeof(p_status->'failed_video_count')='number' then greatest(0,least((p_status->>'failed_video_count')::int,500)) else 0 end,
    'synced_at',       v_synced
  )) || jsonb_build_object('reported_at', v_now);

  -- 재생 위치/보고 시각을 제외한 "의미 있는 변경" 지문
  v_fp := md5((v_clean - 'current_time' - 'reported_at' - 'pending_count')::text);

  select status_fp, last_seen_at into v_prev_fp, v_prev_seen
    from public.player_live_status where room_id = v_room;

  -- 같은 내용이 짧은 간격으로 반복되면 쓰기 생략 (오동작 플레이어 보호)
  if v_prev_fp is not distinct from v_fp and v_prev_seen is not null and v_prev_seen > v_now - interval '5 seconds' then
    return jsonb_build_object('ok', true, 'skipped', true, 'server_time', v_now);
  end if;

  insert into public.player_live_status as s (room_id, last_seen_at, player_status, updated_at, changed_at, status_fp)
  values (v_room, v_now, v_clean, v_now, v_now, v_fp)
  on conflict (room_id) do update set
    last_seen_at  = excluded.last_seen_at,
    player_status = excluded.player_status,
    updated_at    = excluded.updated_at,
    changed_at    = case when s.status_fp is distinct from excluded.status_fp then excluded.changed_at else coalesce(s.changed_at, excluded.changed_at) end,
    status_fp     = excluded.status_fp;

  return jsonb_build_object('ok', true, 'server_time', v_now);
end $$;
COMMIT;


-- ===== merged from v2.35.77-hospital-video-delete.sql =====
-- Clinic Signage v2.35.77
-- Safe site-only video removal. Do NOT remove referenced video and do NOT delete R2 object.
BEGIN;
CREATE OR REPLACE FUNCTION public.hospital_delete_site_video(p_site uuid,p_video uuid)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public
AS $$
DECLARE v_video public.videos%ROWTYPE;
BEGIN
  IF NOT public.can_manage_site(p_site) THEN
    RAISE EXCEPTION '영상 삭제 권한이 없습니다.' USING ERRCODE='42501';
  END IF;
  SELECT * INTO v_video FROM public.videos WHERE id=p_video AND site_id=p_site FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION '이 병원 소유 영상만 삭제할 수 있습니다.' USING ERRCODE='42501';
  END IF;
  -- Check all persistent references, including inactive/future schedules.
  IF EXISTS (SELECT 1 FROM public.playlist_items WHERE video_id=p_video)
     OR EXISTS (SELECT 1 FROM public.room_video_rules WHERE video_id=p_video)
     OR EXISTS (SELECT 1 FROM public.rooms WHERE p_video=ANY(manual_video_ids))
     OR EXISTS (SELECT 1 FROM public.site_broadcasts WHERE p_video=ANY(video_ids))
     OR EXISTS (SELECT 1 FROM public.group_broadcasts WHERE p_video=ANY(video_ids))
     OR EXISTS (SELECT 1 FROM public.broadcast_schedules WHERE p_video=ANY(video_ids))
     OR EXISTS (SELECT 1 FROM public.site_settings WHERE operating_config->>'emergency_video_id'=p_video::text)
     OR EXISTS (SELECT 1 FROM public.app_settings WHERE emergency_video_id=p_video)
     OR EXISTS (SELECT 1 FROM public.broadcast WHERE p_video=ANY(video_ids)) THEN
    RAISE EXCEPTION '재생목록 또는 송출 설정에서 사용 중인 영상입니다. 연결을 먼저 해제한 뒤 삭제하세요.' USING ERRCODE='P0001';
  END IF;
  DELETE FROM public.videos WHERE id=p_video AND site_id=p_site;
  IF NOT FOUND THEN RAISE EXCEPTION '삭제할 영상을 찾지 못했습니다.'; END IF;
END $$;
REVOKE ALL ON FUNCTION public.hospital_delete_site_video(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.hospital_delete_site_video(uuid,uuid) TO anon,authenticated;
COMMIT;


-- ===== merged from v2.35.78-superadmin-hospital-full-access.sql =====
-- Clinic Signage 2.35.78: superadmin global content controls from hospital view.
-- Never infer admin from client-supplied p_site. Verify PIN session on server.
-- Requires existing v2.35.77 hospital_delete_site_video migration.
BEGIN;

CREATE OR REPLACE FUNCTION public.superadmin_save_global_playlist(
  p_id uuid, p_name text, p_video_ids uuid[]
) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_video uuid; v_pos int:=0;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION '슈퍼어드민만 공용 재생목록을 수정할 수 있습니다.' USING ERRCODE='42501';
  END IF;
  IF p_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.playlists WHERE id=p_id AND site_id IS NULL) THEN
    RAISE EXCEPTION '공용 재생목록을 찾을 수 없습니다.' USING ERRCODE='P0001';
  END IF;
  IF nullif(btrim(coalesce(p_name,'')),'') IS NULL THEN
    RAISE EXCEPTION '재생목록 이름을 입력하세요.' USING ERRCODE='P0001';
  END IF;
  IF coalesce(array_length(p_video_ids,1),0)=0 THEN
    RAISE EXCEPTION '영상은 1개 이상 선택하세요.' USING ERRCODE='P0001';
  END IF;
  IF EXISTS(
    SELECT 1 FROM unnest(p_video_ids) AS x(id)
    WHERE NOT EXISTS(SELECT 1 FROM public.videos v WHERE v.id=x.id AND v.site_id IS NULL AND v.active)
  ) THEN
    RAISE EXCEPTION '공용 재생목록에는 공용 영상만 넣을 수 있습니다.' USING ERRCODE='P0001';
  END IF;
  IF (SELECT count(*) FROM unnest(p_video_ids)) <> (SELECT count(DISTINCT x.id) FROM unnest(p_video_ids) AS x(id)) THEN
    RAISE EXCEPTION '중복된 영상이 포함되어 있습니다.' USING ERRCODE='P0001';
  END IF;
  PERFORM 1 FROM public.playlists WHERE id=p_id AND site_id IS NULL FOR UPDATE;
  UPDATE public.playlists SET name=btrim(p_name),updated_at=clock_timestamp() WHERE id=p_id AND site_id IS NULL;
  DELETE FROM public.playlist_items WHERE playlist_id=p_id;
  FOREACH v_video IN ARRAY p_video_ids LOOP
    v_pos:=v_pos+10;
    INSERT INTO public.playlist_items(playlist_id,video_id,sort_order)
    VALUES (p_id,v_video,v_pos);
  END LOOP;
  RETURN p_id;
END $$;

CREATE OR REPLACE FUNCTION public.superadmin_delete_global_playlist(p_id uuid)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION '슈퍼어드민 권한이 필요합니다.' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM public.playlists WHERE id=p_id AND site_id IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '공용 재생목록을 찾을 수 없습니다.' USING ERRCODE='P0001'; END IF;
  IF EXISTS(SELECT 1 FROM public.rooms WHERE default_playlist_id=p_id)
     OR EXISTS(SELECT 1 FROM public.signage_groups WHERE default_playlist_id=p_id) THEN
    RAISE EXCEPTION 'TV 또는 층에서 사용 중인 공용 재생목록은 삭제할 수 없습니다.' USING ERRCODE='P0001';
  END IF;
  DELETE FROM public.playlists WHERE id=p_id AND site_id IS NULL;
END $$;

CREATE OR REPLACE FUNCTION public.superadmin_delete_global_video(p_video uuid)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION '슈퍼어드민 권한이 필요합니다.' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM public.videos WHERE id=p_video AND site_id IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '공용 영상을 찾을 수 없습니다.' USING ERRCODE='P0001'; END IF;
  -- Protect all hospitals and all scheduled/persistent references.
  IF EXISTS(SELECT 1 FROM public.playlist_items WHERE video_id=p_video)
    OR EXISTS(SELECT 1 FROM public.room_video_rules WHERE video_id=p_video)
    OR EXISTS(SELECT 1 FROM public.rooms WHERE p_video=ANY(manual_video_ids))
    OR EXISTS(SELECT 1 FROM public.site_broadcasts WHERE p_video=ANY(video_ids))
    OR EXISTS(SELECT 1 FROM public.group_broadcasts WHERE p_video=ANY(video_ids))
    OR EXISTS(SELECT 1 FROM public.broadcast_schedules WHERE p_video=ANY(video_ids))
    OR EXISTS(SELECT 1 FROM public.site_settings WHERE operating_config->>'emergency_video_id'=p_video::text)
    OR EXISTS(SELECT 1 FROM public.app_settings WHERE emergency_video_id=p_video)
    OR EXISTS(SELECT 1 FROM public.broadcast WHERE p_video=ANY(video_ids)) THEN
    RAISE EXCEPTION '다른 병원 또는 송출 설정에서 사용 중입니다. 연결을 모두 해제한 뒤 삭제하세요.' USING ERRCODE='P0001';
  END IF;
  DELETE FROM public.videos WHERE id=p_video AND site_id IS NULL;
END $$;

REVOKE ALL ON FUNCTION public.superadmin_save_global_playlist(uuid,text,uuid[]),
  public.superadmin_delete_global_playlist(uuid),
  public.superadmin_delete_global_video(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.superadmin_save_global_playlist(uuid,text,uuid[]),
  public.superadmin_delete_global_playlist(uuid),
  public.superadmin_delete_global_video(uuid) TO anon,authenticated;
COMMIT;


-- ===== merged from v2.35.79-r2-video-delete.sql =====
-- v2.35.79: durable deletion queue. Apply BEFORE deploying the web/API files.
-- Existing video references are checked before any metadata deletion; R2 failure leaves a retryable job.
BEGIN;
CREATE TABLE IF NOT EXISTS public.video_r2_delete_jobs (
  video_id uuid PRIMARY KEY,
  site_id uuid,
  object_key text,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','complete')),
  last_error text,
  created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
  completed_at timestamptz
);
ALTER TABLE public.video_r2_delete_jobs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.video_r2_delete_jobs FROM PUBLIC, anon, authenticated;

CREATE OR REPLACE FUNCTION public.video_delete_enqueue(p_video uuid, p_site uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v public.videos%ROWTYPE; j public.video_r2_delete_jobs%ROWTYPE; v_key text;
BEGIN
  -- Serialize requests for this specific video, including duplicate clicks.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_video::text, 0));
  SELECT * INTO j FROM public.video_r2_delete_jobs WHERE video_id=p_video FOR UPDATE;
  IF FOUND THEN
    IF NOT (public.is_admin() OR (j.site_id IS NOT NULL AND public.can_manage_site(j.site_id) AND p_site=j.site_id)) THEN
      RAISE EXCEPTION '삭제 작업 접근 권한이 없습니다.' USING ERRCODE='42501';
    END IF;
    RETURN jsonb_build_object('video_id',j.video_id,'object_key',j.object_key,'status',j.status);
  END IF;
  SELECT * INTO v FROM public.videos WHERE id=p_video FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '영상을 찾을 수 없습니다.'; END IF;
  IF v.site_id IS NULL THEN
    IF NOT public.is_admin() THEN RAISE EXCEPTION '공용 영상은 슈퍼어드민만 삭제할 수 있습니다.' USING ERRCODE='42501'; END IF;
  ELSIF (p_site IS DISTINCT FROM v.site_id) OR NOT public.can_manage_site(v.site_id) THEN
    RAISE EXCEPTION '영상 삭제 권한이 없습니다.' USING ERRCODE='42501';
  END IF;

  -- Protect scheduled, inactive and active uses across ALL sites, not just the open hospital.
  IF EXISTS (SELECT 1 FROM public.playlist_items WHERE video_id=p_video)
    OR EXISTS (SELECT 1 FROM public.room_video_rules WHERE video_id=p_video)
    OR EXISTS (SELECT 1 FROM public.rooms WHERE p_video=ANY(manual_video_ids))
    OR EXISTS (SELECT 1 FROM public.site_broadcasts WHERE p_video=ANY(video_ids))
    OR EXISTS (SELECT 1 FROM public.group_broadcasts WHERE p_video=ANY(video_ids))
    OR EXISTS (SELECT 1 FROM public.broadcast_schedules WHERE p_video=ANY(video_ids))
    OR EXISTS (SELECT 1 FROM public.site_settings WHERE operating_config->>'emergency_video_id'=p_video::text)
    OR EXISTS (SELECT 1 FROM public.app_settings WHERE emergency_video_id=p_video)
    OR EXISTS (SELECT 1 FROM public.broadcast WHERE p_video=ANY(video_ids)) THEN
    RAISE EXCEPTION '사용 중인 영상입니다. 모든 재생목록 및 송출 연결을 해제하세요.' USING ERRCODE='P0001';
  END IF;

  v_key := CASE WHEN v.source='r2' THEN nullif(btrim(v.storage_path),'') END;
  -- Never delete an R2 key that looks unrelated to this system's managed video prefixes.
  IF v_key IS NOT NULL AND NOT (
      v_key ~ '^videos/[0-9]{4}/[0-9]{2}/[A-Za-z0-9가-힣._/-]+$'
      OR v_key ~ '^sites/[0-9a-fA-F-]{36}/videos/[0-9]{4}/[0-9]{2}/[A-Za-z0-9가-힣._/-]+$'
    ) THEN
    RAISE EXCEPTION 'R2 영상 경로를 확인할 수 없습니다. 수동 확인이 필요합니다.' USING ERRCODE='P0001';
  END IF;
  IF v_key LIKE '%..%' OR v_key LIKE '%//%' THEN
    RAISE EXCEPTION '안전하지 않은 R2 경로입니다.' USING ERRCODE='P0001';
  END IF;
  -- Legacy global keys may be shared by URL even where storage_path differs.
  IF v_key IS NOT NULL AND EXISTS(
    SELECT 1 FROM public.videos other
    WHERE other.id<>v.id AND (other.storage_path=v_key OR other.url=v.url AND v.url IS NOT NULL)
  ) THEN RAISE EXCEPTION '다른 영상에서도 동일한 파일을 사용합니다.' USING ERRCODE='P0001'; END IF;

  INSERT INTO public.video_r2_delete_jobs(video_id,site_id,object_key)
  VALUES(v.id,v.site_id,v_key);
  -- Metadata removal and retry job are committed in the SAME transaction.
  DELETE FROM public.videos WHERE id=v.id;
  RETURN jsonb_build_object('video_id',v.id,'object_key',v_key,'status','pending');
END $$;

CREATE OR REPLACE FUNCTION public.video_delete_pending(p_site uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
  IF NOT public.is_admin() AND (p_site IS NULL OR NOT public.can_manage_site(p_site)) THEN
    RAISE EXCEPTION '접근 권한이 없습니다.' USING ERRCODE='42501';
  END IF;
  RETURN COALESCE((SELECT jsonb_agg(jsonb_build_object('video_id',video_id,'object_key',object_key))
    FROM (SELECT video_id,object_key FROM public.video_r2_delete_jobs
      WHERE status='pending' AND (site_id=p_site OR (public.is_admin() AND p_site IS NULL))
      ORDER BY created_at LIMIT 20) jobs), '[]'::jsonb);
END $$;

CREATE OR REPLACE FUNCTION public.video_delete_finish(p_video uuid, p_error text DEFAULT NULL)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE j public.video_r2_delete_jobs%ROWTYPE;
BEGIN
  SELECT * INTO j FROM public.video_r2_delete_jobs WHERE video_id=p_video FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '삭제 작업을 찾지 못했습니다.'; END IF;
  IF NOT (public.is_admin() OR (j.site_id IS NOT NULL AND public.can_manage_site(j.site_id))) THEN
    RAISE EXCEPTION '삭제 작업 접근 권한이 없습니다.' USING ERRCODE='42501';
  END IF;
  UPDATE public.video_r2_delete_jobs
    SET status=CASE WHEN p_error IS NULL THEN 'complete' ELSE 'pending' END,
        last_error=left(p_error,500),
        completed_at=CASE WHEN p_error IS NULL THEN clock_timestamp() ELSE NULL END
    WHERE video_id=p_video;
END $$;
REVOKE ALL ON FUNCTION public.video_delete_enqueue(uuid,uuid),public.video_delete_pending(uuid),public.video_delete_finish(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.video_delete_enqueue(uuid,uuid),public.video_delete_pending(uuid),public.video_delete_finish(uuid,text) TO anon,authenticated;
COMMIT;


-- ===== merged from v2.35.79-r2-delete-key-hotfix.sql =====
-- Hotfix for v2.35.79: accept the R2 object keys actually issued by both upload APIs.
-- Requires the v2.35.79 delete-job migration to be installed first.
-- Only replaces video_delete_enqueue; no rows are deleted by running this migration.
BEGIN;
CREATE OR REPLACE FUNCTION public.video_delete_enqueue(p_video uuid, p_site uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v public.videos%ROWTYPE; j public.video_r2_delete_jobs%ROWTYPE; v_key text;
BEGIN
  -- Serialize requests for this specific video, including duplicate clicks.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_video::text, 0));
  SELECT * INTO j FROM public.video_r2_delete_jobs WHERE video_id=p_video FOR UPDATE;
  IF FOUND THEN
    IF NOT (public.is_admin() OR (j.site_id IS NOT NULL AND public.can_manage_site(j.site_id) AND p_site=j.site_id)) THEN
      RAISE EXCEPTION '삭제 작업 접근 권한이 없습니다.' USING ERRCODE='42501';
    END IF;
    RETURN jsonb_build_object('video_id',j.video_id,'object_key',j.object_key,'site_id',j.site_id,'status',j.status);
  END IF;
  SELECT * INTO v FROM public.videos WHERE id=p_video FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '영상을 찾을 수 없습니다.'; END IF;
  IF v.site_id IS NULL THEN
    IF NOT public.is_admin() THEN RAISE EXCEPTION '공용 영상은 슈퍼어드민만 삭제할 수 있습니다.' USING ERRCODE='42501'; END IF;
  ELSIF (p_site IS DISTINCT FROM v.site_id) OR NOT public.can_manage_site(v.site_id) THEN
    RAISE EXCEPTION '영상 삭제 권한이 없습니다.' USING ERRCODE='42501';
  END IF;

  -- Protect scheduled, inactive and active uses across ALL sites, not just the open hospital.
  IF EXISTS (SELECT 1 FROM public.playlist_items WHERE video_id=p_video)
    OR EXISTS (SELECT 1 FROM public.room_video_rules WHERE video_id=p_video)
    OR EXISTS (SELECT 1 FROM public.rooms WHERE p_video=ANY(manual_video_ids))
    OR EXISTS (SELECT 1 FROM public.site_broadcasts WHERE p_video=ANY(video_ids))
    OR EXISTS (SELECT 1 FROM public.group_broadcasts WHERE p_video=ANY(video_ids))
    OR EXISTS (SELECT 1 FROM public.broadcast_schedules WHERE p_video=ANY(video_ids))
    OR EXISTS (SELECT 1 FROM public.site_settings WHERE operating_config->>'emergency_video_id'=p_video::text)
    OR EXISTS (SELECT 1 FROM public.app_settings WHERE emergency_video_id=p_video)
    OR EXISTS (SELECT 1 FROM public.broadcast WHERE p_video=ANY(video_ids)) THEN
    RAISE EXCEPTION '사용 중인 영상입니다. 모든 재생목록 및 송출 연결을 해제하세요.' USING ERRCODE='P0001';
  END IF;

  v_key := CASE WHEN v.source='r2' THEN nullif(btrim(v.storage_path),'') END;
  -- Never delete an R2 key that looks unrelated to this system's managed video prefixes.
  IF v_key IS NOT NULL AND NOT (
      -- r2-presign: sites/{site_id}/videos/YYYY/MM/{name}.mp4
      v_key ~ '^sites/[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}/videos/[0-9]{4}/[0-9]{2}/[A-Za-z0-9가-힣._-]+$'
      -- hospital-video-presign: videos/sites/{site_id}/{uuid}-{name}.mp4
      OR v_key ~ '^videos/sites/[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}/[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}-[A-Za-z0-9가-힣._-]+$'
      -- legacy global uploader: videos/YYYY/MM/{name}.mp4
      OR v_key ~ '^videos/[0-9]{4}/[0-9]{2}/[A-Za-z0-9가-힣._-]+$'
    ) THEN
    RAISE EXCEPTION 'R2 영상 경로를 확인할 수 없습니다. 수동 확인이 필요합니다.' USING ERRCODE='P0001';
  END IF;
  -- Scoped object paths must belong to this row's hospital.
  IF v_key ~ '^(sites/|videos/sites/)' THEN
    IF v.site_id IS NULL OR NOT (
      v_key LIKE ('sites/' || v.site_id::text || '/videos/%')
      OR v_key LIKE ('videos/sites/' || v.site_id::text || '/%')
    ) THEN
      RAISE EXCEPTION 'R2 경로와 영상 소유 병원이 일치하지 않습니다.' USING ERRCODE='P0001';
    END IF;
  END IF;
  IF v_key LIKE '%..%' OR v_key LIKE '%//%' THEN
    RAISE EXCEPTION '안전하지 않은 R2 경로입니다.' USING ERRCODE='P0001';
  END IF;
  -- Legacy global keys may be shared by URL even where storage_path differs.
  IF v_key IS NOT NULL AND EXISTS(
    SELECT 1 FROM public.videos other
    WHERE other.id<>v.id AND (other.storage_path=v_key OR other.url=v.url AND v.url IS NOT NULL)
  ) THEN RAISE EXCEPTION '다른 영상에서도 동일한 파일을 사용합니다.' USING ERRCODE='P0001'; END IF;

  INSERT INTO public.video_r2_delete_jobs(video_id,site_id,object_key)
  VALUES(v.id,v.site_id,v_key);
  -- Metadata removal and retry job are committed in the SAME transaction.
  DELETE FROM public.videos WHERE id=v.id;
  RETURN jsonb_build_object('video_id',v.id,'object_key',v_key,'site_id',v.site_id,'status','pending');
END $$;

CREATE OR REPLACE FUNCTION public.video_delete_pending(p_site uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
  IF NOT public.is_admin() AND (p_site IS NULL OR NOT public.can_manage_site(p_site)) THEN
    RAISE EXCEPTION '접근 권한이 없습니다.' USING ERRCODE='42501';
  END IF;
  RETURN COALESCE((SELECT jsonb_agg(jsonb_build_object('video_id',video_id,'object_key',object_key,'site_id',site_id))
    FROM (SELECT video_id,object_key,site_id FROM public.video_r2_delete_jobs
      WHERE status='pending' AND (site_id=p_site OR (public.is_admin() AND p_site IS NULL))
      ORDER BY created_at LIMIT 20) jobs), '[]'::jsonb);
END $$;

COMMIT;


-- ===== merged from v2.35.80-short-video-keys.sql =====
-- v2.35.80: accept shortened hospital video keys while retaining legacy deletion support.
-- Requires the v2.35.79 delete-job migration to be installed first.
-- Only replaces video_delete_enqueue; no rows are deleted by running this migration.
BEGIN;
CREATE OR REPLACE FUNCTION public.video_delete_enqueue(p_video uuid, p_site uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v public.videos%ROWTYPE; j public.video_r2_delete_jobs%ROWTYPE; v_key text;
BEGIN
  -- Serialize requests for this specific video, including duplicate clicks.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_video::text, 0));
  SELECT * INTO j FROM public.video_r2_delete_jobs WHERE video_id=p_video FOR UPDATE;
  IF FOUND THEN
    IF NOT (public.is_admin() OR (j.site_id IS NOT NULL AND public.can_manage_site(j.site_id) AND p_site=j.site_id)) THEN
      RAISE EXCEPTION '삭제 작업 접근 권한이 없습니다.' USING ERRCODE='42501';
    END IF;
    RETURN jsonb_build_object('video_id',j.video_id,'object_key',j.object_key,'site_id',j.site_id,'status',j.status);
  END IF;
  SELECT * INTO v FROM public.videos WHERE id=p_video FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '영상을 찾을 수 없습니다.'; END IF;
  IF v.site_id IS NULL THEN
    IF NOT public.is_admin() THEN RAISE EXCEPTION '공용 영상은 슈퍼어드민만 삭제할 수 있습니다.' USING ERRCODE='42501'; END IF;
  ELSIF (p_site IS DISTINCT FROM v.site_id) OR NOT public.can_manage_site(v.site_id) THEN
    RAISE EXCEPTION '영상 삭제 권한이 없습니다.' USING ERRCODE='42501';
  END IF;

  -- Protect scheduled, inactive and active uses across ALL sites, not just the open hospital.
  IF EXISTS (SELECT 1 FROM public.playlist_items WHERE video_id=p_video)
    OR EXISTS (SELECT 1 FROM public.room_video_rules WHERE video_id=p_video)
    OR EXISTS (SELECT 1 FROM public.rooms WHERE p_video=ANY(manual_video_ids))
    OR EXISTS (SELECT 1 FROM public.site_broadcasts WHERE p_video=ANY(video_ids))
    OR EXISTS (SELECT 1 FROM public.group_broadcasts WHERE p_video=ANY(video_ids))
    OR EXISTS (SELECT 1 FROM public.broadcast_schedules WHERE p_video=ANY(video_ids))
    OR EXISTS (SELECT 1 FROM public.site_settings WHERE operating_config->>'emergency_video_id'=p_video::text)
    OR EXISTS (SELECT 1 FROM public.app_settings WHERE emergency_video_id=p_video)
    OR EXISTS (SELECT 1 FROM public.broadcast WHERE p_video=ANY(video_ids)) THEN
    RAISE EXCEPTION '사용 중인 영상입니다. 모든 재생목록 및 송출 연결을 해제하세요.' USING ERRCODE='P0001';
  END IF;

  v_key := CASE WHEN v.source='r2' THEN nullif(btrim(v.storage_path),'') END;
  -- Never delete an R2 key that looks unrelated to this system's managed video prefixes.
  IF v_key IS NOT NULL AND NOT (
      -- New short path: sites/{site_id}/videos/{uuid}.mp4
      v_key ~ '^sites/[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}/videos/[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}\.mp4$'
      OR
      -- r2-presign: sites/{site_id}/videos/YYYY/MM/{name}.mp4
      v_key ~ '^sites/[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}/videos/[0-9]{4}/[0-9]{2}/[A-Za-z0-9가-힣._-]+$'
      -- hospital-video-presign: videos/sites/{site_id}/{uuid}-{name}.mp4
      OR v_key ~ '^videos/sites/[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}/[0-9a-fA-F]{8}(-[0-9a-fA-F]{4}){3}-[0-9a-fA-F]{12}-[A-Za-z0-9가-힣._-]+$'
      -- legacy global uploader: videos/YYYY/MM/{name}.mp4
      OR v_key ~ '^videos/[0-9]{4}/[0-9]{2}/[A-Za-z0-9가-힣._-]+$'
    ) THEN
    RAISE EXCEPTION 'R2 영상 경로를 확인할 수 없습니다. 수동 확인이 필요합니다.' USING ERRCODE='P0001';
  END IF;
  -- Scoped object paths must belong to this row's hospital.
  IF v_key ~ '^(sites/|videos/sites/)' THEN
    IF v.site_id IS NULL OR NOT (
      v_key LIKE ('sites/' || v.site_id::text || '/videos/%')
      OR v_key LIKE ('videos/sites/' || v.site_id::text || '/%')
    ) THEN
      RAISE EXCEPTION 'R2 경로와 영상 소유 병원이 일치하지 않습니다.' USING ERRCODE='P0001';
    END IF;
  END IF;
  IF v_key LIKE '%..%' OR v_key LIKE '%//%' THEN
    RAISE EXCEPTION '안전하지 않은 R2 경로입니다.' USING ERRCODE='P0001';
  END IF;
  -- Legacy global keys may be shared by URL even where storage_path differs.
  IF v_key IS NOT NULL AND EXISTS(
    SELECT 1 FROM public.videos other
    WHERE other.id<>v.id AND (other.storage_path=v_key OR other.url=v.url AND v.url IS NOT NULL)
  ) THEN RAISE EXCEPTION '다른 영상에서도 동일한 파일을 사용합니다.' USING ERRCODE='P0001'; END IF;

  INSERT INTO public.video_r2_delete_jobs(video_id,site_id,object_key)
  VALUES(v.id,v.site_id,v_key);
  -- Metadata removal and retry job are committed in the SAME transaction.
  DELETE FROM public.videos WHERE id=v.id;
  RETURN jsonb_build_object('video_id',v.id,'object_key',v_key,'site_id',v.site_id,'status','pending');
END $$;

CREATE OR REPLACE FUNCTION public.video_delete_pending(p_site uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
  IF NOT public.is_admin() AND (p_site IS NULL OR NOT public.can_manage_site(p_site)) THEN
    RAISE EXCEPTION '접근 권한이 없습니다.' USING ERRCODE='42501';
  END IF;
  RETURN COALESCE((SELECT jsonb_agg(jsonb_build_object('video_id',video_id,'object_key',object_key,'site_id',site_id))
    FROM (SELECT video_id,object_key,site_id FROM public.video_r2_delete_jobs
      WHERE status='pending' AND (site_id=p_site OR (public.is_admin() AND p_site IS NULL))
      ORDER BY created_at LIMIT 20) jobs), '[]'::jsonb);
END $$;

COMMIT;


-- ===== merged from v2.35.81-force-bulk-playlist-delete.sql =====
-- Clinic Signage · 재생목록 일괄/강제 삭제 (미리보기 + 단일 확인 + 원자적 해제)
-- 기존 데이터는 이 SQL을 설치하는 것만으로 변경되지 않습니다.
BEGIN;
CREATE OR REPLACE FUNCTION public.hospital_bulk_delete_playlists(
  p_site uuid,
  p_ids uuid[],
  p_dry_run boolean DEFAULT true,
  p_expected_signature text DEFAULT null
) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $function$
DECLARE
  v_ids uuid[];
  v_total integer;
  v_count integer;
  v_tv_count integer;
  v_group_count integer;
  v_site_count integer;
  v_signature text;
  v_global_count integer;
BEGIN
  IF NOT public.can_manage_site(p_site) THEN
    RAISE EXCEPTION '이 병원의 관리 권한이 없습니다.' USING ERRCODE='42501';
  END IF;
  SELECT array_agg(x ORDER BY x) INTO v_ids
  FROM (SELECT DISTINCT id AS x FROM unnest(coalesce(p_ids, '{}'::uuid[])) id WHERE id IS NOT NULL) u;
  v_total := coalesce(cardinality(v_ids), 0);
  IF v_total < 1 OR v_total > 100 THEN
    RAISE EXCEPTION '재생목록은 1~100개씩 삭제할 수 있습니다.' USING ERRCODE='22023';
  END IF;
  -- 삭제 대상 자체를 잠그고 존재 여부와 범위를 서버에서 재검증한다.
  PERFORM id FROM public.playlists WHERE id=ANY(v_ids) ORDER BY id FOR UPDATE;
  SELECT count(*), count(*) FILTER (WHERE site_id IS NULL)
    INTO v_count, v_global_count
  FROM public.playlists WHERE id=ANY(v_ids)
    AND (site_id=p_site OR (site_id IS NULL AND public.is_admin()));
  IF v_count <> v_total THEN
    RAISE EXCEPTION '재생목록이 없거나 삭제 권한이 없습니다.' USING ERRCODE='42501';
  END IF;
  -- 같은 TV의 직접 연결과 층 상속 연결을 중복 집계하지 않는다.
  SELECT count(*) INTO v_tv_count
  FROM public.rooms r
  LEFT JOIN public.signage_groups g ON g.id=r.group_id
  WHERE r.default_playlist_id=ANY(v_ids)
     OR (r.default_playlist_id IS NULL AND g.default_playlist_id=ANY(v_ids));
  SELECT count(*) INTO v_group_count
  FROM public.signage_groups WHERE default_playlist_id=ANY(v_ids);
  SELECT count(*) INTO v_site_count
  FROM (
    SELECT r.site_id FROM public.rooms r
    LEFT JOIN public.signage_groups g ON g.id=r.group_id
    WHERE r.default_playlist_id=ANY(v_ids)
       OR (r.default_playlist_id IS NULL AND g.default_playlist_id=ANY(v_ids))
    UNION
    SELECT site_id FROM public.signage_groups WHERE default_playlist_id=ANY(v_ids)
  ) s;
  -- 변경 감지 지문: 선택 목록/TV 직접 연결/층 연결. 미리보기 이후 연결이 달라지면 삭제 중단.
  SELECT md5(
    coalesce((SELECT string_agg(id::text,',' ORDER BY id) FROM unnest(v_ids) id),'') || '|' ||
    coalesce((SELECT string_agg(r.id::text||':'||r.default_playlist_id::text,',' ORDER BY r.id)
      FROM public.rooms r WHERE r.default_playlist_id=ANY(v_ids)),'') || '|' ||
    coalesce((SELECT string_agg(g.id::text||':'||g.default_playlist_id::text,',' ORDER BY g.id)
      FROM public.signage_groups g WHERE g.default_playlist_id=ANY(v_ids)),'')
  ) INTO v_signature;
  IF coalesce(p_dry_run,true) THEN
    RETURN jsonb_build_object('playlist_count',v_total,'tv_count',v_tv_count,
      'group_count',v_group_count,'site_count',v_site_count,
      'global_count',v_global_count,'signature',v_signature);
  END IF;
  IF p_expected_signature IS NULL OR p_expected_signature<>v_signature THEN
    RAISE EXCEPTION '목록 연결 상태가 변경되었습니다. 다시 확인해 주세요.' USING ERRCODE='P0001';
  END IF;
  -- 모든 작업은 한 RPC/트랜잭션 안에서 실행되며 실패 시 전체 롤백된다.
  UPDATE public.rooms SET default_playlist_id=NULL WHERE default_playlist_id=ANY(v_ids);
  UPDATE public.signage_groups SET default_playlist_id=NULL WHERE default_playlist_id=ANY(v_ids);
  DELETE FROM public.playlists WHERE id=ANY(v_ids);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  IF v_count<>v_total THEN
    RAISE EXCEPTION '삭제 건수가 달라져 작업을 취소했습니다.' USING ERRCODE='P0001';
  END IF;
  RETURN jsonb_build_object('deleted_count',v_count,'playlist_count',v_total,
    'tv_count',v_tv_count,'group_count',v_group_count,'site_count',v_site_count,
    'global_count',v_global_count);
END
$function$;
REVOKE ALL ON FUNCTION public.hospital_bulk_delete_playlists(uuid,uuid[],boolean,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.hospital_bulk_delete_playlists(uuid,uuid[],boolean,text) TO anon,authenticated;
COMMIT;
-- 설치 확인(데이터 변경 없음)
SELECT to_regprocedure('public.hospital_bulk_delete_playlists(uuid,uuid[],boolean,text)') IS NOT NULL AS rpc_installed;


-- ===== merged from v2.35.83-player-diagnostics.sql =====
-- Clinic Signage v2.35.83: non-destructive diagnostics telemetry extension.
-- Run in Supabase SQL Editor BEFORE deploying the v2.35.83 player.
-- This patch edits the installed RPC definitions, retaining existing permissions and logic.
-- A mismatch aborts without changing either RPC.
BEGIN;
DO $patch$
DECLARE
  report_sql text;
  heartbeat_sql text;
  report_anchor text := '''source'',          left(coalesce(p_status->>''source'', ''''), 64),';
  heartbeat_anchor text := '''source'',left(coalesce(p_status->>''source'',''''),64),';
  new_fields text := E'\n    ''visibility_state'', case when p_status->>''visibility_state'' in (''visible'',''hidden'') then p_status->>''visibility_state'' end,\n    ''window_focused'', case when jsonb_typeof(p_status->''window_focused'')=''boolean'' then (p_status->>''window_focused'')::boolean end,';
BEGIN
  SELECT pg_get_functiondef(to_regprocedure('public.player_report(uuid,jsonb)')) INTO report_sql;
  SELECT pg_get_functiondef(to_regprocedure('public.player_heartbeat(uuid,jsonb)')) INTO heartbeat_sql;
  IF report_sql IS NULL OR heartbeat_sql IS NULL THEN
    RAISE EXCEPTION 'Required report/heartbeat functions are missing';
  END IF;
  IF position('''visibility_state''' IN report_sql)=0 THEN
    IF position(report_anchor IN report_sql)=0 THEN
      RAISE EXCEPTION 'player_report definition differs from expected schema; no changes made';
    END IF;
    report_sql := replace(report_sql,report_anchor,report_anchor || new_fields);
    EXECUTE report_sql;
  END IF;
  IF position('''visibility_state''' IN heartbeat_sql)=0 THEN
    IF position(heartbeat_anchor IN heartbeat_sql)=0 THEN
      RAISE EXCEPTION 'player_heartbeat definition differs from expected schema; transaction rolled back';
    END IF;
    heartbeat_sql := replace(heartbeat_sql,heartbeat_anchor,heartbeat_anchor || new_fields);
    EXECUTE heartbeat_sql;
  END IF;
END $patch$;
SELECT pg_notify('pgrst', 'reload schema');
COMMIT;
SELECT
  position('''visibility_state''' in pg_get_functiondef(to_regprocedure('public.player_report(uuid,jsonb)')))>0 AS report_extended,
  position('''visibility_state''' in pg_get_functiondef(to_regprocedure('public.player_heartbeat(uuid,jsonb)')))>0 AS heartbeat_extended;


-- ===== merged from v2.35.84-login-hardening.sql =====
-- Clinic Signage v2.35.84 — 로그인 반복 시도 차단 강화 + 병원 PIN 설정 속도 개선
-- Safe to rerun. 데이터 삭제 없음 (함수 2개 교체 + schema_version 기록).
--
-- 1) pin_login
--    - 병원 주소(?site=코드)로 로그인 → 그 병원 관리자 PIN만 검사
--      기본 주소(병원 코드 없음)      → 슈퍼어드민 PIN만 검사
--      (이전에는 병원 주소에서도 슈퍼어드민 PIN을 먼저 검사해서, 병원 주소 100곳이 모두
--       슈퍼어드민 PIN을 대입해 볼 수 있는 통로였음)
--    - 계정(범위)별 잠금 추가: 같은 대상에 15분 안에 10번 틀리면 15분 잠금.
--      기존 기기 ID(p_client_id)·IP 잠금은 둘 다 요청자가 바꿀 수 있어서 우회 가능했음.
--      PIN 자리수 정책은 그대로.
-- 2) admin_set_site_staff_pin
--    - "다른 병원에서 사용 중인 PIN" 검사 제거. 로그인이 병원 코드로 분리되어 있어 PIN이 겹쳐도 문제가 없고,
--      이 검사는 모든 병원 계정에 bcrypt를 한 번씩 돌려서 병원 수에 비례해 느려짐
--      (병원 수십 곳부터 Supabase 기본 statement timeout에 걸려 PIN 설정이 실패할 수 있음).

begin;

create or replace function public.pin_login(p_pin text,p_client_id text,p_site_code text default null)
returns jsonb language plpgsql security definer set search_path=public,extensions as $$
declare
  v_client text:=left(trim(coalesce(p_client_id,'')),100);
  v_site_code text:=lower(trim(coalesce(p_site_code,'')));
  v_ip_key text:='ip:'||coalesce(public.pin_request_ip(),'unknown');
  v_scope_key text;
  v_fail int:=0; v_locked timestamptz;
  v_ip_fail int:=0; v_ip_locked timestamptz; v_ip_updated timestamptz;
  v_scope_fail int:=0; v_scope_locked timestamptz; v_scope_updated timestamptz;
  v_account public.pin_accounts; v_token text; v_exp timestamptz; v_now timestamptz:=clock_timestamp();
  c_window constant interval:=interval '15 minutes';
  c_ip_max constant int:=20;
  c_scope_max constant int:=10;
begin
  if v_client='' or v_client !~ '^[A-Za-z0-9._:-]{8,100}$' then return jsonb_build_object('ok',false,'error','invalid_client'); end if;
  if p_pin !~ '^[0-9]{4,6}$' then return jsonb_build_object('ok',false,'error','invalid_pin'); end if;
  if v_site_code<>'' and v_site_code !~ '^[a-z0-9_-]{1,64}$' then return jsonb_build_object('ok',false,'error','invalid_pin'); end if;
  v_scope_key:=case when v_site_code='' then 'scope:admin' else 'scope:site:'||v_site_code end;

  -- 잠금 확인: 대상(범위) → IP → 기기 순
  select failed_count,locked_until,updated_at into v_scope_fail,v_scope_locked,v_scope_updated from public.pin_login_throttle where client_id=v_scope_key;
  if v_scope_locked is not null and v_scope_locked>v_now then return jsonb_build_object('ok',false,'error','locked','retry_after_sec',greatest(1,ceil(extract(epoch from(v_scope_locked-v_now)))::int)); end if;
  if v_scope_updated is null or v_scope_updated<v_now-c_window then v_scope_fail:=0; end if;

  select failed_count,locked_until,updated_at into v_ip_fail,v_ip_locked,v_ip_updated from public.pin_login_throttle where client_id=v_ip_key;
  if v_ip_locked is not null and v_ip_locked>v_now then return jsonb_build_object('ok',false,'error','locked','retry_after_sec',greatest(1,ceil(extract(epoch from(v_ip_locked-v_now)))::int)); end if;
  if v_ip_updated is null or v_ip_updated<v_now-c_window then v_ip_fail:=0; end if;

  select failed_count,locked_until into v_fail,v_locked from public.pin_login_throttle where client_id=v_client;
  if v_locked is not null and v_locked>v_now then return jsonb_build_object('ok',false,'error','locked','retry_after_sec',greatest(1,ceil(extract(epoch from(v_locked-v_now)))::int)); end if;

  -- 계정 조회: 주소에 따라 한 종류만 (bcrypt 1회)
  if v_site_code='' then
    select a.* into v_account from public.pin_accounts a
     where a.enabled and a.role='admin' and crypt(p_pin,a.pin_hash)=a.pin_hash
     order by a.id limit 1;
  else
    select a.* into v_account
    from public.pin_accounts a join public.sites s on s.id=a.site_id
    where a.enabled and a.role='staff' and s.active and s.code=v_site_code
      and crypt(p_pin,a.pin_hash)=a.pin_hash
    order by a.id limit 1;
  end if;

  if v_account.id is null then
    -- 대상(범위) 잠금: 요청자가 바꿀 수 없는 기준
    v_scope_fail:=coalesce(v_scope_fail,0)+1;
    insert into public.pin_login_throttle(client_id,failed_count,locked_until,updated_at)
    values(v_scope_key,case when v_scope_fail>=c_scope_max then 0 else v_scope_fail end,case when v_scope_fail>=c_scope_max then v_now+c_window end,v_now)
    on conflict(client_id) do update set failed_count=excluded.failed_count,locked_until=excluded.locked_until,updated_at=excluded.updated_at;

    v_ip_fail:=coalesce(v_ip_fail,0)+1;
    insert into public.pin_login_throttle(client_id,failed_count,locked_until,updated_at)
    values(v_ip_key,case when v_ip_fail>=c_ip_max then 0 else v_ip_fail end,case when v_ip_fail>=c_ip_max then v_now+c_window end,v_now)
    on conflict(client_id) do update set failed_count=excluded.failed_count,locked_until=excluded.locked_until,updated_at=excluded.updated_at;

    if v_scope_fail>=c_scope_max or v_ip_fail>=c_ip_max then
      -- 비로그인 상태라 audit_event(권한 검사)를 쓰지 않고 직접 기록. 슈퍼어드민 화면 감사 로그에서 확인.
      insert into public.audit_log(site_id,actor_role,action,entity_type,entity_id,summary,after_state)
      values((select s.id from public.sites s where v_site_code<>'' and s.code=v_site_code limit 1),null,'security','login_lock',v_scope_key,
             'PIN 반복 실패로 로그인 잠금',jsonb_build_object('scope',v_scope_key,'scope_fail',v_scope_fail,'ip_fail',v_ip_fail));
      return jsonb_build_object('ok',false,'error','locked','retry_after_sec',extract(epoch from c_window)::int);
    end if;

    v_fail:=coalesce(v_fail,0)+1;
    if v_fail>=5 then
      insert into public.pin_login_throttle(client_id,failed_count,locked_until,updated_at) values(v_client,0,v_now+interval '5 minutes',v_now)
      on conflict(client_id) do update set failed_count=0,locked_until=excluded.locked_until,updated_at=v_now;
      return jsonb_build_object('ok',false,'error','locked','retry_after_sec',300);
    end if;
    insert into public.pin_login_throttle(client_id,failed_count,locked_until,updated_at) values(v_client,v_fail,null,v_now)
    on conflict(client_id) do update set failed_count=excluded.failed_count,locked_until=null,updated_at=v_now;
    return jsonb_build_object('ok',false,'error','invalid_pin');
  end if;

  delete from public.pin_login_throttle where client_id in(v_client,v_ip_key,v_scope_key);
  delete from public.pin_login_throttle where locked_until is null and updated_at<v_now-interval '1 day';
  delete from public.pin_sessions where expires_at<=v_now;
  v_token:=encode(gen_random_bytes(32),'hex'); v_exp:=v_now+interval '12 hours';
  insert into public.pin_sessions(account_id,token_hash,expires_at) values(v_account.id,digest(v_token,'sha256'),v_exp);
  return jsonb_build_object('ok',true,'token',v_token,'role',v_account.role,'site_id',v_account.site_id,'expires_at',v_exp);
end $$;
revoke all on function public.pin_login(text,text,text) from public;
grant execute on function public.pin_login(text,text,text) to anon,authenticated;

create or replace function public.admin_set_site_staff_pin(p_site uuid,p_pin text)
returns void language plpgsql security definer set search_path=public,extensions as $$
declare v_account bigint;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  if not exists(select 1 from public.sites where id=p_site) then raise exception 'site not found'; end if;
  if not exists(select 1 from public.sites where id=p_site and active) then raise exception '비활성 병원은 PIN을 변경할 수 없습니다'; end if;
  if p_pin !~ '^[0-9]{4,6}$' then raise exception '병원 관리자 PIN은 숫자 4~6자리여야 합니다'; end if;
  -- 슈퍼어드민 계정은 보통 1개라 비용이 작다. 같은 PIN이면 운영 혼선이 생기므로 유지.
  if exists(select 1 from public.pin_accounts a where a.enabled and a.role='admin' and crypt(p_pin,a.pin_hash)=a.pin_hash) then raise exception '슈퍼어드민 PIN과 병원 관리자 PIN은 달라야 합니다'; end if;
  select id into v_account from public.pin_accounts where role='staff' and site_id=p_site order by id limit 1;
  if v_account is null then insert into public.pin_accounts(role,site_id,pin_hash,enabled,updated_at) values('staff',p_site,crypt(p_pin,gen_salt('bf',10)),true,clock_timestamp()) returning id into v_account;
  else update public.pin_accounts set pin_hash=crypt(p_pin,gen_salt('bf',10)),enabled=true,updated_at=clock_timestamp() where id=v_account; end if;
  delete from public.pin_sessions where account_id=v_account;
  delete from public.pin_login_throttle where client_id='scope:site:'||(select lower(code) from public.sites where id=p_site);
  perform public.audit_event(p_site,'update','access',v_account::text,'병원 관리자 PIN 변경',null,null);
end $$;
revoke all on function public.admin_set_site_staff_pin(uuid,text) from public;
grant execute on function public.admin_set_site_staff_pin(uuid,text) to anon,authenticated;

insert into public.schema_version(version,applied_at) values('2.35.84',clock_timestamp())
on conflict(version) do update set applied_at=excluded.applied_at;
notify pgrst,'reload schema';
commit;


-- ===== merged from v2.35.85-tv-pairing.sql =====
-- Clinic Signage v2.35.85 — TV 연결 코드(페어링)
-- Safe to rerun. 기존 데이터 변경 없음 (테이블 1개 + 함수 3개 추가).
--
-- 흐름
--   1) 설치형 플레이어가 처음 켜지면 pairing_request(기기ID) → 6자리 코드를 TV 화면에 크게 표시
--   2) 병원 관리자가 디스플레이 설정에서 그 코드를 입력 → hospital_pair_display(디스플레이, 코드)
--   3) 플레이어가 pairing_poll(기기ID, 코드)로 확인 → 그 디스플레이의 player_key를 받아 송출 시작
-- player_key는 코드를 만든 기기(기기ID+코드 둘 다 일치)에게만, 한 번만 전달된다.

begin;

create table if not exists public.player_pairing_codes (
  code text primary key check (code ~ '^[0-9]{6}$'),
  device_id text not null unique check (device_id ~ '^[A-Za-z0-9_-]{16,64}$'),
  room_id uuid references public.rooms(id) on delete cascade,
  created_at timestamptz not null default clock_timestamp(),
  expires_at timestamptz not null,
  paired_at timestamptz
);
create index if not exists player_pairing_codes_expires_idx on public.player_pairing_codes(expires_at);
alter table public.player_pairing_codes enable row level security;
revoke all on table public.player_pairing_codes from public, anon, authenticated;

-- 플레이어: 연결 코드 발급 (같은 기기는 만료 전까지 같은 코드)
create or replace function public.pairing_request(p_device_id text)
returns jsonb language plpgsql security definer set search_path=public,extensions as $$
declare
  v_device text:=trim(coalesce(p_device_id,''));
  v_now timestamptz:=clock_timestamp();
  v_ip_key text:='pair:'||coalesce(public.pin_request_ip(),'unknown');
  v_count int; v_updated timestamptz;
  v_row public.player_pairing_codes;
  v_code text; i int;
begin
  if v_device !~ '^[A-Za-z0-9_-]{16,64}$' then return jsonb_build_object('ok',false,'error','invalid_device'); end if;

  -- 같은 IP에서 10분에 60회까지 (병원 한 곳에서 TV 여러 대를 동시에 설치해도 충분)
  select failed_count,updated_at into v_count,v_updated from public.pin_login_throttle where client_id=v_ip_key;
  if v_updated is null or v_updated<v_now-interval '10 minutes' then v_count:=0; end if;
  if v_count>=60 then return jsonb_build_object('ok',false,'error','rate_limited','retry_after_sec',600); end if;
  insert into public.pin_login_throttle(client_id,failed_count,locked_until,updated_at) values(v_ip_key,v_count+1,null,case when v_count=0 then v_now else coalesce(v_updated,v_now) end)
  on conflict(client_id) do update set failed_count=excluded.failed_count,updated_at=excluded.updated_at;

  delete from public.player_pairing_codes where expires_at<v_now;

  select * into v_row from public.player_pairing_codes where device_id=v_device;
  if v_row.code is not null and v_row.room_id is null then
    return jsonb_build_object('ok',true,'code',v_row.code,'expires_at',v_row.expires_at,'ttl_sec',greatest(1,floor(extract(epoch from v_row.expires_at-v_now))::int));
  end if;
  if v_row.code is not null then
    -- 이미 연결된 코드: 플레이어가 poll로 받아가야 함
    return jsonb_build_object('ok',true,'code',v_row.code,'expires_at',v_row.expires_at,'ttl_sec',greatest(1,floor(extract(epoch from v_row.expires_at-v_now))::int),'paired',true);
  end if;

  for i in 1..30 loop
    v_code:=lpad(((('x'||encode(gen_random_bytes(4),'hex'))::bit(32)::bigint)%1000000)::text,6,'0');
    begin
      insert into public.player_pairing_codes(code,device_id,expires_at) values(v_code,v_device,v_now+interval '10 minutes');
      return jsonb_build_object('ok',true,'code',v_code,'expires_at',v_now+interval '10 minutes','ttl_sec',600);
    exception when unique_violation then
      -- 코드 충돌이면 다시 뽑기. 기기ID 충돌(동시 요청)이면 기존 코드 반환
      select * into v_row from public.player_pairing_codes where device_id=v_device;
      if v_row.code is not null then
        return jsonb_build_object('ok',true,'code',v_row.code,'expires_at',v_row.expires_at,'ttl_sec',greatest(1,floor(extract(epoch from v_row.expires_at-v_now))::int));
      end if;
    end;
  end loop;
  return jsonb_build_object('ok',false,'error','busy');
end $$;

-- 플레이어: 연결 여부 확인. 연결되면 player_key를 한 번만 전달하고 코드 삭제
create or replace function public.pairing_poll(p_device_id text,p_code text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare
  v_row public.player_pairing_codes; v_key uuid; v_name text; v_site text;
begin
  if coalesce(p_device_id,'') !~ '^[A-Za-z0-9_-]{16,64}$' or coalesce(p_code,'') !~ '^[0-9]{6}$' then
    return jsonb_build_object('ok',false,'status','expired');
  end if;
  select * into v_row from public.player_pairing_codes where device_id=p_device_id and code=p_code;
  if v_row.code is null then return jsonb_build_object('ok',true,'status','expired'); end if;
  if v_row.room_id is null then
    if v_row.expires_at<clock_timestamp() then
      delete from public.player_pairing_codes where code=v_row.code;
      return jsonb_build_object('ok',true,'status','expired');
    end if;
    return jsonb_build_object('ok',true,'status','pending','ttl_sec',greatest(1,floor(extract(epoch from v_row.expires_at-clock_timestamp()))::int));
  end if;
  select r.player_key,r.name,s.name into v_key,v_name,v_site from public.rooms r left join public.sites s on s.id=r.site_id where r.id=v_row.room_id;
  delete from public.player_pairing_codes where code=v_row.code;
  if v_key is null then return jsonb_build_object('ok',true,'status','expired'); end if;
  return jsonb_build_object('ok',true,'status','paired','player_key',v_key,'room_name',v_name,'site_name',v_site);
end $$;

-- 병원 관리자/슈퍼어드민: TV 화면의 코드를 입력해 디스플레이에 연결
create or replace function public.hospital_pair_display(p_room uuid,p_code text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare
  v_site uuid; v_name text; v_code text:=regexp_replace(coalesce(p_code,''),'[^0-9]','','g');
  v_fail_key text; v_fail int; v_updated timestamptz; v_now timestamptz:=clock_timestamp(); v_device text;
begin
  select r.site_id,r.name into v_site,v_name from public.rooms r where r.id=p_room;
  if v_site is null then raise exception '디스플레이를 찾을 수 없습니다'; end if;
  if not public.can_manage_site(v_site) then raise exception 'not allowed'; end if;
  if v_code !~ '^[0-9]{6}$' then raise exception 'TV 화면의 6자리 숫자를 입력하세요'; end if;

  -- 잘못된 코드 반복 입력 제한 (병원당 10분에 10회)
  v_fail_key:='pairfail:'||v_site::text;
  select failed_count,updated_at into v_fail,v_updated from public.pin_login_throttle where client_id=v_fail_key;
  if v_updated is null or v_updated<v_now-interval '10 minutes' then v_fail:=0; end if;
  if v_fail>=10 then raise exception '연결 코드를 여러 번 잘못 입력했습니다. 10분 후 다시 시도하세요'; end if;

  update public.player_pairing_codes set room_id=p_room,paired_at=v_now
   where code=v_code and room_id is null and expires_at>v_now
  returning device_id into v_device;
  if v_device is null then
    insert into public.pin_login_throttle(client_id,failed_count,locked_until,updated_at) values(v_fail_key,v_fail+1,null,case when v_fail=0 then v_now else v_updated end)
    on conflict(client_id) do update set failed_count=excluded.failed_count,updated_at=excluded.updated_at;
    raise exception '연결 코드가 없거나 만료되었습니다. TV 화면의 코드를 다시 확인하세요';
  end if;
  delete from public.pin_login_throttle where client_id=v_fail_key;
  perform public.audit_event(v_site,'update','display',p_room::text,'TV 연결 코드로 플레이어 연결',null,jsonb_build_object('room',v_name));
  return jsonb_build_object('ok',true,'room_name',v_name);
end $$;

revoke all on function public.pairing_request(text), public.pairing_poll(text,text), public.hospital_pair_display(uuid,text) from public;
grant execute on function public.pairing_request(text), public.pairing_poll(text,text), public.hospital_pair_display(uuid,text) to anon,authenticated;

insert into public.schema_version(version,applied_at) values('2.35.85',clock_timestamp())
on conflict(version) do update set applied_at=excluded.applied_at;
notify pgrst,'reload schema';
commit;



-- ===== merged from v2.35.85-db-sync.sql =====
-- Clinic Signage v2.35.85 — 운영 DB ↔ 저장소 동기화
-- Safe to rerun. 데이터 삭제 없음(중복 인덱스 2개·권한 과다 정책 1개 제거, 예전 알림 트리거 교체).
--
-- A. 운영 DB에 빠져 있던 것 추가 (저장소 기준)
--    - 2.34.78 병원 단위 TV 알림: player_control_signals.site_id, 문장 단위 알림 트리거 9개, 인덱스
--      (기존: 영상·재생목록 하나만 바뀌어도 전체 병원 TV를 깨움 → 해당 병원 TV만)
--    - 2.34.77 디스플레이 삭제 안전장치(환자 배정 중 삭제 금지) / 한글 오류 메시지
--    - 2.34.96 층·공간 안내 컬럼(content_reason, patient_context_note)
--    - 2.34.70 층 공간 중복 방지 인덱스 (운영 중복 0건 확인)
--    - 2.35.06 성능: player_get_state 썸네일 제외, 실시간 상태 조회 1회 평가, 중복 인덱스 2개 제거,
--      Realtime 발행 테이블 정리(player_control_signals만)
--    - 2.35.78 슈퍼어드민 공용 재생목록 저장 / 공용 영상 삭제 함수
--    - 오늘 완료 환자 기준을 한국 자정으로 (hospital_reception_state)
-- B. 운영 DB에만 있던 것은 그대로 유지하고 저장소(schema.sql)에도 기록
--    - 운영 쪽이 더 최신인 함수 유지: player_get_state_lite(sha256·playlist_hash, TV가 사용),
--      staff_room_list(병원 범위 제한), admin_undo_control 등
--    - 운영 전용 함수 11개·media_gc_queue·영상 검증 컬럼 등
-- C. 보안: player_live_status_read(누구나 전체 병원 TV 상태 조회 가능) 정책 제거
--    → 병원 관리자/슈퍼어드민만 조회하는 기존 정책(player_live_status_member_select)만 남김

begin;

-- ---------- 1. 테이블/컬럼 ----------
alter table public.player_control_signals add column if not exists site_id uuid references public.sites(id) on delete cascade;
update public.player_control_signals pcs set site_id=r.site_id
  from public.rooms r where r.id=pcs.room_id and pcs.site_id is distinct from r.site_id;

alter table public.floor_spaces add column if not exists content_reason text;
alter table public.floor_spaces add column if not exists patient_context_note text;
alter table public.tags add column if not exists content_reason text;
alter table public.tags add column if not exists patient_context_note text;

-- 운영 전용 컬럼 (신규 설치에도 동일하게)
alter table public.app_settings add column if not exists operating_start time not null default '09:00:00';
alter table public.app_settings add column if not exists operating_end time not null default '20:00:00';
alter table public.rooms add column if not exists control_revision bigint not null default 0;
alter table public.rooms add column if not exists control_updated_at timestamptz;
alter table public.videos add column if not exists width_px integer;
alter table public.videos add column if not exists height_px integer;
alter table public.videos add column if not exists sha256 text;
alter table public.videos add column if not exists validation_status text not null default 'unknown';
alter table public.videos add column if not exists validation_note text;

create table if not exists public.media_gc_queue (
  id bigint generated by default as identity primary key,
  site_id uuid,
  storage_path text not null,
  reason text not null,
  queued_at timestamptz not null default now(),
  delete_after timestamptz not null default (now() + interval '30 days'),
  deleted_at timestamptz,
  last_error text
);
create unique index if not exists media_gc_queue_open_path_uidx on public.media_gc_queue(storage_path) where deleted_at is null;
alter table public.media_gc_queue enable row level security;

create table if not exists public.pin_login_failures (
  id bigint generated by default as identity primary key,
  failed_at timestamptz not null default clock_timestamp()
);
create index if not exists pin_login_failures_at_idx on public.pin_login_failures(failed_at);
alter table public.pin_login_failures enable row level security;

-- ---------- 2. 함수: 저장소 기준으로 올림 ----------
CREATE OR REPLACE FUNCTION public.ensure_player_control_signal()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  insert into public.player_control_signals(room_id,site_id,revision,updated_at)
  values(new.id,new.site_id,0,clock_timestamp())
  on conflict(room_id) do update set site_id=excluded.site_id;
  return new;
end $function$;
CREATE OR REPLACE FUNCTION public.signal_site_rooms_internal(p_site uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_count integer:=0;
begin
  insert into public.player_control_signals(room_id,site_id,revision,updated_at)
  select r.id,r.site_id,1,clock_timestamp()
  from public.rooms r
  where (p_site is null or r.site_id=p_site)
    and coalesce(r.display_control_mode,'remote') in ('remote','hybrid')
  on conflict(room_id) do update
    set site_id=excluded.site_id,revision=public.player_control_signals.revision+1,updated_at=excluded.updated_at;
  get diagnostics v_count=row_count;
  return v_count;
end $function$;
CREATE OR REPLACE FUNCTION public.signal_site_rooms(p_site uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.can_manage_site(p_site) then raise exception 'not allowed'; end if;
  return public.signal_site_rooms_internal(p_site);
end $function$;
CREATE OR REPLACE FUNCTION public.signal_signage_rooms(p_room_ids uuid[] DEFAULT NULL::uuid[], p_group uuid DEFAULT NULL::uuid, p_all boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_count integer:=0; v_site uuid:=coalesce(public.pin_session_site_id(),public.default_site_id());
begin
  if not public.is_member() then raise exception 'not allowed'; end if;
  if (coalesce(p_all,false) or p_group is not null) and not public.is_admin() then raise exception 'not allowed'; end if;
  if not public.is_admin() and exists(select 1 from unnest(coalesce(p_room_ids,'{}'::uuid[])) x where not public.staff_can_remote_control_room(x)) then raise exception 'not allowed'; end if;
  if not coalesce(p_all,false) and p_group is null and coalesce(array_length(p_room_ids,1),0)=0 then return 0; end if;
  insert into public.player_control_signals(room_id,site_id,revision,updated_at)
  select r.id,r.site_id,1,clock_timestamp() from public.rooms r
  where coalesce(r.display_control_mode,'remote') in ('remote','hybrid') and (
        (public.is_admin() and (coalesce(p_all,false) or (p_group is not null and r.group_id=p_group)))
     or (coalesce(array_length(p_room_ids,1),0)>0 and r.id=any(p_room_ids) and (public.is_admin() or r.site_id=v_site)))
  on conflict(room_id) do update set site_id=excluded.site_id,revision=public.player_control_signals.revision+1,updated_at=excluded.updated_at;
  get diagnostics v_count=row_count; return v_count;
end $function$;
