CREATE OR REPLACE FUNCTION public.admin_create_site(p_name text, p_code text, p_building_label text DEFAULT 'MAIN BUILDING'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_name text:=btrim(coalesce(p_name,''));
  v_code text:=lower(btrim(coalesce(p_code,'')));
  v_building text:=coalesce(nullif(btrim(coalesce(p_building_label,'')),''),'MAIN BUILDING');
  v_site public.sites%rowtype;
begin
  if not public.is_admin() then raise exception 'ADMIN_REQUIRED'; end if;
  if v_name='' then return jsonb_build_object('ok',false,'code','SITE_NAME_REQUIRED','message','병원명을 입력하세요.'); end if;
  if v_code='' or length(v_code)>32 or v_code !~ '^[a-z0-9][a-z0-9_-]*$' then return jsonb_build_object('ok',false,'code','SITE_CODE_INVALID','message','병원 코드는 영문 소문자, 숫자, - 또는 _만 사용할 수 있습니다.'); end if;
  insert into public.sites(code,name,building_label,active,updated_at)
  values(v_code,v_name,v_building,true,clock_timestamp())
  on conflict(code) do nothing returning * into v_site;
  if v_site.id is null then
    select * into v_site from public.sites where code=v_code limit 1;
    if v_site.id is null then raise exception 'SITE_CREATE_FAILED'; end if;
    insert into public.site_settings(site_id) values(v_site.id) on conflict(site_id) do nothing;
    return jsonb_build_object('ok',true,'existing',true,'code','SITE_CODE_EXISTS','message','이미 등록된 병원입니다.','site',to_jsonb(v_site));
  end if;
  insert into public.site_settings(site_id) values(v_site.id) on conflict(site_id) do nothing;
  return jsonb_build_object('ok',true,'existing',false,'site',to_jsonb(v_site));
end
$function$;
CREATE OR REPLACE FUNCTION public.admin_import_site_config(p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_site uuid; g jsonb; r jsonb; sp jsonb; v_groups int:=0; v_rooms int:=0; v_spaces int:=0;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  v_site:=coalesce(nullif(p_config#>>'{site,id}','')::uuid,public.default_site_id());
  if not exists(select 1 from public.sites where id=v_site) then raise exception 'site not found'; end if;
  update public.sites set name=coalesce(nullif(p_config#>>'{site,name}',''),name),building_label=coalesce(nullif(p_config#>>'{site,building_label}',''),building_label),updated_at=clock_timestamp() where id=v_site;
  if jsonb_typeof(p_config->'settings')='object' then insert into public.site_settings(site_id,floorplan_assets,operating_config,updated_at) values(v_site,coalesce(p_config#>'{settings,floorplan_assets}','{}'::jsonb),coalesce(p_config#>'{settings,operating_config}','{}'::jsonb),clock_timestamp()) on conflict(site_id) do update set floorplan_assets=excluded.floorplan_assets,operating_config=excluded.operating_config,updated_at=clock_timestamp(); end if;
  if jsonb_typeof(p_config->'groups')='array' then for g in select * from jsonb_array_elements(p_config->'groups') loop update public.signage_groups set name=coalesce(nullif(g->>'name',''),name),kind=coalesce(nullif(g->>'kind',''),kind),floor_number=coalesce((g->>'floor_number')::smallint,floor_number),care_type=coalesce(nullif(g->>'care_type',''),care_type),signage_purpose=g->>'signage_purpose',target_audience=g->>'target_audience',waiting_area_note=g->>'waiting_area_note',signage_reason=g->>'signage_reason',content_intro=g->>'content_intro',content_topics=coalesce(array(select jsonb_array_elements_text(coalesce(g->'content_topics','[]'::jsonb))),'{}'::text[]),role_label=g->>'role_label',default_playlist_id=nullif(g->>'default_playlist_id','')::uuid,sort_order=coalesce((g->>'sort_order')::int,sort_order) where id=(g->>'id')::uuid and site_id=v_site; if found then v_groups:=v_groups+1; end if; end loop; end if;
  if jsonb_typeof(p_config->'rooms')='array' then for r in select * from jsonb_array_elements(p_config->'rooms') loop update public.rooms set name=coalesce(nullif(r->>'name',''),name),group_id=nullif(r->>'group_id','')::uuid,room_mode=coalesce(nullif(r->>'room_mode',''),room_mode),map_x_pct=nullif(r->>'map_x_pct','')::numeric,map_y_pct=nullif(r->>'map_y_pct','')::numeric,display_control_mode=coalesce(nullif(r->>'display_control_mode',''),display_control_mode),display_note=r->>'display_note' where id=(r->>'id')::uuid and site_id=v_site; if found then v_rooms:=v_rooms+1; end if; end loop; end if;
  if jsonb_typeof(p_config->'spaces')='array' then delete from public.floor_spaces where site_id=v_site; for sp in select * from jsonb_array_elements(p_config->'spaces') loop insert into public.floor_spaces(id,site_id,group_id,name,space_type,x_pct,y_pct,width_pct,height_pct,sort_order) values(coalesce(nullif(sp->>'id','')::uuid,gen_random_uuid()),v_site,nullif(sp->>'group_id','')::uuid,coalesce(nullif(sp->>'name',''),'공간'),coalesce(nullif(sp->>'space_type',''),'other'),coalesce((sp->>'x_pct')::numeric,0),coalesce((sp->>'y_pct')::numeric,0),coalesce((sp->>'width_pct')::numeric,10),coalesce((sp->>'height_pct')::numeric,10),coalesce((sp->>'sort_order')::int,0)); v_spaces:=v_spaces+1; end loop; end if;
  perform public.audit_event(v_site,'restore','site_config',v_site::text,'사이트 설정 백업 복원',null,jsonb_build_object('groups',v_groups,'rooms',v_rooms,'spaces',v_spaces));
  return jsonb_build_object('ok',true,'groups',v_groups,'rooms',v_rooms,'spaces',v_spaces);
end $function$;
CREATE OR REPLACE FUNCTION public.hospital_delete_display(p_site uuid, p_room uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_x numeric;
  v_y numeric;
begin
  if not public.can_manage_site(p_site) then raise exception '이 병원의 디스플레이를 삭제할 권한이 없습니다.'; end if;
  select map_x_pct,map_y_pct into v_x,v_y from public.rooms where id=p_room and site_id=p_site;
  if not found then raise exception '디스플레이를 찾을 수 없습니다.'; end if;
  if v_x is not null or v_y is not null then raise exception '배치된 디스플레이는 위치를 먼저 해제하세요.'; end if;
  if exists(select 1 from public.patient_sessions where site_id=p_site and room_id=p_room and status in ('assigned','in_progress')) then
    raise exception '현재 환자가 배정된 디스플레이는 삭제할 수 없습니다. 환자 배정을 먼저 해제하세요.';
  end if;
  delete from public.rooms where id=p_room and site_id=p_site;
end $function$;
CREATE OR REPLACE FUNCTION public.hospital_rename_display(p_site uuid, p_room uuid, p_name text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_group uuid;
  v_name text:=trim(coalesce(p_name,''));
begin
  if not public.can_manage_site(p_site) then raise exception '이 병원의 디스플레이를 수정할 권한이 없습니다.'; end if;
  if v_name='' then raise exception '디스플레이 이름을 입력하세요.'; end if;
  select group_id into v_group from public.rooms where id=p_room and site_id=p_site;
  if not found then raise exception '디스플레이를 찾을 수 없습니다.'; end if;
  if exists(select 1 from public.rooms where site_id=p_site and group_id is not distinct from v_group and id<>p_room and lower(trim(name))=lower(v_name)) then
    raise exception '같은 층에 동일한 디스플레이 이름이 이미 있습니다.';
  end if;
  update public.rooms set name=v_name where id=p_room and site_id=p_site;
end $function$;
CREATE OR REPLACE FUNCTION public.hospital_display_slot_key(p_name text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
declare
  v text:=lower(trim(coalesce(p_name,'')));
  v_token text;
begin
  if v='' then return ''; end if;

  -- Remove common floor prefixes: 10F_01, 10층-01, 10 01, etc.
  v:=regexp_replace(v,'^[[:space:]]*[0-9]+[[:space:]]*(f|층)?[[:space:]_\-./]*','','i');
  v:=trim(v);

  -- Prefer a leading numeric position code when present. 01 and 1 become the same key.
  v_token:=substring(v from '^0*([0-9]+)');
  if v_token is not null and v_token<>'' then
    return 'n:'||((v_token)::bigint)::text;
  end if;

  -- Otherwise normalize the remaining location/name token.
  v:=regexp_replace(v,'[^0-9a-z가-힣]+','','g');
  return case when v='' then lower(trim(coalesce(p_name,''))) else 's:'||v end;
end
$function$;
CREATE OR REPLACE FUNCTION public.hospital_reception_state(p_site uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_site uuid; v_rooms jsonb; v_groups jsonb; v_patients jsonb; v_broadcast jsonb; v_playlists jsonb; v_videos jsonb; v_items jsonb; v_rules jsonb; v_site_row jsonb; v_floorplans jsonb; v_spaces jsonb; v_versions jsonb; v_settings jsonb;
begin
  if not public.is_member() then raise exception 'not allowed'; end if;
  v_site:=case when public.is_admin() then p_site else public.pin_session_site_id() end;
  if v_site is null or (not public.is_admin() and p_site is not null and p_site<>v_site) or not public.can_manage_site(v_site) then raise exception 'not allowed'; end if;
  select to_jsonb(s) into v_site_row from public.sites s where s.id=v_site; if v_site_row is null then raise exception 'site not found'; end if;
  select coalesce(ss.floorplan_assets,'{}'::jsonb),coalesce(ss.operating_config,'{}'::jsonb) into v_floorplans,v_settings from public.site_settings ss where ss.site_id=v_site;
  select coalesce(jsonb_agg(to_jsonb(fs) order by fs.sort_order,fs.created_at),'[]'::jsonb) into v_spaces from public.floor_spaces fs where fs.site_id=v_site;
  select coalesce(jsonb_agg(to_jsonb(fv) order by fv.created_at desc),'[]'::jsonb) into v_versions from public.floorplan_versions fv where fv.site_id=v_site;
  select coalesce(jsonb_agg(jsonb_build_object('id',r.id,'site_id',r.site_id,'name',r.name,'sort_order',r.sort_order,'group_id',r.group_id,'group_name',g.name,'room_mode',r.room_mode,'last_seen_at',r.last_seen_at,'player_status',coalesce(r.player_status,'{}'::jsonb),'session_timeout_min',r.session_timeout_min,'session_started_at',r.session_started_at,'session_age_group',r.session_age_group,'session_gender',r.session_gender,'session_treatment',r.session_treatment,'default_playlist_id',r.default_playlist_id,'manual_active',r.manual_active,'manual_video_ids',r.manual_video_ids,'map_x_pct',r.map_x_pct,'map_y_pct',r.map_y_pct,'display_control_mode',r.display_control_mode,'manual_check_status',r.manual_check_status,'manual_checked_at',r.manual_checked_at,'manual_checked_by',r.manual_checked_by,'display_note',r.display_note,'floor_space_id',r.floor_space_id) order by coalesce(g.sort_order,2147483647),r.sort_order,r.created_at),'[]'::jsonb) into v_rooms from public.rooms r left join public.signage_groups g on g.id=r.group_id where r.site_id=v_site;
  select coalesce(jsonb_agg(jsonb_build_object('id',g.id,'site_id',g.site_id,'name',g.name,'kind',g.kind,'floor_number',g.floor_number,'care_type',g.care_type,'signage_purpose',g.signage_purpose,'target_audience',g.target_audience,'waiting_area_note',g.waiting_area_note,'signage_reason',g.signage_reason,'content_intro',g.content_intro,'content_topics',g.content_topics,'role_label',g.role_label,'default_playlist_id',g.default_playlist_id,'sort_order',g.sort_order) order by g.sort_order,g.floor_number,g.created_at),'[]'::jsonb) into v_groups from public.signage_groups g where g.site_id=v_site;
  select coalesce(jsonb_agg(to_jsonb(x) order by case x.status when 'in_progress' then 0 when 'assigned' then 1 when 'waiting' then 2 else 3 end,x.waiting_started_at),'[]'::jsonb) into v_patients from (select * from public.patient_sessions where site_id=v_site and (status in ('waiting','assigned','in_progress') or (status='completed' and completed_at >= (date_trunc('day', clock_timestamp() at time zone 'Asia/Seoul') at time zone 'Asia/Seoul')))) x;
  select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'site_id',p.site_id,'name',p.name,'kind',p.kind,'active',p.active,'sort_order',p.sort_order,'target_treatment',p.target_treatment,'target_age',p.target_age,'target_gender',p.target_gender) order by p.sort_order,p.created_at),'[]'::jsonb) into v_playlists from public.playlists p where p.active and (p.site_id is null or p.site_id=v_site);
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',v.id,
    'site_id',v.site_id,
    'title',v.title,
    'active',v.active,
    'duration_sec',v.duration_sec,
    'thumbnail_data_url',v.thumbnail_data_url,
    'url',v.url,
    'source',v.source,
    'storage_path',v.storage_path,
    'file_path',v.file_path,
    'target_treatment',v.target_treatment,
    'target_age',v.target_age,
    'target_gender',v.target_gender
  ) order by v.sort_order,v.created_at),'[]'::jsonb) into v_videos
  from public.videos v
  where v.active and (v.site_id is null or v.site_id=v_site) and (v.source<>'local' or v.available);
  select coalesce(jsonb_agg(jsonb_build_object('playlist_id',pi.playlist_id,'video_id',pi.video_id,'sort_order',pi.sort_order) order by pi.playlist_id,pi.sort_order,pi.created_at),'[]'::jsonb) into v_items from public.playlist_items pi join public.playlists p on p.id=pi.playlist_id where p.site_id is null or p.site_id=v_site;
  select coalesce(jsonb_agg(jsonb_build_object('room_id',rr.room_id,'video_id',rr.video_id,'enabled',rr.enabled,'sort_order',rr.sort_order,'starts_at',rr.starts_at,'ends_at',rr.ends_at,'updated_at',rr.updated_at)),'[]'::jsonb) into v_rules from public.room_video_rules rr join public.rooms r on r.id=rr.room_id where r.site_id=v_site;
  select jsonb_build_object('active',active,'video_ids',video_ids,'notice_text',notice_text,'starts_at',starts_at,'ends_at',ends_at,'revision',revision) into v_broadcast from public.site_broadcasts where site_id=v_site;
  return jsonb_build_object('site',v_site_row,'site_settings',coalesce(v_settings,'{}'::jsonb),'floorplan_assets',coalesce(v_floorplans,'{}'::jsonb),'floorplan_versions',coalesce(v_versions,'[]'::jsonb),'spaces',coalesce(v_spaces,'[]'::jsonb),'rooms',v_rooms,'groups',v_groups,'patients',v_patients,'playlists',v_playlists,'videos',v_videos,'playlist_items',v_items,'room_video_rules',v_rules,'broadcast',coalesce(v_broadcast,'{}'::jsonb),'server_time',clock_timestamp());
end $function$;
CREATE OR REPLACE FUNCTION public.staff_reception_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_site uuid; v_rooms jsonb; v_groups jsonb; v_patients jsonb; v_broadcast jsonb;
  v_playlists jsonb; v_videos jsonb; v_items jsonb; v_rules jsonb; v_site_row jsonb;
  v_floorplans jsonb; v_spaces jsonb; v_versions jsonb;
begin
  if not public.is_member() then raise exception 'not allowed'; end if;
  v_site:=coalesce(public.pin_session_site_id(),public.default_site_id());
  if public.is_admin() and v_site is null then v_site:=public.default_site_id(); end if;
  if v_site is null then raise exception 'site not configured'; end if;

  select to_jsonb(s) into v_site_row from public.sites s where s.id=v_site;
  select coalesce(ss.floorplan_assets,'{}'::jsonb) into v_floorplans from public.site_settings ss where ss.site_id=v_site;
  v_floorplans:=coalesce(v_floorplans,'{}'::jsonb);
  select coalesce(jsonb_agg(to_jsonb(fs) order by fs.sort_order,fs.created_at),'[]'::jsonb) into v_spaces
    from public.floor_spaces fs where fs.site_id=v_site;
  select coalesce(jsonb_agg(to_jsonb(fv) order by fv.created_at desc),'[]'::jsonb) into v_versions
    from public.floorplan_versions fv where fv.site_id=v_site;

  select coalesce(jsonb_agg(jsonb_build_object(
    'id',r.id,'site_id',r.site_id,'name',r.name,'sort_order',r.sort_order,'group_id',r.group_id,'group_name',g.name,'room_mode',r.room_mode,
    'last_seen_at',r.last_seen_at,'player_status',coalesce(r.player_status,'{}'::jsonb),'session_timeout_min',r.session_timeout_min,
    'session_started_at',r.session_started_at,'session_age_group',r.session_age_group,'session_gender',r.session_gender,'session_treatment',r.session_treatment,
    'default_playlist_id',r.default_playlist_id,'manual_active',r.manual_active,'manual_video_ids',r.manual_video_ids,
    'map_x_pct',r.map_x_pct,'map_y_pct',r.map_y_pct,'display_control_mode',r.display_control_mode,'manual_check_status',r.manual_check_status,
    'manual_checked_at',r.manual_checked_at,'manual_checked_by',r.manual_checked_by,'display_note',r.display_note
  ) order by coalesce(g.sort_order,2147483647),r.sort_order,r.created_at),'[]'::jsonb) into v_rooms
  from public.rooms r left join public.signage_groups g on g.id=r.group_id
  where r.site_id=v_site;

  select coalesce(jsonb_agg(jsonb_build_object('id',g.id,'site_id',g.site_id,'name',g.name,'kind',g.kind,'floor_number',g.floor_number,
    'care_type',g.care_type,'signage_purpose',g.signage_purpose,'target_audience',g.target_audience,'waiting_area_note',g.waiting_area_note,
    'signage_reason',g.signage_reason,'content_intro',g.content_intro,'content_topics',g.content_topics,'role_label',g.role_label,'default_playlist_id',g.default_playlist_id,'sort_order',g.sort_order) order by g.sort_order,g.floor_number,g.created_at),'[]'::jsonb)
    into v_groups from public.signage_groups g where g.site_id=v_site;

  select coalesce(jsonb_agg(to_jsonb(x) order by case x.status when 'in_progress' then 0 when 'assigned' then 1 when 'waiting' then 2 else 3 end,x.waiting_started_at),'[]'::jsonb)
    into v_patients from (select * from public.patient_sessions where site_id=v_site and ((status in ('waiting','assigned','in_progress')) or (status='completed' and completed_at>=date_trunc('day',clock_timestamp())))) x;

  select coalesce(jsonb_agg(jsonb_build_object('id',p.id,'site_id',p.site_id,'name',p.name,'kind',p.kind,'active',p.active,'sort_order',p.sort_order,
    'target_treatment',p.target_treatment,'target_age',p.target_age,'target_gender',p.target_gender) order by p.sort_order,p.created_at),'[]'::jsonb)
    into v_playlists from public.playlists p where p.active and (p.site_id is null or p.site_id=v_site);
  select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'site_id',v.site_id,'title',v.title,'active',v.active,'duration_sec',v.duration_sec,
    'thumbnail_data_url',v.thumbnail_data_url,'target_treatment',v.target_treatment,'target_age',v.target_age,'target_gender',v.target_gender) order by v.sort_order,v.created_at),'[]'::jsonb)
    into v_videos from public.videos v where v.active and (v.site_id is null or v.site_id=v_site) and (v.source<>'local' or v.available);
  select coalesce(jsonb_agg(jsonb_build_object('playlist_id',pi.playlist_id,'video_id',pi.video_id,'sort_order',pi.sort_order) order by pi.playlist_id,pi.sort_order,pi.created_at),'[]'::jsonb)
    into v_items from public.playlist_items pi join public.playlists p on p.id=pi.playlist_id where p.site_id is null or p.site_id=v_site;
  select coalesce(jsonb_agg(jsonb_build_object('room_id',rr.room_id,'video_id',rr.video_id,'enabled',rr.enabled,'sort_order',rr.sort_order,'starts_at',rr.starts_at,'ends_at',rr.ends_at,'updated_at',rr.updated_at)),'[]'::jsonb)
    into v_rules from public.room_video_rules rr join public.rooms r on r.id=rr.room_id where r.site_id=v_site;
  select jsonb_build_object('active',active,'notice_text',notice_text) into v_broadcast from public.broadcast where id=1;

  return jsonb_build_object('site',coalesce(v_site_row,'{}'::jsonb),'floorplan_assets',v_floorplans,'floorplan_versions',coalesce(v_versions,'[]'::jsonb),'spaces',coalesce(v_spaces,'[]'::jsonb),
    'rooms',v_rooms,'groups',v_groups,'patients',v_patients,'playlists',v_playlists,'videos',v_videos,'playlist_items',v_items,
    'room_video_rules',v_rules,'broadcast',coalesce(v_broadcast,'{}'::jsonb),'server_time',clock_timestamp());
end $function$;
CREATE OR REPLACE FUNCTION public.signage_live_status(p_room_ids uuid[] DEFAULT NULL::uuid[], p_since timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_role text:=public.pin_session_role(); v_admin boolean; v_site uuid;
begin
  if v_role is null or v_role not in ('admin','staff') then raise exception 'not allowed' using errcode='42501'; end if;
  v_admin:=(v_role='admin');
  if not v_admin then
    v_site:=public.pin_session_site_id();
    if v_site is null then raise exception 'not allowed' using errcode='42501'; end if;
  end if;
  return (
    with s as (
      select s.room_id,s.last_seen_at,s.player_status,coalesce(s.changed_at,s.updated_at,s.last_seen_at) as changed
      from public.player_live_status s
      join public.rooms r on r.id=s.room_id
      where coalesce(r.display_control_mode,'remote')<>'manual'
        and (v_admin or r.site_id=v_site)
        and (p_room_ids is null or s.room_id=any(p_room_ids))
    )
    select jsonb_build_object(
      'server_time',clock_timestamp(),
      'seen',coalesce(jsonb_agg(jsonb_build_object('room_id',s.room_id,'last_seen_at',s.last_seen_at)),'[]'::jsonb),
      'rows',coalesce(jsonb_agg(jsonb_build_object('room_id',s.room_id,'last_seen_at',s.last_seen_at,'player_status',coalesce(s.player_status,'{}'::jsonb)-'thumbnail','changed_at',s.changed))
                      filter (where p_since is null or s.changed>p_since),'[]'::jsonb)
    )
    from s
  );
end $function$;
CREATE OR REPLACE FUNCTION public.player_get_state(p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  r public.rooms; b public.site_broadcasts; s public.app_settings; ss public.site_settings; gb public.group_broadcasts; hs public.broadcast_schedules; gs public.broadcast_schedules;
  v_mode text; v_expires timestamptz; v_playlist jsonb:='[]'::jsonb; v_emergency jsonb; v_playlist_id uuid;
  v_notice text; v_effective timestamptz; v_revision text:='0'; v_next_transition timestamptz; v_operating jsonb; v_operating_end timestamptz;
begin
  select * into r from public.rooms where player_key=p_key; if not found then return null; end if;
  select * into b from public.site_broadcasts where site_id=r.site_id; select * into s from public.app_settings where id=1; select * into ss from public.site_settings where site_id=r.site_id;
  if coalesce(r.display_control_mode,'remote')='manual' then
    return jsonb_build_object('room',jsonb_build_object('id',r.id,'site_id',r.site_id,'name',r.name,'group_id',r.group_id,'room_mode',r.room_mode,'force_mute',true,'volume',0,'paused',true,'overlay_text',null,'reload_nonce',r.reload_nonce),'mode','closed','priority','manual','manual_control',true,'playlist','[]'::jsonb,'emergency_video',null,'operating',jsonb_build_object('active',false,'reason','manual_display'),'sync_revision','manual:'||r.id::text,'next_transition_at',null,'media_server_url',coalesce(s.media_server_url,''),'server_time',clock_timestamp());
  end if;
  v_operating:=public.signage_room_operating_status(r.id,clock_timestamp());
  if coalesce((v_operating->>'active')::boolean,false)=false then
    return jsonb_build_object('room',jsonb_build_object('id',r.id,'site_id',r.site_id,'name',r.name,'group_id',r.group_id,'room_mode',r.room_mode,'force_mute',r.force_mute,'volume',r.volume,'paused',r.paused,'overlay_text',r.overlay_text,'reload_nonce',r.reload_nonce),'mode','closed','priority','closed','playlist','[]'::jsonb,'emergency_video',null,'operating',v_operating,'sync_revision','closed:'||coalesce(v_operating->>'next_start_at','none'),'next_transition_at',v_operating->>'next_start_at','media_server_url',coalesce(s.media_server_url,''),'server_time',clock_timestamp());
  end if;
  v_operating_end:=nullif(v_operating->>'current_end_at','')::timestamptz;
  if r.group_id is not null then select * into gb from public.group_broadcasts where group_id=r.group_id; end if;
  select * into hs from public.broadcast_schedules x where x.enabled and x.site_id=r.site_id and x.scope_type='hospital' and x.starts_at<=clock_timestamp() and x.ends_at>clock_timestamp() order by x.starts_at desc limit 1;
  if r.group_id is not null then select * into gs from public.broadcast_schedules x where x.enabled and x.site_id=r.site_id and x.scope_type='group' and x.group_id=r.group_id and x.starts_at<=clock_timestamp() and x.ends_at>clock_timestamp() order by x.starts_at desc limit 1; end if;
  select min(t) into v_next_transition from (
    select starts_at t from public.broadcast_schedules x where x.enabled and x.site_id=r.site_id and x.starts_at>clock_timestamp() and (x.scope_type='hospital' or (x.scope_type='group' and x.group_id=r.group_id))
    union all select ends_at t from public.broadcast_schedules x where x.enabled and x.site_id=r.site_id and x.ends_at>clock_timestamp() and (x.scope_type='hospital' or (x.scope_type='group' and x.group_id=r.group_id))
    union all select b.starts_at where b.active and b.starts_at is not null and b.starts_at>clock_timestamp()
    union all select b.ends_at where b.active and b.ends_at is not null and b.ends_at>clock_timestamp()
    union all select r.manual_starts_at where r.manual_active and r.manual_starts_at is not null and r.manual_starts_at>clock_timestamp()
    union all select r.manual_ends_at where r.manual_active and r.manual_ends_at is not null and r.manual_ends_at>clock_timestamp()
    union all select starts_at t from public.room_video_rules rr where rr.room_id=r.id and rr.starts_at>clock_timestamp()
    union all select ends_at t from public.room_video_rules rr where rr.room_id=r.id and rr.ends_at>clock_timestamp()
  ) q;
  if v_operating_end is not null and (v_next_transition is null or v_operating_end<v_next_transition) then v_next_transition:=v_operating_end; end if;
  if r.session_started_at is not null and r.session_timeout_min>0 then v_expires:=r.session_started_at+make_interval(mins=>r.session_timeout_min); end if;

  if b.active and (b.starts_at is null or b.starts_at<=clock_timestamp()) and (b.ends_at is null or b.ends_at>clock_timestamp()) and coalesce(array_length(b.video_ids,1),0)>0 then
    select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'title',v.title,'source',v.source,'file_path',v.file_path,'url',v.url,'size',v.size_bytes,'file_modified_at',v.file_modified_at) order by array_position(b.video_ids,v.id)),'[]'::jsonb) into v_playlist from public.videos v where v.id=any(b.video_ids) and v.active and (v.site_id is null or v.site_id=r.site_id) and (v.source<>'local' or v.available);
    if jsonb_array_length(v_playlist)>0 then v_mode:='broadcast';v_notice:=b.notice_text;v_effective:=b.effective_at;v_revision:='b:'||b.revision; end if;
  end if;
  if v_mode is null and hs.id is not null then
    select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'title',v.title,'source',v.source,'file_path',v.file_path,'url',v.url,'size',v.size_bytes,'file_modified_at',v.file_modified_at) order by array_position(hs.video_ids,v.id)),'[]'::jsonb) into v_playlist from public.videos v where v.id=any(hs.video_ids) and v.active and (v.site_id is null or v.site_id=r.site_id) and (v.source<>'local' or v.available);
    if jsonb_array_length(v_playlist)>0 then v_mode:='broadcast_schedule';v_notice:=hs.notice_text;v_effective:=hs.starts_at;v_revision:='hs:'||hs.id::text||':'||extract(epoch from hs.starts_at)::bigint; end if;
  end if;
  if v_mode is null and r.manual_active and (r.manual_starts_at is null or r.manual_starts_at<=clock_timestamp()) and (r.manual_ends_at is null or r.manual_ends_at>clock_timestamp()) and coalesce(array_length(r.manual_video_ids,1),0)>0 then
    select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'title',v.title,'source',v.source,'file_path',v.file_path,'url',v.url,'size',v.size_bytes,'file_modified_at',v.file_modified_at) order by array_position(r.manual_video_ids,v.id)),'[]'::jsonb) into v_playlist from public.videos v where v.id=any(r.manual_video_ids) and v.active and (v.site_id is null or v.site_id=r.site_id) and (v.source<>'local' or v.available);
    if jsonb_array_length(v_playlist)>0 then v_mode:='manual';v_revision:='m:'||coalesce(extract(epoch from r.manual_updated_at)::bigint,0); end if;
  end if;
  if v_mode is null and gb.group_id is not null and gb.active and coalesce(array_length(gb.video_ids,1),0)>0 then
    select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'title',v.title,'source',v.source,'file_path',v.file_path,'url',v.url,'size',v.size_bytes,'file_modified_at',v.file_modified_at) order by array_position(gb.video_ids,v.id)),'[]'::jsonb) into v_playlist from public.videos v where v.id=any(gb.video_ids) and v.active and (v.site_id is null or v.site_id=r.site_id) and (v.source<>'local' or v.available);
    if jsonb_array_length(v_playlist)>0 then v_mode:='group';v_notice:=gb.notice_text;v_effective:=gb.effective_at;v_revision:='g:'||gb.revision; end if;
  end if;
  if v_mode is null and gs.id is not null then
    select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'title',v.title,'source',v.source,'file_path',v.file_path,'url',v.url,'size',v.size_bytes,'file_modified_at',v.file_modified_at) order by array_position(gs.video_ids,v.id)),'[]'::jsonb) into v_playlist from public.videos v where v.id=any(gs.video_ids) and v.active and (v.site_id is null or v.site_id=r.site_id) and (v.source<>'local' or v.available);
    if jsonb_array_length(v_playlist)>0 then v_mode:='group_schedule';v_notice:=gs.notice_text;v_effective:=gs.starts_at;v_revision:='gs:'||gs.id::text||':'||extract(epoch from gs.starts_at)::bigint; end if;
  end if;

  if v_mode is null and r.room_mode in ('treatment','consultation') and r.session_treatment is not null and r.session_started_at is not null and (v_expires is null or v_expires>clock_timestamp()) then
    select p.id into v_playlist_id from public.playlists p where p.active and p.kind='patient' and (p.site_id is null or p.site_id=r.site_id)
      and (coalesce(array_length(p.target_treatment,1),0)=0 or r.session_treatment=any(p.target_treatment))
      and (coalesce(array_length(p.target_age,1),0)=0 or (r.session_age_group is not null and r.session_age_group=any(p.target_age)))
      and (coalesce(array_length(p.target_gender,1),0)=0 or (r.session_gender is not null and r.session_gender=any(p.target_gender)))
    order by (case when p.site_id=r.site_id then 1000 else 0 end + case when coalesce(array_length(p.target_treatment,1),0)>0 then 100 else 0 end + case when coalesce(array_length(p.target_age,1),0)>0 then 10 else 0 end + case when coalesce(array_length(p.target_gender,1),0)>0 then 5 else 0 end) desc,p.sort_order,p.created_at limit 1;
    if v_playlist_id is not null then
      select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'title',v.title,'source',v.source,'file_path',v.file_path,'url',v.url,'size',v.size_bytes,'file_modified_at',v.file_modified_at) order by pi.sort_order,pi.created_at),'[]'::jsonb) into v_playlist from public.playlist_items pi join public.videos v on v.id=pi.video_id where pi.playlist_id=v_playlist_id and v.active and (v.site_id is null or v.site_id=r.site_id) and (v.source<>'local' or v.available);
      if jsonb_array_length(v_playlist)>0 then v_mode:='patient';v_revision:='pp:'||v_playlist_id::text||':'||coalesce(extract(epoch from r.session_started_at)::bigint,0); end if;
    end if;
    if v_mode is null then
      with candidates as (select v.*,(case when coalesce(array_length(v.target_treatment,1),0)>0 then 100 else 0 end + case when coalesce(array_length(v.target_age,1),0)>0 then 10 else 0 end + case when coalesce(array_length(v.target_gender,1),0)>0 then 5 else 0 end) score from public.videos v where v.active and (v.site_id is null or v.site_id=r.site_id) and (v.source<>'local' or v.available) and (coalesce(array_length(v.target_treatment,1),0)=0 or r.session_treatment=any(v.target_treatment)) and (coalesce(array_length(v.target_age,1),0)=0 or (r.session_age_group is not null and r.session_age_group=any(v.target_age))) and (coalesce(array_length(v.target_gender,1),0)=0 or (r.session_gender is not null and r.session_gender=any(v.target_gender)))), best as (select max(score) score from candidates)
      select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'title',c.title,'source',c.source,'file_path',c.file_path,'url',c.url,'size',c.size_bytes,'file_modified_at',c.file_modified_at) order by c.sort_order,c.created_at),'[]'::jsonb) into v_playlist from candidates c cross join best where c.score=best.score;
      if jsonb_array_length(v_playlist)>0 then v_mode:='patient';v_revision:='legacy-p:'||coalesce(extract(epoch from r.session_started_at)::bigint,0); end if;
    end if;
  end if;

  if v_mode is null then
    v_mode:='default';v_expires:=null;
    v_playlist_id:=r.default_playlist_id;
    if v_playlist_id is null and r.group_id is not null then select default_playlist_id into v_playlist_id from public.signage_groups where id=r.group_id; end if;
    if v_playlist_id is null then select id into v_playlist_id from public.playlists where active and kind='default' and (site_id is null or site_id=r.site_id) order by coalesce(site_id=r.site_id,false) desc,sort_order,created_at limit 1; end if;
    if v_playlist_id is not null then select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'title',v.title,'source',v.source,'file_path',v.file_path,'url',v.url,'size',v.size_bytes,'file_modified_at',v.file_modified_at) order by pi.sort_order,pi.created_at),'[]'::jsonb) into v_playlist from public.playlist_items pi join public.videos v on v.id=pi.video_id where pi.playlist_id=v_playlist_id and v.active and (v.site_id is null or v.site_id=r.site_id) and (v.source<>'local' or v.available); end if;
    if jsonb_array_length(v_playlist)=0 then select coalesce(jsonb_agg(jsonb_build_object('id',v.id,'title',v.title,'source',v.source,'file_path',v.file_path,'url',v.url,'size',v.size_bytes,'file_modified_at',v.file_modified_at) order by v.sort_order,v.created_at),'[]'::jsonb) into v_playlist from public.videos v where v.active and (v.site_id is null or v.site_id=r.site_id) and (v.source<>'local' or v.available) and v.tags&&r.default_tags; end if;
    v_revision:='d:'||coalesce(v_playlist_id::text,'legacy');
  end if;
  if v_mode in ('manual','patient','default') then
    v_playlist:=public.apply_room_video_rules(r.id,v_playlist);
    v_revision:=v_revision||':rr:'||coalesce((select extract(epoch from max(updated_at))::bigint::text from public.room_video_rules where room_id=r.id),'0');
  end if;
  if nullif(ss.operating_config->>'emergency_video_id','') is not null then select jsonb_build_object('id',v.id,'title',v.title,'source',v.source,'file_path',v.file_path,'url',v.url,'size',v.size_bytes,'file_modified_at',v.file_modified_at) into v_emergency from public.videos v where v.id=(ss.operating_config->>'emergency_video_id')::uuid and v.active and (v.site_id is null or v.site_id=r.site_id) and (v.source<>'local' or v.available); end if;
  return jsonb_build_object('room',jsonb_build_object('id',r.id,'site_id',r.site_id,'name',r.name,'group_id',r.group_id,'room_mode',r.room_mode,'force_mute',r.force_mute,'volume',r.volume,'paused',r.paused,'overlay_text',r.overlay_text,'reload_nonce',r.reload_nonce),'mode',v_mode,'priority',v_mode,'operating',v_operating,'session_expires_at',case when v_mode='patient' then v_expires end,'notice_text',v_notice,'playlist',v_playlist,'emergency_video',v_emergency,'sync_effective_at',v_effective,'sync_revision',v_revision,'next_transition_at',v_next_transition,'media_server_url',coalesce(s.media_server_url,''),'server_time',clock_timestamp());
end $function$;
CREATE OR REPLACE FUNCTION public.superadmin_save_global_playlist(p_id uuid, p_name text, p_video_ids uuid[])
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_video uuid; v_pos int:=0;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION '슈퍼어드민만 공용 재생목록을 수정할 수 있습니다.' USING ERRCODE='42501';
  END IF;
  IF p_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.playlists WHERE id=p_id AND site_id IS NULL) THEN
    RAISE EXCEPTION '공용 재생목록을 찾을 수 없습니다.' USING ERRCODE='P0001';
  END IF;
  IF nullif(btrim(coalesce(p_name,'')),'') IS NULL THEN
    RAISE EXCEPTION '재생목록 이름을 입력하세요.' USING ERRCODE='P0001';
  END IF;
  IF coalesce(array_length(p_video_ids,1),0)=0 THEN
    RAISE EXCEPTION '영상은 1개 이상 선택하세요.' USING ERRCODE='P0001';
  END IF;
  IF EXISTS(
    SELECT 1 FROM unnest(p_video_ids) AS x(id)
    WHERE NOT EXISTS(SELECT 1 FROM public.videos v WHERE v.id=x.id AND v.site_id IS NULL AND v.active)
  ) THEN
    RAISE EXCEPTION '공용 재생목록에는 공용 영상만 넣을 수 있습니다.' USING ERRCODE='P0001';
  END IF;
  IF (SELECT count(*) FROM unnest(p_video_ids)) <> (SELECT count(DISTINCT x.id) FROM unnest(p_video_ids) AS x(id)) THEN
    RAISE EXCEPTION '중복된 영상이 포함되어 있습니다.' USING ERRCODE='P0001';
  END IF;
  PERFORM 1 FROM public.playlists WHERE id=p_id AND site_id IS NULL FOR UPDATE;
  UPDATE public.playlists SET name=btrim(p_name),updated_at=clock_timestamp() WHERE id=p_id AND site_id IS NULL;
  DELETE FROM public.playlist_items WHERE playlist_id=p_id;
  FOREACH v_video IN ARRAY p_video_ids LOOP
    v_pos:=v_pos+10;
    INSERT INTO public.playlist_items(playlist_id,video_id,sort_order)
    VALUES (p_id,v_video,v_pos);
  END LOOP;
  RETURN p_id;
END $function$;
CREATE OR REPLACE FUNCTION public.superadmin_delete_global_video(p_video uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION '슈퍼어드민 권한이 필요합니다.' USING ERRCODE='42501'; END IF;
  PERFORM 1 FROM public.videos WHERE id=p_video AND site_id IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION '공용 영상을 찾을 수 없습니다.' USING ERRCODE='P0001'; END IF;
  -- Protect all hospitals and all scheduled/persistent references.
  IF EXISTS(SELECT 1 FROM public.playlist_items WHERE video_id=p_video)
    OR EXISTS(SELECT 1 FROM public.room_video_rules WHERE video_id=p_video)
    OR EXISTS(SELECT 1 FROM public.rooms WHERE p_video=ANY(manual_video_ids))
    OR EXISTS(SELECT 1 FROM public.site_broadcasts WHERE p_video=ANY(video_ids))
    OR EXISTS(SELECT 1 FROM public.group_broadcasts WHERE p_video=ANY(video_ids))
    OR EXISTS(SELECT 1 FROM public.broadcast_schedules WHERE p_video=ANY(video_ids))
    OR EXISTS(SELECT 1 FROM public.site_settings WHERE operating_config->>'emergency_video_id'=p_video::text)
    OR EXISTS(SELECT 1 FROM public.app_settings WHERE emergency_video_id=p_video)
    OR EXISTS(SELECT 1 FROM public.broadcast WHERE p_video=ANY(video_ids)) THEN
    RAISE EXCEPTION '다른 병원 또는 송출 설정에서 사용 중입니다. 연결을 모두 해제한 뒤 삭제하세요.' USING ERRCODE='P0001';
  END IF;
  DELETE FROM public.videos WHERE id=p_video AND site_id IS NULL;
END $function$;

-- ---------- 3. 함수: 운영 쪽 유지 (저장소에 기록) ----------
drop function if exists public.admin_close_today();
CREATE OR REPLACE FUNCTION public.admin_close_today()
 RETURNS date
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare d date:=(clock_timestamp() at time zone 'Asia/Seoul')::date;
begin
  if not coalesce(public.is_admin(),false) then raise exception 'not allowed'; end if;
  update public.app_settings set early_closed_date=d,updated_at=clock_timestamp() where id=1;
  perform public.signal_signage_rooms(array(select id from public.rooms));
  return d;
end $function$;
CREATE OR REPLACE FUNCTION public.admin_undo_control(p_history bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare h public.control_history; item jsonb; s jsonb;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  select * into h from public.control_history where id=p_history;
  if not found or h.before_state is null then raise exception '복귀할 상태가 없습니다'; end if;
  if h.scope_type='hospital' then
    update public.broadcast set active=coalesce((h.before_state->>'active')::boolean,false),video_ids=coalesce(ARRAY(SELECT (jsonb_array_elements_text(coalesce(h.before_state->'video_ids','[]'::jsonb)))::uuid),'{}'::uuid[]),notice_text=h.before_state->>'notice_text',effective_at=null,revision=revision+1,updated_at=clock_timestamp() where id=1;
  elsif h.scope_type='group' then
    insert into public.group_broadcasts(group_id) values(h.scope_id) on conflict(group_id) do nothing;
    update public.group_broadcasts set active=coalesce((h.before_state->>'active')::boolean,false),video_ids=coalesce(ARRAY(SELECT (jsonb_array_elements_text(coalesce(h.before_state->'video_ids','[]'::jsonb)))::uuid),'{}'::uuid[]),notice_text=h.before_state->>'notice_text',effective_at=null,revision=revision+1,updated_at=clock_timestamp() where group_id=h.scope_id;
  elsif h.scope_type='rooms' and jsonb_typeof(h.before_state)='array' then
    for item in select * from jsonb_array_elements(h.before_state) loop
      update public.rooms set manual_active=coalesce((item->>'manual_active')::boolean,false),manual_video_ids=coalesce(ARRAY(SELECT (jsonb_array_elements_text(coalesce(item->'manual_video_ids','[]'::jsonb)))::uuid),'{}'::uuid[]),manual_updated_at=clock_timestamp() where id=(item->>'id')::uuid;
    end loop;
  elsif h.scope_type='rooms' and jsonb_typeof(h.before_state)='object' then
    s:=h.before_state;
    if h.scope_id is null or not exists(select 1 from public.rooms where id=h.scope_id) then raise exception '공간을 찾을 수 없습니다'; end if;
    update public.rooms set
      manual_active=coalesce((s->>'manual_active')::boolean,false),
      manual_video_ids=coalesce(ARRAY(SELECT (jsonb_array_elements_text(coalesce(s->'manual_video_ids','[]'::jsonb)))::uuid),'{}'::uuid[]),
      manual_updated_at=clock_timestamp(),
      default_playlist_id=case when s ? 'default_playlist_id' and (nullif(s->>'default_playlist_id','') is null or exists(select 1 from public.playlists p where p.id=(s->>'default_playlist_id')::uuid)) then nullif(s->>'default_playlist_id','')::uuid else default_playlist_id end
    where id=h.scope_id;
    -- 플레이리스트 변경 때 해제된 빠른 맞춤(환자 미등록) 상태만 복원한다. 등록 환자가 배정된 공간은 건드리지 않는다.
    if s ? 'session_treatment' and not exists(select 1 from public.patient_sessions where room_id=h.scope_id and status in ('assigned','in_progress')) then
      update public.rooms set
        session_treatment=s->>'session_treatment',
        session_age_group=s->>'session_age_group',
        session_gender=s->>'session_gender',
        session_started_at=case when s->>'session_treatment' is null then null else coalesce(nullif(s->>'session_started_at','')::timestamptz,clock_timestamp()) end,
        session_tags=array_remove(array[s->>'session_age_group',s->>'session_gender',s->>'session_treatment']::text[],null)
      where id=h.scope_id;
    end if;
  else raise exception '이 이력은 직접 복귀할 수 없습니다'; end if;
  insert into public.control_history(scope_type,scope_id,action,label,before_state,after_state) values(h.scope_type,h.scope_id,'undo',coalesce(h.label,'직전 상태'),h.after_state,h.before_state);
end $function$;
CREATE OR REPLACE FUNCTION public.player_get_state_lite(p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE s jsonb; v_pl jsonb;
BEGIN
  s := public.player_get_state(p_key);
  IF s IS NULL THEN RETURN NULL; END IF;
  SELECT coalesce(jsonb_agg(
    (x.e - 'thumbnail') ||
    CASE WHEN jsonb_typeof(v.variants)='object' THEN jsonb_build_object('variants',v.variants) ELSE '{}'::jsonb END ||
    CASE WHEN v.sha256 IS NOT NULL THEN jsonb_build_object('sha256',v.sha256) ELSE '{}'::jsonb END ||
    CASE WHEN v.file_modified_at IS NOT NULL THEN jsonb_build_object('file_modified_at',v.file_modified_at) ELSE '{}'::jsonb END
    ORDER BY x.o), '[]'::jsonb)
  INTO v_pl
  FROM jsonb_array_elements(CASE WHEN jsonb_typeof(s->'playlist')='array' THEN s->'playlist' ELSE '[]'::jsonb END)
       WITH ORDINALITY AS x(e,o)
  LEFT JOIN public.videos v ON v.id=CASE
    WHEN (x.e->>'id') ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    THEN (x.e->>'id')::uuid ELSE NULL END;
  RETURN s || jsonb_build_object(
    'playlist',v_pl,
    -- Include order, mode, URL, size, file modified time, digest.
    'playlist_hash',md5(jsonb_build_object(
      'mode',coalesce(s->>'mode',''),
      'playlist',(SELECT coalesce(jsonb_agg(jsonb_build_array(
        e->>'id',e->>'url',e->>'size',e->>'file_modified_at',e->>'sha256') ORDER BY o),'[]'::jsonb)
        FROM jsonb_array_elements(v_pl) WITH ORDINALITY AS y(e,o))
    )::text),
    'emergency_video',CASE WHEN jsonb_typeof(s->'emergency_video')='object'
      THEN (s->'emergency_video') - 'thumbnail'::text ELSE coalesce(s->'emergency_video','null'::jsonb) END
  );
END $function$;
CREATE OR REPLACE FUNCTION public.staff_room_list()
 RETURNS TABLE(id uuid, name text, sort_order integer, default_tags text[], session_tags text[], session_started_at timestamp with time zone, session_timeout_min integer, session_expires_at timestamp with time zone, session_age_group text, session_gender text, session_treatment text, last_seen_at timestamp with time zone, group_id uuid, group_name text, group_kind text, room_mode text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_role text := public.pin_session_role();
        v_site uuid := public.pin_session_site_id();
BEGIN
  IF v_role NOT IN ('admin','staff') OR v_role IS NULL THEN
    RAISE EXCEPTION 'not allowed' USING errcode='42501';
  END IF;
  -- Fail closed if a staff session has no site assignment.
  IF v_role='staff' AND v_site IS NULL THEN
    RAISE EXCEPTION 'site scope required' USING errcode='42501';
  END IF;
  RETURN QUERY
    SELECT r.id,r.name,r.sort_order,r.default_tags,r.session_tags,
      r.session_started_at,r.session_timeout_min,
      CASE WHEN r.session_started_at IS NOT NULL AND r.session_timeout_min>0
        THEN r.session_started_at+make_interval(mins=>r.session_timeout_min) ELSE NULL END,
      r.session_age_group,r.session_gender,r.session_treatment,r.last_seen_at,
      r.group_id,g.name,g.kind,r.room_mode
    FROM public.rooms r
    LEFT JOIN public.signage_groups g ON g.id=r.group_id
    WHERE v_role='admin' OR r.site_id=v_site
    ORDER BY coalesce(g.sort_order,2147483647),g.name NULLS LAST,r.sort_order,r.created_at;
END $function$;
CREATE OR REPLACE FUNCTION public.admin_reopen_today()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not coalesce(public.is_admin(),false) then raise exception 'not allowed'; end if;
  update public.app_settings set early_closed_date=null,updated_at=clock_timestamp() where id=1;
  perform public.signal_signage_rooms(array(select id from public.rooms));
end $function$;
CREATE OR REPLACE FUNCTION public.admin_prune_signage_logs(p_event_days integer DEFAULT 30, p_daily_days integer DEFAULT 400)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare ev int:=0; dy int:=0;
begin
  if not coalesce(public.is_admin(),false) then raise exception 'not allowed'; end if;
  delete from public.player_events where occurred_at < clock_timestamp()-make_interval(days=>greatest(7,least(coalesce(p_event_days,30),365))); get diagnostics ev=row_count;
  delete from public.room_playback_daily where day < ((clock_timestamp() at time zone 'Asia/Seoul')::date-greatest(90,least(coalesce(p_daily_days,400),1500))); get diagnostics dy=row_count;
  return jsonb_build_object('player_events_deleted',ev,'daily_deleted',dy);
end $function$;

-- ---------- 4. 함수: 운영 전용 (저장소에 기록) ----------
CREATE OR REPLACE FUNCTION public.room_operating_window(p_room uuid, p_day date)
 RETURNS TABLE(is_open boolean, start_time time without time zone, end_time time without time zone, source text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r public.rooms; s public.app_settings; dow int;
begin
  select * into r from public.rooms where id=p_room;
  select * into s from public.app_settings where id=1;
  if r.id is null then is_open:=false;start_time:=null;end_time:=null;source:='missing';return next;return; end if;
  dow:=extract(isodow from p_day)::int;
  if r.operating_override then
    source:='room';
    if dow between 1 and 5 then is_open:=r.operating_weekday_enabled;start_time:=r.operating_weekday_start;end_time:=r.operating_weekday_end;
    elsif dow=6 then is_open:=r.operating_saturday_enabled;start_time:=r.operating_saturday_start;end_time:=r.operating_saturday_end;
    else is_open:=r.operating_sunday_enabled;start_time:=r.operating_sunday_start;end_time:=r.operating_sunday_end; end if;
  else
    source:='hospital';
    if dow between 1 and 5 then is_open:=s.operating_weekday_enabled;start_time:=s.operating_weekday_start;end_time:=s.operating_weekday_end;
    elsif dow=6 then is_open:=s.operating_saturday_enabled;start_time:=s.operating_saturday_start;end_time:=s.operating_saturday_end;
    else is_open:=s.operating_sunday_enabled;start_time:=s.operating_sunday_start;end_time:=s.operating_sunday_end; end if;
  end if;
  if not coalesce(is_open,false) or start_time is null or end_time is null or end_time<=start_time then is_open:=false; end if;
  return next;
end $function$;
CREATE OR REPLACE FUNCTION public.room_operating_status(p_room uuid, p_at timestamp with time zone DEFAULT clock_timestamp())
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  s public.app_settings; d date; lt time; w record; i int; nd date; nw record;
  active boolean:=false; nxt timestamptz; reason text:='closed'; src text:='hospital';
begin
  select * into s from public.app_settings where id=1;
  d:=(p_at at time zone 'Asia/Seoul')::date; lt:=(p_at at time zone 'Asia/Seoul')::time;
  select * into w from public.room_operating_window(p_room,d); src:=coalesce(w.source,'hospital');
  if s.early_closed_date=d then
    active:=false;reason:='early_closed';
  elsif w.is_open and lt>=w.start_time and lt<w.end_time then
    active:=true;reason:='open';nxt:=((d+w.end_time)::timestamp at time zone 'Asia/Seoul');
  elsif w.is_open and lt<w.start_time then
    active:=false;reason:='before_open';nxt:=((d+w.start_time)::timestamp at time zone 'Asia/Seoul');
  else
    active:=false;reason:='after_close';
  end if;
  if not active and nxt is null then
    for i in 1..8 loop
      nd:=d+i;
      select * into nw from public.room_operating_window(p_room,nd);
      if nw.is_open then nxt:=((nd+nw.start_time)::timestamp at time zone 'Asia/Seoul'); exit; end if;
    end loop;
  end if;
  return jsonb_build_object('active',active,'reason',reason,'source',src,'date',d,'start_time',w.start_time,'end_time',w.end_time,'next_transition_at',nxt,'early_closed',s.early_closed_date=d);
end $function$;
CREATE OR REPLACE FUNCTION public.player_get_state_operating(p_key uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare s jsonb; gate jsonb; rid uuid; current_next timestamptz; gate_next timestamptz; final_next timestamptz;
begin
  s:=public.player_get_state(p_key); if s is null then return null; end if;
  rid:=nullif(s#>>'{room,id}','')::uuid;
  gate:=public.room_operating_status(rid,clock_timestamp());
  current_next:=nullif(s->>'next_transition_at','')::timestamptz;
  gate_next:=nullif(gate->>'next_transition_at','')::timestamptz;
  if current_next is null then final_next:=gate_next; elsif gate_next is null then final_next:=current_next; else final_next:=least(current_next,gate_next); end if;
  if not coalesce((gate->>'active')::boolean,false) then
    return s || jsonb_build_object('mode','closed','playlist','[]'::jsonb,'notice_text',null,'session_expires_at',null,'next_transition_at',gate_next,'operating',gate,'sync_revision',coalesce(s->>'sync_revision','0')||':closed:'||coalesce(gate->>'date',''));
  end if;
  return s || jsonb_build_object('next_transition_at',final_next,'operating',gate);
end $function$;
CREATE OR REPLACE FUNCTION public.player_live_ping(p_key uuid, p_status jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_room uuid; v_now timestamptz:=clock_timestamp(); clean jsonb;
begin
  select id into v_room from public.rooms where player_key=p_key;
  if v_room is null then return; end if;
  if p_status is null or jsonb_typeof(p_status)<>'object' or pg_column_size(p_status)>16384 then return; end if;
  clean=jsonb_build_object(
    'video_id',case when jsonb_typeof(p_status->'video_id')='string' then left(p_status->>'video_id',64) else null end,
    'title',left(coalesce(p_status->>'title',''),160),'mode',left(coalesce(p_status->>'mode',''),32),
    'playback_state',left(coalesce(p_status->>'playback_state',''),32),
    'current_time',case when jsonb_typeof(p_status->'current_time')='number' then greatest(0,least((p_status->>'current_time')::numeric,86400)) else 0 end,
    'duration',case when jsonb_typeof(p_status->'duration')='number' then greatest(0,least((p_status->>'duration')::numeric,86400)) else 0 end,
    'muted',case when jsonb_typeof(p_status->'muted')='boolean' then (p_status->>'muted')::boolean else false end,
    'volume',case when jsonb_typeof(p_status->'volume')='number' then greatest(0,least((p_status->>'volume')::int,100)) else 0 end,
    'online',case when jsonb_typeof(p_status->'online')='boolean' then (p_status->>'online')::boolean else false end,
    'error',left(coalesce(p_status->>'error',''),300),'source',left(coalesce(p_status->>'source',''),64),
    'recovery_stage',case when jsonb_typeof(p_status->'recovery_stage')='number' then greatest(0,least((p_status->>'recovery_stage')::int,5)) else 0 end,
    'playlist_video_ids',coalesce((select jsonb_agg(left(x.value,64) order by x.ord) from jsonb_array_elements_text(case when jsonb_typeof(p_status->'playlist_video_ids')='array' then p_status->'playlist_video_ids' else '[]'::jsonb end) with ordinality as x(value,ord) where x.ord<=20),'[]'::jsonb),
    'playlist_titles',coalesce((select jsonb_agg(left(x.value,120) order by x.ord) from jsonb_array_elements_text(case when jsonb_typeof(p_status->'playlist_titles')='array' then p_status->'playlist_titles' else '[]'::jsonb end) with ordinality as x(value,ord) where x.ord<=8),'[]'::jsonb),
    'playlist_count',case when jsonb_typeof(p_status->'playlist_count')='number' then greatest(0,least((p_status->>'playlist_count')::int,500)) else 0 end,
    'current_index',case when jsonb_typeof(p_status->'current_index')='number' then greatest(0,least((p_status->>'current_index')::int,499)) else 0 end,
    'next_title',left(coalesce(p_status->>'next_title',''),160),'app_version',left(coalesce(p_status->>'app_version',''),24),'reported_at',left(coalesce(p_status->>'reported_at',''),48)
  );
  insert into public.player_live_status(room_id,last_seen_at,player_status,updated_at)
  values(v_room,v_now,clean,v_now)
  on conflict(room_id) do update set last_seen_at=excluded.last_seen_at,player_status=excluded.player_status,updated_at=excluded.updated_at;
end $function$;
CREATE OR REPLACE FUNCTION public.prune_player_events(p_keep_days integer DEFAULT 30)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE n bigint;
BEGIN
  DELETE FROM public.player_events WHERE occurred_at < now() - make_interval(days=>greatest(coalesce(p_keep_days,30),7));
  GET DIAGNOSTICS n=ROW_COUNT;
  RETURN n;
END $function$;
CREATE OR REPLACE FUNCTION public.enqueue_media_gc()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP='DELETE' THEN
    IF OLD.source='r2' AND nullif(OLD.storage_path,'') IS NOT NULL THEN
      INSERT INTO public.media_gc_queue(site_id,storage_path,reason)
      VALUES(OLD.site_id,OLD.storage_path,'video_deleted')
      ON CONFLICT (storage_path) WHERE deleted_at IS NULL DO NOTHING;
    END IF;
    RETURN OLD;
  END IF;
  IF OLD.source='r2' AND nullif(OLD.storage_path,'') IS NOT NULL
     AND NEW.storage_path IS DISTINCT FROM OLD.storage_path THEN
    INSERT INTO public.media_gc_queue(site_id,storage_path,reason)
    VALUES(OLD.site_id,OLD.storage_path,'file_replaced')
    ON CONFLICT (storage_path) WHERE deleted_at IS NULL DO NOTHING;
  END IF;
  RETURN NEW;
END $function$;
CREATE OR REPLACE FUNCTION public.hospital_get_room_overlays(p_site uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if not public.can_manage_site(p_site) then raise exception '접근 권한이 없습니다.'; end if;
  return coalesce((select jsonb_agg(jsonb_build_object('id',r.id,'overlay_text',r.overlay_text))
    from public.rooms r where r.site_id=p_site),'[]'::jsonb);
end $function$;
CREATE OR REPLACE FUNCTION public.hospital_reload_site_players(p_site uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_count integer := 0;
BEGIN
  IF p_site IS NULL OR NOT public.can_manage_site(p_site) THEN
    RAISE EXCEPTION 'not allowed';
  END IF;
  UPDATE public.rooms r
     SET reload_nonce = CASE WHEN r.reload_nonce >= 2147483646 THEN 1 ELSE r.reload_nonce + 1 END
   WHERE r.site_id = p_site
     AND coalesce(r.display_control_mode,'remote') IN ('remote','hybrid');
  GET DIAGNOSTICS v_count = ROW_COUNT;
  PERFORM public.signal_site_rooms_internal(p_site);
  RETURN v_count;
END;
$function$;
CREATE OR REPLACE FUNCTION public.hospital_remove_room_manual_video(p_site uuid, p_room uuid, p_video uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_room public.rooms;
  v_remaining uuid[];
BEGIN
  IF NOT public.is_member() OR NOT public.staff_can_remote_control_room(p_room) THEN
    RAISE EXCEPTION 'not allowed' USING ERRCODE='42501';
  END IF;
  -- Explicit tenant scoping, including superadmin sessions in a selected hospital.
  SELECT * INTO v_room FROM public.rooms
  WHERE id=p_room AND site_id=p_site FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'TV not found in selected hospital' USING ERRCODE='22023'; END IF;
  IF NOT COALESCE(v_room.manual_active,false) OR NOT p_video=ANY(COALESCE(v_room.manual_video_ids,'{}'::uuid[])) THEN
    RAISE EXCEPTION 'video not in current manual TV list' USING ERRCODE='22023';
  END IF;
  v_remaining:=array_remove(v_room.manual_video_ids,p_video);
  UPDATE public.rooms SET
    manual_video_ids=COALESCE(v_remaining,'{}'::uuid[]),
    manual_active=COALESCE(array_length(v_remaining,1),0)>0,
    manual_starts_at=CASE WHEN COALESCE(array_length(v_remaining,1),0)>0 THEN manual_starts_at ELSE NULL END,
    manual_ends_at=CASE WHEN COALESCE(array_length(v_remaining,1),0)>0 THEN manual_ends_at ELSE NULL END,
    manual_updated_at=clock_timestamp()
  WHERE id=p_room AND site_id=p_site;
END;
$function$;
CREATE OR REPLACE FUNCTION public.hospital_reorder_floor_displays(p_site uuid, p_room_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_total integer := coalesce(array_length(p_room_ids,1),0);
  v_group uuid;
  v_group_count integer;
  v_existing_count integer;
begin
  if p_site is null or not public.can_manage_site(p_site) then
    raise exception '이 병원의 TV 순서를 변경할 권한이 없습니다.';
  end if;
  if v_total < 1 or v_total > 500 then
    raise exception 'TV 목록이 올바르지 않습니다.';
  end if;
  if (select count(distinct x.id) from unnest(p_room_ids) as x(id)) <> v_total then
    raise exception '중복된 TV가 포함되어 있습니다.';
  end if;
  -- Serialize concurrent reorder operations within one site; prevent stale partial lists.
  perform 1 from public.sites s where s.id=p_site for update;
  perform 1 from public.rooms r where r.site_id=p_site and r.id=any(p_room_ids) order by r.id for update;
  select (array_agg(distinct r.group_id))[1],count(distinct r.group_id),count(*)
    into v_group,v_group_count,v_existing_count
    from public.rooms r
    join public.signage_groups g on g.id=r.group_id and g.site_id=p_site
   where r.site_id=p_site and r.id=any(p_room_ids) and g.kind='floor';
  if v_existing_count <> v_total or v_group_count <> 1 or v_group is null then
    raise exception 'TV 목록에 다른 병원 또는 다른 층이 포함되어 있습니다.';
  end if;
  if (select count(*) from public.rooms where site_id=p_site and group_id=v_group) <> v_total then
    raise exception 'TV 목록이 변경되었습니다. 새로고침 후 다시 시도하세요.';
  end if;
  update public.rooms r set sort_order=(o.ord::integer*10)
  from unnest(p_room_ids) with ordinality as o(id,ord)
  where r.id=o.id and r.site_id=p_site and r.group_id=v_group;
end;
$function$;
CREATE OR REPLACE FUNCTION public.hospital_set_room_overlay_text(p_site uuid, p_room uuid, p_text text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_text text := nullif(btrim(coalesce(p_text,'')), '');
begin
  if not public.can_manage_site(p_site) then
    raise exception '이 병원의 TV를 수정할 권한이 없습니다.';
  end if;
  if length(coalesce(v_text,'')) > 160 then
    raise exception '화면 문구는 160자 이내여야 합니다.';
  end if;
  update public.rooms set overlay_text=v_text
    where id=p_room and site_id=p_site;
  if not found then raise exception 'TV를 찾을 수 없습니다.'; end if;
  -- Existing room-change trigger broadcasts any player-visible field changes.
end $function$;

