update public.player_live_status set last_seen_at=coalesce(last_seen_at,now()), player_status=coalesce(player_status,'{}'::jsonb)
  where last_seen_at is null or player_status is null;
alter table public.player_live_status alter column last_seen_at set default now(), alter column last_seen_at set not null;
alter table public.player_live_status alter column player_status set default '{}'::jsonb, alter column player_status set not null;
