revoke all on function public.enqueue_media_gc() from public, anon, authenticated;
revoke all on function public.prune_player_events(integer) from public, anon, authenticated;
-- 층 번호 중복 방지: 층 번호가 있는 층에만 적용
do $$
begin
  if exists(select 1 from pg_indexes where schemaname='public' and indexname='signage_groups_site_floor_uidx'
            and indexdef not like '%floor_number IS NOT NULL%') then
    drop index public.signage_groups_site_floor_uidx;
  end if;
end $$;
create unique index if not exists signage_groups_site_floor_uidx on public.signage_groups(site_id,floor_number) where kind='floor' and floor_number is not null;

insert into public.schema_version(version,applied_at) values('2.35.85-db-sync',clock_timestamp())
on conflict(version) do update set applied_at=excluded.applied_at;
notify pgrst,'reload schema';
commit;


-- ===== merged from v2.35.86-pairing-hardening.sql =====
-- Clinic Signage v2.35.86 — TV 연결 코드 보안·안정성, 기기 교체(인증 키 재발급), 내부 함수 권한 정리, DB 버전 확인
-- Safe to rerun. 기존 병원·TV·재생목록·영상 데이터는 변경하거나 삭제하지 않는다.
-- (진행 중이던 연결 코드 행에만 상태 컬럼이 추가된다. TV 인증 키는 관리자가 '기기 교체'를 실행할 때만 바뀐다.)
--
-- 연결 코드 상태
--   issued    : 설치형 플레이어가 코드 발급 (10분 유효)
--   approved  : 병원 관리자가 디스플레이에 연결 승인 (승인 시점부터 10분 안에 기기가 받아가야 함)
--   delivered : 기기가 인증 정보를 받아감 (같은 기기는 만료 전까지 몇 번이든 다시 받을 수 있음 → 네트워크 장애 재시도)
--   confirmed : 기기가 인증 정보를 저장했다고 확인 → 이후 이 코드로는 인증 정보를 받을 수 없음
--   (만료)    : expires_at 경과. 상태와 관계없이 사용 불가, 정리 대상
-- 인증 정보는 코드를 발급한 기기(기기ID + 코드 둘 다 일치)에게만 전달된다. 다른 기기는 받을 수 없다.

begin;

-- ---------- 1. 연결 코드 상태 컬럼 ----------
alter table public.player_pairing_codes add column if not exists status text not null default 'issued';
alter table public.player_pairing_codes add column if not exists approved_at timestamptz;
alter table public.player_pairing_codes add column if not exists delivered_at timestamptz;
alter table public.player_pairing_codes add column if not exists delivery_count integer not null default 0;
alter table public.player_pairing_codes add column if not exists confirmed_at timestamptz;
alter table public.player_pairing_codes add column if not exists replaced_key boolean not null default false;
update public.player_pairing_codes set status='approved', approved_at=coalesce(approved_at,paired_at) where room_id is not null and status='issued';
do $$
begin
  if not exists(select 1 from pg_constraint where conname='player_pairing_codes_status_check') then
    alter table public.player_pairing_codes add constraint player_pairing_codes_status_check
      check (status in ('issued','approved','delivered','confirmed'));
  end if;
end $$;
create index if not exists player_pairing_codes_room_idx on public.player_pairing_codes(room_id) where room_id is not null;

-- ---------- 2. 원자적 횟수 제한 도우미 ----------
-- 고정 창(window) 안의 횟수를 한 문장(upsert)으로 올리고 결과를 돌려준다. 동시 요청에도 누락되지 않는다.
create or replace function public.signage_throttle_hit(p_key text,p_window interval)
returns integer language sql security definer set search_path=public as $$
  insert into public.pin_login_throttle(client_id,failed_count,locked_until,updated_at)
  values(p_key,1,null,clock_timestamp())
  on conflict(client_id) do update set
    failed_count=case when public.pin_login_throttle.updated_at<clock_timestamp()-p_window then 1 else public.pin_login_throttle.failed_count+1 end,
    updated_at=case when public.pin_login_throttle.updated_at<clock_timestamp()-p_window then clock_timestamp() else public.pin_login_throttle.updated_at end
  returning failed_count
$$;
create or replace function public.signage_throttle_count(p_key text,p_window interval)
returns integer language sql stable security definer set search_path=public as $$
  select coalesce((select failed_count from public.pin_login_throttle where client_id=p_key and updated_at>=clock_timestamp()-p_window),0)
$$;
revoke all on function public.signage_throttle_hit(text,interval), public.signage_throttle_count(text,interval) from public, anon, authenticated;

create or replace function public.signage_pairing_cleanup()
returns void language sql security definer set search_path=public as $$
  delete from public.player_pairing_codes
   where (status<>'confirmed' and expires_at<clock_timestamp())
      or (status='confirmed' and confirmed_at<clock_timestamp()-interval '1 day')
$$;
revoke all on function public.signage_pairing_cleanup() from public, anon, authenticated;

-- ---------- 3. 플레이어: 코드 발급 ----------
create or replace function public.pairing_request(p_device_id text)
returns jsonb language plpgsql security definer set search_path=public,extensions as $$
declare
  v_device text:=trim(coalesce(p_device_id,''));
  v_now timestamptz:=clock_timestamp();
  v_hits int; v_row public.player_pairing_codes; v_code text; i int;
begin
  if v_device !~ '^[A-Za-z0-9_-]{16,64}$' then return jsonb_build_object('ok',false,'error','invalid_device'); end if;
  -- 같은 IP 10분에 60회 (병원 한 곳에서 여러 대를 동시에 설치해도 충분). 원자적으로 센다.
  v_hits:=public.signage_throttle_hit('pair:'||coalesce(public.pin_request_ip(),'unknown'),interval '10 minutes');
  if v_hits>60 then return jsonb_build_object('ok',false,'error','rate_limited','retry_after_sec',600); end if;

  perform public.signage_pairing_cleanup();
  -- 같은 기기의 요청은 순서대로 처리 (동시 요청으로 코드가 두 개 생기지 않게)
  perform pg_advisory_xact_lock(hashtext('signage-pair-device:'||v_device));

  select * into v_row from public.player_pairing_codes where device_id=v_device;
  if v_row.code is not null and v_row.status<>'confirmed' and v_row.expires_at>v_now then
    return jsonb_build_object('ok',true,'code',v_row.code,'status',v_row.status,
      'ttl_sec',greatest(1,floor(extract(epoch from v_row.expires_at-v_now))::int));
  end if;
  delete from public.player_pairing_codes where device_id=v_device;

  for i in 1..30 loop
    v_code:=lpad(((('x'||encode(gen_random_bytes(4),'hex'))::bit(32)::bigint)%1000000)::text,6,'0');
    begin
      insert into public.player_pairing_codes(code,device_id,status,expires_at) values(v_code,v_device,'issued',v_now+interval '10 minutes');
      return jsonb_build_object('ok',true,'code',v_code,'status','issued','ttl_sec',600);
    exception when unique_violation then null; -- 코드 충돌 → 다시 뽑기
    end;
  end loop;
  return jsonb_build_object('ok',false,'error','busy','retry_after_sec',10);
end $$;

-- ---------- 4. 플레이어: 연결 확인 + 인증 정보 받기 ----------
-- 같은 기기는 만료 전까지 몇 번이든 다시 받을 수 있다(응답 유실 대비). 저장 확인(confirm) 후에는 받을 수 없다.
create or replace function public.pairing_poll(p_device_id text,p_code text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_row public.player_pairing_codes; v_key uuid; v_name text; v_site text; v_now timestamptz:=clock_timestamp();
begin
  if coalesce(p_device_id,'') !~ '^[A-Za-z0-9_-]{16,64}$' or coalesce(p_code,'') !~ '^[0-9]{6}$' then
    return jsonb_build_object('ok',true,'status','expired');
  end if;
  select * into v_row from public.player_pairing_codes where device_id=p_device_id and code=p_code for update;
  if v_row.code is null then return jsonb_build_object('ok',true,'status','expired'); end if;
  if v_row.status='confirmed' then return jsonb_build_object('ok',true,'status','confirmed'); end if;
  if v_row.expires_at<=v_now then
    delete from public.player_pairing_codes where code=v_row.code;
    return jsonb_build_object('ok',true,'status','expired');
  end if;
  if v_row.status='issued' then
    return jsonb_build_object('ok',true,'status','pending','ttl_sec',greatest(1,floor(extract(epoch from v_row.expires_at-v_now))::int));
  end if;
  -- approved / delivered: 현재 TV 인증 키 전달 (승인 뒤 기기 교체가 일어났으면 새 키)
  select r.player_key,r.name,s.name into v_key,v_name,v_site from public.rooms r join public.sites s on s.id=r.site_id where r.id=v_row.room_id;
  if v_key is null then
    delete from public.player_pairing_codes where code=v_row.code;
    return jsonb_build_object('ok',true,'status','expired');
  end if;
  update public.player_pairing_codes set status='delivered',delivered_at=v_now,delivery_count=delivery_count+1 where code=v_row.code;
  return jsonb_build_object('ok',true,'status','paired','player_key',v_key,'room_name',v_name,'site_name',v_site,
    'ttl_sec',greatest(1,floor(extract(epoch from v_row.expires_at-v_now))::int));
end $$;

-- ---------- 5. 플레이어: 저장 완료 확인 ----------
create or replace function public.pairing_confirm(p_device_id text,p_code text,p_player_key uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_row public.player_pairing_codes; v_key uuid; v_site uuid; v_now timestamptz:=clock_timestamp();
begin
  if coalesce(p_device_id,'') !~ '^[A-Za-z0-9_-]{16,64}$' or coalesce(p_code,'') !~ '^[0-9]{6}$' then
    return jsonb_build_object('ok',false,'error','invalid');
  end if;
  select * into v_row from public.player_pairing_codes where device_id=p_device_id and code=p_code for update;
  if v_row.code is null or v_row.status not in ('delivered','confirmed') then return jsonb_build_object('ok',false,'error','not_delivered'); end if;
  if v_row.status='confirmed' then return jsonb_build_object('ok',true,'status','confirmed'); end if; -- 재시도 허용
  if v_row.expires_at<=v_now then return jsonb_build_object('ok',false,'error','expired'); end if;
  select player_key,site_id into v_key,v_site from public.rooms where id=v_row.room_id;
  if v_key is null or v_key<>p_player_key then return jsonb_build_object('ok',false,'error','key_mismatch'); end if;
  update public.player_pairing_codes set status='confirmed',confirmed_at=v_now where code=v_row.code;
  insert into public.audit_log(site_id,actor_role,action,entity_type,entity_id,summary,after_state)
  values(v_site,null,'update','display',v_row.room_id::text,'설치형 플레이어 연결 완료(기기 저장 확인)',
         jsonb_build_object('delivery_count',v_row.delivery_count,'replaced_key',v_row.replaced_key));
  return jsonb_build_object('ok',true,'status','confirmed');
end $$;

-- ---------- 6. 관리자: 연결 승인 ----------
-- 2인자 버전은 실패 시 예외로 실패 횟수가 롤백되는 문제가 있어 제거한다. (예전 화면은 'DB 업데이트 필요'로 안내됨)
drop function if exists public.hospital_pair_display(uuid,text);
create or replace function public.hospital_pair_display(p_room uuid,p_code text,p_replace boolean)
returns jsonb language plpgsql security definer set search_path=public as $$
declare
  v_site uuid; v_name text; v_code text:=regexp_replace(coalesce(p_code,''),'[^0-9]','','g');
  v_fail_key text; v_fails int; v_row public.player_pairing_codes; v_now timestamptz:=clock_timestamp();
begin
  select r.site_id,r.name into v_site,v_name from public.rooms r where r.id=p_room;
  if v_site is null then return jsonb_build_object('ok',false,'error','room_not_found','message','디스플레이를 찾을 수 없습니다.'); end if;
  if not public.can_manage_site(v_site) then raise exception 'not allowed' using errcode='42501'; end if;

  -- 병원 단위로 순서대로 처리 → 동시 오입력도 정확히 센다
  perform pg_advisory_xact_lock(hashtext('signage-pairfail:'||v_site::text));
  v_fail_key:='pairfail:'||v_site::text;
  v_fails:=public.signage_throttle_count(v_fail_key,interval '10 minutes');
  if v_fails>=10 then
    return jsonb_build_object('ok',false,'error','locked','retry_after_sec',600,
      'message','연결 코드를 여러 번 잘못 입력했습니다. 10분 후 다시 시도하세요.');
  end if;
  if v_code !~ '^[0-9]{6}$' then
    return jsonb_build_object('ok',false,'error','invalid_format','message','TV 화면에 표시된 6자리 숫자를 입력하세요.');
  end if;

  select * into v_row from public.player_pairing_codes where code=v_code for update;
  if v_row.code is null or v_row.status<>'issued' or v_row.expires_at<=v_now then
    v_fails:=public.signage_throttle_hit(v_fail_key,interval '10 minutes'); -- 예외를 던지지 않으므로 기록이 유지된다
    return jsonb_build_object('ok',false,'error','invalid_code','remaining',greatest(0,10-v_fails),
      'message',case when v_fails>=10 then '연결 코드를 여러 번 잘못 입력했습니다. 10분 후 다시 시도하세요.'
                     else '연결 코드가 없거나 만료되었습니다. TV 화면의 코드를 다시 확인하세요. (남은 시도 '||greatest(0,10-v_fails)||'회)' end);
  end if;

  if coalesce(p_replace,false) then
    update public.rooms set player_key=gen_random_uuid() where id=p_room;
    delete from public.player_pairing_codes where room_id=p_room and code<>v_code;
  end if;
  update public.player_pairing_codes
     set status='approved',room_id=p_room,approved_at=v_now,paired_at=v_now,
         expires_at=v_now+interval '10 minutes',replaced_key=coalesce(p_replace,false)
   where code=v_code;
  delete from public.pin_login_throttle where client_id=v_fail_key;
  perform public.audit_event(v_site,'update','display',p_room::text,
    case when coalesce(p_replace,false) then 'TV 연결 코드 승인 (기존 기기 해제·인증 키 교체)' else 'TV 연결 코드 승인' end,
    null,jsonb_build_object('room',v_name,'replace',coalesce(p_replace,false)));
  return jsonb_build_object('ok',true,'room_name',v_name,'replaced',coalesce(p_replace,false));
end $$;

-- ---------- 7. 관리자: 기존 기기 연결 해제 (인증 키 교체) ----------
-- 이전 키로는 상태 조회·보고·영상 목록 조회가 모두 거부된다 (모든 플레이어 함수가 rooms.player_key로 찾기 때문).
create or replace function public.hospital_reset_display_key(p_room uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_site uuid; v_name text;
begin
  select site_id,name into v_site,v_name from public.rooms where id=p_room;
  if v_site is null then return jsonb_build_object('ok',false,'error','room_not_found','message','디스플레이를 찾을 수 없습니다.'); end if;
  if not public.can_manage_site(v_site) then raise exception 'not allowed' using errcode='42501'; end if;
  update public.rooms set player_key=gen_random_uuid() where id=p_room;
  delete from public.player_pairing_codes where room_id=p_room and status<>'confirmed';
  perform public.audit_event(v_site,'update','display',p_room::text,'기존 TV 기기 연결 해제 (인증 키 교체)',null,jsonb_build_object('room',v_name));
  return jsonb_build_object('ok',true,'room_name',v_name);
end $$;

-- 관리자 화면 표시용: 이 디스플레이의 마지막 설치형 플레이어 연결
create or replace function public.hospital_display_pairing_info(p_room uuid)
returns jsonb language plpgsql stable security definer set search_path=public as $$
declare v_site uuid; v_row record;
begin
  select site_id into v_site from public.rooms where id=p_room;
  if v_site is null or not public.can_manage_site(v_site) then raise exception 'not allowed' using errcode='42501'; end if;
  select status,approved_at,confirmed_at,expires_at,replaced_key into v_row
    from public.player_pairing_codes where room_id=p_room order by approved_at desc nulls last limit 1;
  return jsonb_build_object('status',v_row.status,'approved_at',v_row.approved_at,'confirmed_at',v_row.confirmed_at,
                            'expires_at',v_row.expires_at,'replaced_key',v_row.replaced_key);
end $$;

revoke all on function public.pairing_request(text), public.pairing_poll(text,text), public.pairing_confirm(text,text,uuid),
  public.hospital_pair_display(uuid,text,boolean), public.hospital_reset_display_key(uuid), public.hospital_display_pairing_info(uuid) from public;
grant execute on function public.pairing_request(text), public.pairing_poll(text,text), public.pairing_confirm(text,text,uuid),
  public.hospital_pair_display(uuid,text,boolean), public.hospital_reset_display_key(uuid), public.hospital_display_pairing_info(uuid) to anon,authenticated;

-- ---------- 8. DB 버전 확인 (관리자 화면이 호환 여부를 판단) ----------
create or replace function public.app_db_version()
returns jsonb language sql stable security definer set search_path=public as $$
  select jsonb_build_object('version','2.35.86','features',jsonb_build_array('pairing_v2','display_key_reset'))
$$;
revoke all on function public.app_db_version() from public;
grant execute on function public.app_db_version() to anon,authenticated;

-- ---------- 9. 내부 전용 함수의 외부 호출 차단 ----------
-- 화면·API·TV가 직접 호출하지 않고, 보안 정의(security definer) 함수와 트리거 안에서만 쓰는 함수.
-- 트리거 함수는 실행 권한과 무관하게 동작하고, 보안 정의 함수 안에서의 호출은 소유자 권한으로 실행된다.
do $$
declare f record;
begin
  for f in
    select p.oid::regprocedure as sig
      from pg_proc p join pg_namespace n on n.oid=p.pronamespace
     where n.nspname='public'
       and (pg_get_function_result(p.oid)='trigger'
            or p.proname in ('apply_room_video_rules','audit_event','hospital_display_slot_key',
                             'room_operating_status','room_operating_window','signage_operating_window',
                             'signage_room_operating_status','signage_room_operating_window','site_operating_config',
                             'player_get_state_operating','signal_site_rooms_internal'))
       and not exists(select 1 from pg_depend d where d.objid=p.oid and d.deptype='e')
  loop
    execute format('revoke all on function %s from public, anon, authenticated', f.sig);
  end loop;
end $$;

insert into public.schema_version(version,applied_at) values('2.35.86',clock_timestamp())
on conflict(version) do update set applied_at=excluded.applied_at;
notify pgrst,'reload schema';
commit;


-- v2.35.87: persistent pairing ownership, credential snapshots, status reset.
-- Apply after v2.35.86. Existing playback keys are NOT rotated by migration.
begin;
-- 2.35.86이 먼저 적용되어 있어야 한다 (연결 코드 상태 컬럼·보조 함수 의존).
do $$ begin
  if not exists(select 1 from public.schema_version where version='2.35.86') then
    raise exception '먼저 supabase/v2.35.86-pairing-hardening.sql을 실행한 뒤 이 파일을 실행하세요.';
  end if;
end $$;
alter table public.player_pairing_codes add column if not exists approved_key uuid;
create table if not exists public.display_pairing_owner (
  room_id uuid primary key references public.rooms(id) on delete cascade,
  device_id text not null,
  player_key uuid not null,
  approved_at timestamptz not null default clock_timestamp()
);
alter table public.display_pairing_owner enable row level security;
revoke all on public.display_pairing_owner from public, anon, authenticated;
-- Serialize short pairing transactions (not playback/reporting). Consistent lock order.
select pg_advisory_xact_lock(hashtext('signage-pairing-v3'));
-- Preserve existing keys; old approvals without a trustworthy snapshot must not deliver a key.
do $$ begin
  if not exists(select 1 from public.schema_version where version='2.35.87') then
    insert into public.display_pairing_owner(room_id,device_id,player_key,approved_at)
      select distinct on (c.room_id) c.room_id,c.device_id,r.player_key,coalesce(c.approved_at,c.paired_at,clock_timestamp())
      from public.player_pairing_codes c join public.rooms r on r.id=c.room_id
      where c.status in ('approved','delivered','confirmed')
      order by c.room_id,c.approved_at desc nulls last,c.code
      on conflict(room_id) do nothing;
    delete from public.player_pairing_codes where status in ('approved','delivered');
    -- Confirmed rows may acknowledge retries only if the supplied key still matches.
    update public.player_pairing_codes c set approved_key=o.player_key
      from public.display_pairing_owner o where c.room_id=o.room_id and c.device_id=o.device_id and c.status='confirmed';
  end if;
end $$;
-- Reset current status while preserving playlists, patients and historical events.
-- A tombstone is needed because incremental live polling otherwise retains the old status.
create or replace function public.signage_reset_pairing_status(p_room uuid)
returns void language plpgsql security definer set search_path=public as $$
declare t timestamptz:=clock_timestamp();
begin
  update public.rooms set last_seen_at=null,player_status='{}'::jsonb where id=p_room;
  insert into public.player_live_status(room_id,last_seen_at,player_status,updated_at,changed_at,status_fp)
  values(p_room,t,'{"pairing_reset":true}'::jsonb,t,t,'pairing_reset')
  on conflict(room_id) do update set last_seen_at=excluded.last_seen_at,player_status=excluded.player_status,
    updated_at=excluded.updated_at,changed_at=excluded.changed_at,status_fp=excluded.status_fp;
end $$;
revoke all on function public.signage_reset_pairing_status(uuid) from public,anon,authenticated;
-- Preserve deployed report implementations; serialize key lookup with key rotation.
-- Abort transaction if a deployed signature/body is unexpected rather than silently weakening it.
do $$
declare f regprocedure; src text; patched text;
begin
  foreach f in array array['public.player_report(uuid,jsonb)'::regprocedure,'public.player_live_ping(uuid,jsonb)'::regprocedure] loop
    src:=pg_get_functiondef(f);
    patched:=regexp_replace(src,'(where player_key[[:space:]]*=[[:space:]]*p_key)[[:space:]]*;', '\1 for share;', 'i');
    if patched=src and src !~* 'where player_key[[:space:]]*=[[:space:]]*p_key[[:space:]]+for (share|update)' then
      raise exception 'Unexpected report function: %', f;
    end if;
    if patched<>src then execute patched; end if;
  end loop;
end $$;
create or replace function public.pairing_request(p_device_id text)
returns jsonb language plpgsql security definer set search_path=public,extensions as $$
declare
  v_device text:=trim(coalesce(p_device_id,''));
  v_now timestamptz:=clock_timestamp();
  v_hits int; v_row public.player_pairing_codes; v_code text; i int;
begin
  perform pg_advisory_xact_lock(hashtext('signage-pairing-v3'));
  v_now:=clock_timestamp();
  if v_device !~ '^[A-Za-z0-9_-]{16,64}$' then return jsonb_build_object('ok',false,'error','invalid_device'); end if;
  -- 같은 IP 10분에 60회 (병원 한 곳에서 여러 대를 동시에 설치해도 충분). 원자적으로 센다.
  v_hits:=public.signage_throttle_hit('pair:'||coalesce(public.pin_request_ip(),'unknown'),interval '10 minutes');
  if v_hits>60 then return jsonb_build_object('ok',false,'error','rate_limited','retry_after_sec',600); end if;

  perform public.signage_pairing_cleanup();
  -- 같은 기기의 요청은 순서대로 처리 (동시 요청으로 코드가 두 개 생기지 않게)
  perform pg_advisory_xact_lock(hashtext('signage-pair-device:'||v_device));

  select * into v_row from public.player_pairing_codes where device_id=v_device;
  if v_row.code is not null and v_row.status<>'confirmed' and v_row.expires_at>v_now then
    return jsonb_build_object('ok',true,'code',v_row.code,'status',v_row.status,
      'ttl_sec',greatest(1,floor(extract(epoch from v_row.expires_at-v_now))::int));
  end if;
  delete from public.player_pairing_codes where device_id=v_device;

  for i in 1..30 loop
    v_code:=lpad(((('x'||encode(gen_random_bytes(4),'hex'))::bit(32)::bigint)%1000000)::text,6,'0');
    begin
      insert into public.player_pairing_codes(code,device_id,status,expires_at) values(v_code,v_device,'issued',v_now+interval '10 minutes');
      return jsonb_build_object('ok',true,'code',v_code,'status','issued','ttl_sec',600);
    exception when unique_violation then null; -- 코드 충돌 → 다시 뽑기
    end;
  end loop;
  return jsonb_build_object('ok',false,'error','busy','retry_after_sec',10);
end $$;

create or replace function public.pairing_poll(p_device_id text,p_code text)
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_row public.player_pairing_codes; v_key uuid; v_name text; v_site text; v_now timestamptz:=clock_timestamp();
begin
  perform pg_advisory_xact_lock(hashtext('signage-pairing-v3'));
  v_now:=clock_timestamp();
  if coalesce(p_device_id,'') !~ '^[A-Za-z0-9_-]{16,64}$' or coalesce(p_code,'') !~ '^[0-9]{6}$' then
    return jsonb_build_object('ok',true,'status','expired');
  end if;
  select * into v_row from public.player_pairing_codes where device_id=p_device_id and code=p_code for update;
  if v_row.code is null then return jsonb_build_object('ok',true,'status','expired'); end if;
  if v_row.status='confirmed' then return jsonb_build_object('ok',true,'status','confirmed'); end if;
  if v_row.expires_at<=v_now then
    delete from public.player_pairing_codes where code=v_row.code;
    return jsonb_build_object('ok',true,'status','expired');
  end if;
  if v_row.status='issued' then
    return jsonb_build_object('ok',true,'status','pending','ttl_sec',greatest(1,floor(extract(epoch from v_row.expires_at-v_now))::int));
  end if;
  -- Only the credential snapshot approved for this device may be delivered.
  select r.player_key,r.name,s.name into v_key,v_name,v_site from public.rooms r join public.sites s on s.id=r.site_id where r.id=v_row.room_id;
  if v_key is null or v_row.approved_key is distinct from v_key or not exists(select 1 from public.display_pairing_owner o where o.room_id=v_row.room_id and o.device_id=p_device_id and o.player_key=v_key) then
    delete from public.player_pairing_codes where code=v_row.code;
    return jsonb_build_object('ok',true,'status','expired');
  end if;
  update public.player_pairing_codes set status='delivered',delivered_at=v_now,delivery_count=delivery_count+1 where code=v_row.code;
  return jsonb_build_object('ok',true,'status','paired','player_key',v_key,'room_name',v_name,'site_name',v_site,
    'ttl_sec',greatest(1,floor(extract(epoch from v_row.expires_at-v_now))::int));
end $$;

create or replace function public.pairing_confirm(p_device_id text,p_code text,p_player_key uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_row public.player_pairing_codes; v_key uuid; v_site uuid; v_now timestamptz:=clock_timestamp();
begin
  perform pg_advisory_xact_lock(hashtext('signage-pairing-v3'));
  v_now:=clock_timestamp();
  if coalesce(p_device_id,'') !~ '^[A-Za-z0-9_-]{16,64}$' or coalesce(p_code,'') !~ '^[0-9]{6}$' then
    return jsonb_build_object('ok',false,'error','invalid');
  end if;
  select * into v_row from public.player_pairing_codes where device_id=p_device_id and code=p_code for update;
  if v_row.code is null or v_row.status not in ('delivered','confirmed') then return jsonb_build_object('ok',false,'error','not_delivered'); end if;
  select player_key,site_id into v_key,v_site from public.rooms where id=v_row.room_id;
  if v_key is null or v_key is distinct from p_player_key or v_row.approved_key is distinct from v_key or not exists(select 1 from public.display_pairing_owner o where o.room_id=v_row.room_id and o.device_id=p_device_id and o.player_key=v_key) then return jsonb_build_object('ok',false,'error','key_mismatch'); end if;
  if v_row.status='confirmed' then return jsonb_build_object('ok',true,'status','confirmed'); end if;
  if v_row.expires_at<=v_now then return jsonb_build_object('ok',false,'error','expired'); end if;
  update public.player_pairing_codes set status='confirmed',confirmed_at=v_now where code=v_row.code;
  insert into public.audit_log(site_id,actor_role,action,entity_type,entity_id,summary,after_state)
  values(v_site,null,'update','display',v_row.room_id::text,'설치형 플레이어 연결 완료(기기 저장 확인)',
         jsonb_build_object('delivery_count',v_row.delivery_count,'replaced_key',v_row.replaced_key));
  return jsonb_build_object('ok',true,'status','confirmed');
end $$;

create or replace function public.hospital_pair_display(p_room uuid,p_code text,p_replace boolean)
returns jsonb language plpgsql security definer set search_path=public as $$
declare
  v_site uuid; v_name text; v_code text:=regexp_replace(coalesce(p_code,''),'[^0-9]','','g');
  v_existing boolean; v_key uuid; v_fail_key text; v_fails int; v_row public.player_pairing_codes; v_now timestamptz:=clock_timestamp();
begin
  perform pg_advisory_xact_lock(hashtext('signage-pairing-v3'));
  v_now:=clock_timestamp();
  select r.site_id,r.name into v_site,v_name from public.rooms r where r.id=p_room for update;
  if v_site is null then return jsonb_build_object('ok',false,'error','room_not_found','message','디스플레이를 찾을 수 없습니다.'); end if;
  if not public.can_manage_site(v_site) then raise exception 'not allowed' using errcode='42501'; end if;

  -- 병원 단위로 순서대로 처리 → 동시 오입력도 정확히 센다
  perform pg_advisory_xact_lock(hashtext('signage-pairfail:'||v_site::text));
  v_fail_key:='pairfail:'||v_site::text;
  v_fails:=public.signage_throttle_count(v_fail_key,interval '10 minutes');
  if v_fails>=10 then
    return jsonb_build_object('ok',false,'error','locked','retry_after_sec',600,
      'message','연결 코드를 여러 번 잘못 입력했습니다. 10분 후 다시 시도하세요.');
  end if;
  if v_code !~ '^[0-9]{6}$' then
    return jsonb_build_object('ok',false,'error','invalid_format','message','TV 화면에 표시된 6자리 숫자를 입력하세요.');
  end if;

  select * into v_row from public.player_pairing_codes where code=v_code for update;
  if v_row.code is null or v_row.status<>'issued' or v_row.expires_at<=v_now then
    v_fails:=public.signage_throttle_hit(v_fail_key,interval '10 minutes'); -- 예외를 던지지 않으므로 기록이 유지된다
    return jsonb_build_object('ok',false,'error','invalid_code','remaining',greatest(0,10-v_fails),
      'message',case when v_fails>=10 then '연결 코드를 여러 번 잘못 입력했습니다. 10분 후 다시 시도하세요.'
                     else '연결 코드가 없거나 만료되었습니다. TV 화면의 코드를 다시 확인하세요. (남은 시도 '||greatest(0,10-v_fails)||'회)' end);
  end if;

  -- DB ownership survives code cleanup and does not depend on a first heartbeat.
  v_existing:=exists(select 1 from public.display_pairing_owner where room_id=p_room)
    or exists(select 1 from public.rooms where id=p_room and last_seen_at is not null)
    or exists(select 1 from public.player_live_status where room_id=p_room and not coalesce(player_status->>'pairing_reset'='true',false));
  if v_existing and not coalesce(p_replace,false) then
    return jsonb_build_object('ok',false,'error','replace_required','message','기존 연결이 있습니다. 기기 교체를 승인하세요.');
  end if;
  -- Rotate on EVERY new approval, including first setup, to invalidate any unreported legacy URL.
  update public.rooms set player_key=gen_random_uuid() where id=p_room returning player_key into v_key;
  delete from public.player_pairing_codes where room_id=p_room and code<>v_code;
  insert into public.display_pairing_owner(room_id,device_id,player_key,approved_at)
    values(p_room,v_row.device_id,v_key,v_now)
    on conflict(room_id) do update set device_id=excluded.device_id,player_key=excluded.player_key,approved_at=excluded.approved_at;
  perform public.signage_reset_pairing_status(p_room);
  update public.player_pairing_codes
     set status='approved',approved_key=v_key,room_id=p_room,approved_at=v_now,paired_at=v_now,
         expires_at=v_now+interval '10 minutes',replaced_key=coalesce(p_replace,false)
   where code=v_code;
  delete from public.pin_login_throttle where client_id=v_fail_key;
  perform public.audit_event(v_site,'update','display',p_room::text,
    case when coalesce(p_replace,false) then 'TV 연결 코드 승인 (기존 기기 해제·인증 키 교체)' else 'TV 연결 코드 승인' end,
    null,jsonb_build_object('room',v_name,'replace',coalesce(p_replace,false)));
  return jsonb_build_object('ok',true,'room_name',v_name,'replaced',coalesce(p_replace,false));
end $$;

create or replace function public.hospital_reset_display_key(p_room uuid)
returns jsonb language plpgsql security definer set search_path=public as $$
declare v_site uuid; v_name text;
begin
  perform pg_advisory_xact_lock(hashtext('signage-pairing-v3'));
    select site_id,name into v_site,v_name from public.rooms where id=p_room for update;
  if v_site is null then return jsonb_build_object('ok',false,'error','room_not_found','message','디스플레이를 찾을 수 없습니다.'); end if;
  if not public.can_manage_site(v_site) then raise exception 'not allowed' using errcode='42501'; end if;
  update public.rooms set player_key=gen_random_uuid() where id=p_room;
  delete from public.player_pairing_codes where room_id=p_room;
  delete from public.display_pairing_owner where room_id=p_room;
  perform public.signage_reset_pairing_status(p_room);
  perform public.audit_event(v_site,'update','display',p_room::text,'기존 TV 기기 연결 해제 (인증 키 교체)',null,jsonb_build_object('room',v_name));
  return jsonb_build_object('ok',true,'room_name',v_name);
end $$;

create or replace function public.hospital_display_pairing_info(p_room uuid)
returns jsonb language plpgsql stable security definer set search_path=public as $$
declare v_site uuid; v_row record;
begin
  select site_id into v_site from public.rooms where id=p_room;
  if v_site is null or not public.can_manage_site(v_site) then raise exception 'not allowed' using errcode='42501'; end if;
  select status,approved_at,confirmed_at,expires_at,replaced_key into v_row
    from public.player_pairing_codes where room_id=p_room order by approved_at desc nulls last limit 1;
  return jsonb_build_object('has_owner',exists(select 1 from public.display_pairing_owner where room_id=p_room),'status',v_row.status,'approved_at',v_row.approved_at,'confirmed_at',v_row.confirmed_at,
                            'expires_at',v_row.expires_at,'replaced_key',v_row.replaced_key);
end $$;
create or replace function public.app_db_version()
returns jsonb language sql stable security definer set search_path=public as $$
  select jsonb_build_object('version','2.35.87','features',jsonb_build_array('pairing_v2','display_key_reset','pairing_v3'))
$$;
insert into public.schema_version(version,applied_at) values('2.35.87',clock_timestamp())
on conflict(version) do update set applied_at=excluded.applied_at;
notify pgrst,'reload schema';
commit;


-- Clinic Signage v2.36.0 | tenant-specific catalogs and onboarding
-- Existing TV keys, playlists, sessions and media are not changed. Run after 2.35.87.
begin;
select pg_advisory_xact_lock(23600);
do $$ begin
  if not exists(select 1 from public.schema_version where version='2.35.87') then
    raise exception '먼저 v2.35.86 및 v2.35.87 마이그레이션을 적용하세요.';
  end if;
  if to_regprocedure('public.app_db_version()') is null or to_regprocedure('public.can_manage_site(uuid)') is null or to_regprocedure('public.admin_create_site(text,text,text)') is null or to_regprocedure('public.admin_set_site_staff_pin(uuid,text)') is null or to_regprocedure('public.hospital_create_floor(uuid,smallint,text)') is null then
    raise exception '2.35.87 필수 DB 함수가 없습니다. 이전 마이그레이션을 확인하세요.';
  end if;
  if not coalesce((public.app_db_version()->'features') ? 'pairing_v3',false) then raise exception '2.35.87 연결 기능이 없습니다. 이전 마이그레이션을 확인하세요.'; end if;
end $$;
alter table public.sites add column if not exists catalog_config jsonb;
-- Retain existing choices and referenced codes, including historical custom values.
-- Only the existing branded site or a site with its own legacy references gets the legacy branded entry.
with refs as (
  select site_id,session_treatment as code from public.rooms where session_treatment is not null
  union select site_id,treatment from public.patient_sessions where treatment is not null
  union select site_id,unnest(target_treatment) from public.playlists where site_id is not null
  union select site_id,unnest(target_treatment) from public.videos where site_id is not null
), initial as (
  select s.id, '{"revision":1,"treatments":[{"code":"general","label":"일반 진료","active":true},{"code":"checkup","label":"검진","active":true},{"code":"aftercare","label":"치료 후 관리","active":true}],"floor_types":[{"code":"general","label":"일반진료","active":true},{"code":"common","label":"공용","active":true},{"code":"support","label":"지원","active":true},{"code":"other","label":"기타","active":true}],"space_types":[{"code":"treatment","label":"진료실","active":true},{"code":"consultation","label":"상담실","active":true},{"code":"waiting","label":"대기","active":true},{"code":"lounge","label":"라운지","active":true},{"code":"reception","label":"접수/안내","active":true},{"code":"lobby","label":"로비","active":true},{"code":"staff","label":"스탭","active":true},{"code":"support","label":"지원","active":true},{"code":"public","label":"공용","active":true},{"code":"other","label":"기타","active":true}],"logo":null}'::jsonb || jsonb_build_object(
    'treatments',coalesce((select jsonb_agg(x order by ord) from jsonb_array_elements('[{"code":"minish","label":"미니쉬","active":true},{"code":"implant","label":"임플란트","active":true},{"code":"whitening","label":"미백","active":true},{"code":"orthodontics","label":"교정","active":true},{"code":"checkup","label":"검진","active":true},{"code":"aftercare","label":"수술 후 관리","active":true},{"code":"general","label":"일반 진료","active":true}]'::jsonb) with ordinality a(x,ord)
      where x->>'code'<>'minish' or s.code='minish' or exists(select 1 from refs where site_id=s.id and code='minish')), '[]'::jsonb)
      || coalesce((select jsonb_agg(jsonb_build_object('code',q.code,'label',q.code,'active',true) order by q.code) from
          (select distinct code from refs where site_id=s.id and nullif(btrim(code),'') is not null and not exists(select 1 from jsonb_array_elements('[{"code":"minish","label":"미니쉬","active":true},{"code":"implant","label":"임플란트","active":true},{"code":"whitening","label":"미백","active":true},{"code":"orthodontics","label":"교정","active":true},{"code":"checkup","label":"검진","active":true},{"code":"aftercare","label":"수술 후 관리","active":true},{"code":"general","label":"일반 진료","active":true}]'::jsonb) a where a->>'code'=refs.code)) q),'[]'::jsonb),
    'floor_types',case when s.code='minish' or exists(select 1 from public.signage_groups g where g.site_id=s.id and g.care_type='minish') then '[{"code":"general","label":"일반진료","active":true},{"code":"minish","label":"MINISH","active":true},{"code":"common","label":"공용","active":true},{"code":"support","label":"지원","active":true},{"code":"other","label":"기타","active":true}]'::jsonb else '[{"code":"general","label":"일반진료","active":true},{"code":"common","label":"공용","active":true},{"code":"support","label":"지원","active":true},{"code":"other","label":"기타","active":true}]'::jsonb end
  ) as cfg from public.sites s where s.catalog_config is null
) update public.sites s set catalog_config=i.cfg from initial i where s.id=i.id;
alter table public.sites alter column catalog_config set default '{"revision":1,"treatments":[{"code":"general","label":"일반 진료","active":true},{"code":"checkup","label":"검진","active":true},{"code":"aftercare","label":"치료 후 관리","active":true}],"floor_types":[{"code":"general","label":"일반진료","active":true},{"code":"common","label":"공용","active":true},{"code":"support","label":"지원","active":true},{"code":"other","label":"기타","active":true}],"space_types":[{"code":"treatment","label":"진료실","active":true},{"code":"consultation","label":"상담실","active":true},{"code":"waiting","label":"대기","active":true},{"code":"lounge","label":"라운지","active":true},{"code":"reception","label":"접수/안내","active":true},{"code":"lobby","label":"로비","active":true},{"code":"staff","label":"스탭","active":true},{"code":"support","label":"지원","active":true},{"code":"public","label":"공용","active":true},{"code":"other","label":"기타","active":true}],"logo":null}'::jsonb;
alter table public.sites alter column catalog_config set not null;

-- Codes are stable identifiers: disabling a code retains historical labels and references.
create or replace function public.site_catalog_has_code(p_site uuid,p_kind text,p_code text,p_active boolean default false)
returns boolean language sql stable security definer set search_path=public as $$
  select coalesce(exists(select 1 from public.sites s cross join lateral jsonb_array_elements(s.catalog_config->p_kind) e
    where s.id=p_site and e->>'code'=p_code and (not p_active or e->'active'='true'::jsonb)),false)
$$;
revoke all on function public.site_catalog_has_code(uuid,text,text,boolean) from public,anon,authenticated;

create or replace function public.hospital_save_site_catalog(p_site uuid,p_revision integer,p_catalog jsonb)
returns jsonb language plpgsql security definer set search_path=public as $$
declare old_cfg jsonb; cfg jsonb; category text; item jsonb; old_item jsonb; arr jsonb; code text; label text; seen text[]; logo text; next_revision integer;
begin
  if not public.can_manage_site(p_site) then raise exception 'not allowed' using errcode='42501'; end if;
  select catalog_config into old_cfg from public.sites where id=p_site for update;
  if not found then raise exception '병원을 찾을 수 없습니다.'; end if;
  if p_revision is distinct from (old_cfg->>'revision')::integer then raise exception '다른 관리자가 설정을 변경했습니다. 새로고침 후 다시 시도하세요.' using errcode='40001'; end if;
  if jsonb_typeof(p_catalog) is distinct from 'object' or octet_length(p_catalog::text)>300000 then raise exception '설정 형식 또는 용량이 올바르지 않습니다.'; end if;
  cfg:='{}'::jsonb;
  foreach category in array array['treatments','floor_types','space_types'] loop
    if jsonb_typeof(p_catalog->category) is distinct from 'array' then raise exception '분류 목록이 올바르지 않습니다.'; end if;
    if jsonb_array_length(p_catalog->category)>150 then raise exception '분류는 최대 150개까지 등록할 수 있습니다.'; end if;
    arr:='[]'::jsonb; seen:='{}'::text[];
    for item in select value from jsonb_array_elements(p_catalog->category) loop
      code:=item->>'code'; label:=btrim(coalesce(item->>'label',''));
      if jsonb_typeof(item) is distinct from 'object' or jsonb_typeof(item->'code') is distinct from 'string' or jsonb_typeof(item->'label') is distinct from 'string' or code is null or code='' or code=any(seen) or jsonb_typeof(item->'active') is distinct from 'boolean' or label='' or length(label)>80 then raise exception '중복 또는 잘못된 분류 항목입니다.'; end if;
      if not exists(select 1 from jsonb_array_elements(old_cfg->category) e where e->>'code'=code) and (code !~ '^[a-z][a-z0-9_-]{0,47}$' or code='veneer') then raise exception '분류 식별자는 영문 소문자·숫자·하이픈·밑줄만 사용할 수 있습니다.'; end if;
      seen:=array_append(seen,code);
      arr:=arr||jsonb_build_array(jsonb_build_object('code',code,'label',label,'active',item->'active'));
    end loop;
    -- Never physically remove existing codes. Old media/session tags still resolve.
    for old_item in select value from jsonb_array_elements(old_cfg->category) loop
      if not (old_item->>'code'=any(seen)) then arr:=arr||jsonb_build_array(old_item||'{"active":false}'::jsonb); end if;
    end loop;
    if category in ('floor_types','space_types') and not exists(select 1 from jsonb_array_elements(arr) e where e->>'code'='other' and e->'active'='true'::jsonb) then raise exception '기타 분류는 항상 사용 가능해야 합니다.'; end if;
    if not exists(select 1 from jsonb_array_elements(arr) e where e->'active'='true'::jsonb) then raise exception '한 개 이상의 사용 중인 분류가 필요합니다.'; end if;
    if jsonb_array_length(arr)>150 then raise exception '보관 항목을 포함해 최대 150개입니다.'; end if;
    cfg:=jsonb_set(cfg,array[category],arr,true);
  end loop;
  logo:=nullif(p_catalog->>'logo','');
  if logo is not null and (length(logo)>68300 or logo !~ '^data:image/(png|jpeg|webp);base64,[A-Za-z0-9+/]+={0,2}$') then raise exception '로고는 50KB 이하 PNG/JPG/WebP 이미지여야 합니다.'; end if;
  next_revision:=(old_cfg->>'revision')::integer+1;
  cfg:=cfg||jsonb_build_object('revision',next_revision,'logo',logo);
  update public.sites set catalog_config=cfg,updated_at=clock_timestamp() where id=p_site;
  return cfg;
end $$;
revoke all on function public.hospital_save_site_catalog(uuid,integer,jsonb) from public,anon,authenticated;
grant execute on function public.hospital_save_site_catalog(uuid,integer,jsonb) to anon,authenticated;

-- Replace closed enums with site catalog validation. Other is the required default.
alter table public.signage_groups drop constraint if exists signage_groups_care_type_check;
alter table public.floor_spaces drop constraint if exists floor_spaces_space_type_check;
create or replace function public.enforce_site_catalog_type()
returns trigger language plpgsql security definer set search_path=public as $$
declare category text; code text;
begin
  if tg_table_name='signage_groups' then category:='floor_types'; code:=new.care_type;
  else category:='space_types'; code:=new.space_type; end if;
  -- Existing inactive codes may still be retained/restored, but a code from another hospital is invalid.
  if not public.site_catalog_has_code(new.site_id,category,code,false) then raise exception '이 병원에 등록되지 않은 분류입니다.' using errcode='23514'; end if;
  return new;
end $$;
revoke all on function public.enforce_site_catalog_type() from public,anon,authenticated;
drop trigger if exists signage_groups_site_catalog_guard on public.signage_groups;
create trigger signage_groups_site_catalog_guard before insert or update of site_id,care_type on public.signage_groups for each row execute function public.enforce_site_catalog_type();
drop trigger if exists floor_spaces_site_catalog_guard on public.floor_spaces;
create trigger floor_spaces_site_catalog_guard before insert or update of site_id,space_type on public.floor_spaces for each row execute function public.enforce_site_catalog_type();

create or replace function public.hospital_update_floor_meta(
  p_site uuid,
  p_group uuid,
  p_name text,
  p_care text default 'other',
  p_intro text default null,
  p_topics text[] default '{}',
  p_role text default null,
  p_purpose text default null,
  p_audience text default null,
  p_waiting text default null,
  p_reason text default null,
  p_playlist uuid default null
)
returns void
language plpgsql
security definer
set search_path=public
as $$
declare
  v_name text:=nullif(btrim(coalesce(p_name,'')),'');
  v_care text:=coalesce(nullif(btrim(p_care),''),'other');
begin
  if not public.can_manage_site(p_site) then raise exception 'not allowed'; end if;
  if v_name is null then raise exception '층 이름을 입력하세요'; end if;
  if not public.site_catalog_has_code(p_site,'floor_types',v_care,true) and not exists(select 1 from public.signage_groups where id=p_group and site_id=p_site and care_type=v_care) then raise exception '이 병원에서 사용 가능한 층 유형을 선택하세요.'; end if;
  if p_playlist is not null and not exists(
    select 1 from public.playlists p where p.id=p_playlist and p.active and (p.site_id is null or p.site_id=p_site)
  ) then raise exception '사용할 수 없는 플레이리스트입니다'; end if;

  update public.signage_groups g
  set name=v_name,
      care_type=v_care,
      content_intro=nullif(btrim(coalesce(p_intro,'')),''),
      content_topics=coalesce(p_topics,'{}'::text[]),
      role_label=nullif(btrim(coalesce(p_role,'')),''),
      signage_purpose=nullif(btrim(coalesce(p_purpose,'')),''),
      target_audience=nullif(btrim(coalesce(p_audience,'')),''),
      waiting_area_note=nullif(btrim(coalesce(p_waiting,'')),''),
      signage_reason=nullif(btrim(coalesce(p_reason,'')),''),
      default_playlist_id=p_playlist
  where g.id=p_group and g.site_id=p_site and g.kind='floor';
  if not found then raise exception '층 정보를 찾을 수 없습니다'; end if;
end $$;

create or replace function public.staff_quick_set_room(p_room uuid,p_treatment text,p_age_group text default null,p_gender text default null)
returns void language plpgsql security definer set search_path=public as $$
declare v_mode text; v_site uuid:=public.manageable_room_site(p_room);
begin
  if not public.is_member() or v_site is null or not public.staff_can_remote_control_room(p_room) then raise exception 'not allowed'; end if;
  if not public.site_catalog_has_code(v_site,'treatments',p_treatment,true) then raise exception '이 병원에서 사용 가능한 진료 항목을 선택하세요.'; end if;
  select room_mode into v_mode from public.rooms where id=p_room and site_id=v_site for update;
  if not found then raise exception '진료실을 찾을 수 없습니다'; end if;
  if v_mode not in ('treatment','consultation') then raise exception '맞춤 송출이 가능한 공간이 아닙니다'; end if;
  if exists(select 1 from public.patient_sessions where site_id=v_site and room_id=p_room and status in ('assigned','in_progress')) then raise exception '등록 환자가 배정된 진료실입니다. 환자 관리에서 변경하세요'; end if;
  update public.rooms set session_age_group=nullif(trim(coalesce(p_age_group,'')),''),session_gender=nullif(trim(coalesce(p_gender,'')),''),session_treatment=p_treatment,
    session_tags=array_remove(array[nullif(trim(coalesce(p_age_group,'')),''),nullif(trim(coalesce(p_gender,'')),''),p_treatment]::text[],null),session_started_at=clock_timestamp()
  where id=p_room and site_id=v_site;
end $$;

create or replace function public.staff_create_patient(p_label text,p_age_group text,p_gender text,p_treatment text)
returns uuid language plpgsql security definer set search_path=public as $$
declare v_id uuid; v_queue bigint; v_site uuid;
begin
  if not public.is_member() then raise exception 'not allowed'; end if;
  v_site:=coalesce(public.pin_session_site_id(),public.default_site_id());
  if v_site is null or not public.can_manage_site(v_site) then raise exception '병원을 지정하세요.'; end if;
  if not public.site_catalog_has_code(v_site,'treatments',p_treatment,true) then raise exception '이 병원에서 사용 가능한 진료 항목을 선택하세요.'; end if;
  insert into public.patient_sessions(site_id,label,age_group,gender,treatment)
  values(v_site,nullif(trim(coalesce(p_label,'')),''),nullif(trim(coalesce(p_age_group,'')),''),nullif(trim(coalesce(p_gender,'')),''),p_treatment)
  returning id,queue_no into v_id,v_queue;
  update public.patient_sessions set label=coalesce(label,'대기 '||lpad(v_queue::text,3,'0')) where id=v_id;
  return v_id;
end $$;

CREATE OR REPLACE FUNCTION public.admin_import_site_config(p_config jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_site uuid; g jsonb; r jsonb; sp jsonb; v_groups int:=0; v_rooms int:=0; v_spaces int:=0;
begin
  if not public.is_admin() then raise exception 'not allowed'; end if;
  v_site:=coalesce(nullif(p_config#>>'{site,id}','')::uuid,public.default_site_id());
  if not exists(select 1 from public.sites where id=v_site) then raise exception 'site not found'; end if;
  if jsonb_typeof(p_config#>'{site,catalog_config}')='object' then
    perform public.hospital_save_site_catalog(v_site,(select (catalog_config->>'revision')::integer from public.sites where id=v_site),p_config#>'{site,catalog_config}');
  end if;
  update public.sites set name=coalesce(nullif(p_config#>>'{site,name}',''),name),building_label=coalesce(nullif(p_config#>>'{site,building_label}',''),building_label),updated_at=clock_timestamp() where id=v_site;
  if jsonb_typeof(p_config->'settings')='object' then insert into public.site_settings(site_id,floorplan_assets,operating_config,updated_at) values(v_site,coalesce(p_config#>'{settings,floorplan_assets}','{}'::jsonb),coalesce(p_config#>'{settings,operating_config}','{}'::jsonb),clock_timestamp()) on conflict(site_id) do update set floorplan_assets=excluded.floorplan_assets,operating_config=excluded.operating_config,updated_at=clock_timestamp(); end if;
  if jsonb_typeof(p_config->'groups')='array' then for g in select * from jsonb_array_elements(p_config->'groups') loop update public.signage_groups set name=coalesce(nullif(g->>'name',''),name),kind=coalesce(nullif(g->>'kind',''),kind),floor_number=coalesce((g->>'floor_number')::smallint,floor_number),care_type=coalesce(nullif(g->>'care_type',''),care_type),signage_purpose=g->>'signage_purpose',target_audience=g->>'target_audience',waiting_area_note=g->>'waiting_area_note',signage_reason=g->>'signage_reason',content_intro=g->>'content_intro',content_topics=coalesce(array(select jsonb_array_elements_text(coalesce(g->'content_topics','[]'::jsonb))),'{}'::text[]),role_label=g->>'role_label',default_playlist_id=nullif(g->>'default_playlist_id','')::uuid,sort_order=coalesce((g->>'sort_order')::int,sort_order) where id=(g->>'id')::uuid and site_id=v_site; if found then v_groups:=v_groups+1; end if; end loop; end if;
  if jsonb_typeof(p_config->'rooms')='array' then for r in select * from jsonb_array_elements(p_config->'rooms') loop update public.rooms set name=coalesce(nullif(r->>'name',''),name),group_id=nullif(r->>'group_id','')::uuid,room_mode=coalesce(nullif(r->>'room_mode',''),room_mode),map_x_pct=nullif(r->>'map_x_pct','')::numeric,map_y_pct=nullif(r->>'map_y_pct','')::numeric,display_control_mode=coalesce(nullif(r->>'display_control_mode',''),display_control_mode),display_note=r->>'display_note' where id=(r->>'id')::uuid and site_id=v_site; if found then v_rooms:=v_rooms+1; end if; end loop; end if;
  if jsonb_typeof(p_config->'spaces')='array' then delete from public.floor_spaces where site_id=v_site; for sp in select * from jsonb_array_elements(p_config->'spaces') loop insert into public.floor_spaces(id,site_id,group_id,name,space_type,x_pct,y_pct,width_pct,height_pct,sort_order) values(coalesce(nullif(sp->>'id','')::uuid,gen_random_uuid()),v_site,nullif(sp->>'group_id','')::uuid,coalesce(nullif(sp->>'name',''),'공간'),coalesce(nullif(sp->>'space_type',''),'other'),coalesce((sp->>'x_pct')::numeric,0),coalesce((sp->>'y_pct')::numeric,0),coalesce((sp->>'width_pct')::numeric,10),coalesce((sp->>'height_pct')::numeric,10),coalesce((sp->>'sort_order')::int,0)); v_spaces:=v_spaces+1; end loop; end if;
  perform public.audit_event(v_site,'restore','site_config',v_site::text,'사이트 설정 백업 복원',null,jsonb_build_object('groups',v_groups,'rooms',v_rooms,'spaces',v_spaces));
  return jsonb_build_object('ok',true,'groups',v_groups,'rooms',v_rooms,'spaces',v_spaces);
end $function$;

-- One transaction: no partially-created hospital if PIN or optional floor setup fails.
create or replace function public.admin_onboard_site(p_name text,p_code text,p_pin text,p_building text default 'MAIN BUILDING',p_floors integer default 1)
returns jsonb language plpgsql security definer set search_path=public as $$
declare result jsonb; v_site uuid; n integer;
begin
  if not public.is_admin() then raise exception 'ADMIN_REQUIRED' using errcode='42501'; end if;
  if p_pin is null or p_pin !~ '^[0-9]{4,6}$' then raise exception '병원 관리자 PIN은 4~6자리 숫자여야 합니다.'; end if;
  if p_floors is null or p_floors<0 or p_floors>30 then raise exception '초기 층 수는 0~30이어야 합니다.'; end if;
  result:=public.admin_create_site(p_name,p_code,p_building);
  if result->>'ok'<>'true' or result->>'existing'='true' then return result; end if;
  v_site:=(result#>>'{site,id}')::uuid;
  perform public.admin_set_site_staff_pin(v_site,p_pin);
  for n in 1..p_floors loop perform public.hospital_create_floor(v_site,n::smallint,null); end loop;
  return result||jsonb_build_object('floor_count',p_floors);
end $$;
revoke all on function public.admin_onboard_site(text,text,text,text,integer) from public,anon,authenticated;
grant execute on function public.admin_onboard_site(text,text,text,text,integer) to anon,authenticated;

create or replace function public.app_db_version()
returns jsonb language sql stable security definer set search_path=public as $$
  select jsonb_build_object('version','2.36.0','features',jsonb_build_array('pairing_v2','display_key_reset','pairing_v3','site_catalog_v1'))
$$;
insert into public.schema_version(version,applied_at) values('2.36.0',clock_timestamp()) on conflict(version) do update set applied_at=excluded.applied_at;
notify pgrst,'reload schema';
commit;

-- ===== v2.36.1 video deletion =====
-- Preview and confirmed deletion. Existing R2 queue remains authoritative.
BEGIN;
DO $$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM public.schema_version WHERE version='2.36.0') THEN
  RAISE EXCEPTION '먼저 v2.36.0-site-catalog.sql을 실행하세요.';
 END IF;
END $$;
CREATE OR REPLACE FUNCTION public.video_delete_impact(p_video uuid,p_site uuid)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v public.videos%ROWTYPE; links jsonb; tvs jsonb;
BEGIN
 SELECT * INTO v FROM public.videos WHERE id=p_video;
 IF NOT FOUND THEN RAISE EXCEPTION '영상을 찾을 수 없습니다.'; END IF;
 IF NOT coalesce(public.is_admin(),false) AND (v.site_id IS NULL OR p_site IS DISTINCT FROM v.site_id OR NOT coalesce(public.can_manage_site(v.site_id),false)) THEN
  RAISE EXCEPTION '영상 삭제 권한이 없습니다.' USING ERRCODE='42501';
 END IF;
 IF v.site_id IS NOT NULL AND p_site IS DISTINCT FROM v.site_id THEN RAISE EXCEPTION '영상 소유 병원이 일치하지 않습니다.' USING ERRCODE='42501'; END IF;
 WITH refs(kind,id,site_id,label,remaining,detail) AS (
  SELECT 'playlist',p.id::text,p.site_id,p.name,(SELECT count(*) FROM public.playlist_items i WHERE i.playlist_id=p.id AND i.video_id<>p_video),jsonb_build_object('active',p.active,'kind',p.kind) FROM public.playlists p JOIN public.playlist_items i ON i.playlist_id=p.id WHERE i.video_id=p_video
  UNION ALL SELECT 'rule',r.id::text,r.site_id,concat_ws(' / ',g.name,r.name),NULL::bigint,jsonb_build_object('enabled',rr.enabled,'starts_at',rr.starts_at,'ends_at',rr.ends_at) FROM public.room_video_rules rr JOIN public.rooms r ON r.id=rr.room_id LEFT JOIN public.signage_groups g ON g.id=r.group_id WHERE rr.video_id=p_video
  UNION ALL SELECT 'manual',r.id::text,r.site_id,concat_ws(' / ',g.name,r.name),cardinality(array_remove(r.manual_video_ids,p_video)),jsonb_build_object('active',r.manual_active,'ids',r.manual_video_ids) FROM public.rooms r LEFT JOIN public.signage_groups g ON g.id=r.group_id WHERE p_video=ANY(r.manual_video_ids)
  UNION ALL SELECT 'site',b.site_id::text,b.site_id,'병원 전체 송출',cardinality(array_remove(b.video_ids,p_video)),jsonb_build_object('active',b.active,'ids',b.video_ids) FROM public.site_broadcasts b WHERE p_video=ANY(b.video_ids)
  UNION ALL SELECT 'group',g.id::text,g.site_id,g.name,cardinality(array_remove(b.video_ids,p_video)),jsonb_build_object('active',b.active,'ids',b.video_ids) FROM public.group_broadcasts b JOIN public.signage_groups g ON g.id=b.group_id WHERE p_video=ANY(b.video_ids)
  UNION ALL SELECT 'schedule',b.id::text,b.site_id,concat_ws(' / ',coalesce(g.name,'병원 전체'),to_char(b.starts_at AT TIME ZONE 'Asia/Seoul','YYYY-MM-DD HH24:MI')),cardinality(array_remove(b.video_ids,p_video)),jsonb_build_object('enabled',b.enabled,'starts_at',b.starts_at,'ends_at',b.ends_at,'ids',b.video_ids,'group_id',b.group_id) FROM public.broadcast_schedules b LEFT JOIN public.signage_groups g ON g.id=b.group_id WHERE p_video=ANY(b.video_ids)
  UNION ALL SELECT 'emergency_site',s.site_id::text,s.site_id,'병원 긴급 영상',0,'{}'::jsonb FROM public.site_settings s WHERE s.operating_config->>'emergency_video_id'=p_video::text
  UNION ALL SELECT 'emergency_global',a.id::text,NULL::uuid,'전체 긴급 영상',0,'{}'::jsonb FROM public.app_settings a WHERE a.emergency_video_id=p_video
  UNION ALL SELECT 'legacy',b.id::text,NULL::uuid,'기존 공통 송출',cardinality(array_remove(b.video_ids,p_video)),jsonb_build_object('active',b.active,'ids',b.video_ids) FROM public.broadcast b WHERE p_video=ANY(b.video_ids)
 ) SELECT coalesce(jsonb_agg(jsonb_build_object('kind',q.kind,'id',q.id,'site_id',q.site_id,'site',coalesce(s.name,'전체/공용'),'label',q.label,'remaining',q.remaining,'detail',q.detail) ORDER BY q.kind,q.id),'[]'::jsonb) INTO links FROM refs q LEFT JOIN public.sites s ON s.id=q.site_id;
 -- Never disclose another hospital's references to a hospital account.
 IF NOT coalesce(public.is_admin(),false) AND EXISTS(SELECT 1 FROM jsonb_array_elements(links) l WHERE l->>'site_id' IS DISTINCT FROM p_site::text) THEN
  RAISE EXCEPTION '병원 범위 밖의 연결이 있습니다. 슈퍼어드민에게 삭제를 요청하세요.' USING ERRCODE='42501';
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',r.id,'site',s.name,'label',concat_ws(' / ',g.name,r.name)) ORDER BY r.id),'[]'::jsonb) INTO tvs
 FROM public.rooms r JOIN public.sites s ON s.id=r.site_id LEFT JOIN public.signage_groups g ON g.id=r.group_id
 WHERE (coalesce(public.is_admin(),false) OR r.site_id=p_site) AND EXISTS(SELECT 1 FROM jsonb_array_elements(links) l WHERE
  (l->>'kind'='playlist' AND coalesce(r.default_playlist_id,g.default_playlist_id)::text=l->>'id') OR
  (l->>'kind' IN ('rule','manual') AND r.id::text=l->>'id') OR
  (l->>'kind' IN ('site','emergency_site') AND r.site_id::text=l->>'site_id') OR
  (l->>'kind'='group' AND r.group_id::text=l->>'id') OR
  (l->>'kind'='schedule' AND r.site_id::text=l->>'site_id' AND ((l->'detail'->>'group_id') IS NULL OR r.group_id::text=l->'detail'->>'group_id')) OR
  l->>'kind' IN ('emergency_global','legacy'));
 RETURN jsonb_build_object('title',v.title,'links',links,'tvs',tvs,'count',jsonb_array_length(links),'signature',md5(jsonb_build_array(p_video,v.site_id,v.title,links,tvs)::text));
END $$;
CREATE OR REPLACE FUNCTION public.video_delete_confirmed(p_video uuid,p_site uuid,p_signature text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE impact jsonb;
BEGIN
 -- Authorize before taking locks. Keep existing queue semantics on retries.
 IF EXISTS(SELECT 1 FROM public.video_r2_delete_jobs WHERE video_id=p_video) THEN RETURN public.video_delete_enqueue(p_video,p_site); END IF;
 PERFORM public.video_delete_impact(p_video,p_site);
 -- Lock references against concurrent writes while rechecking the preview and deleting.
 PERFORM set_config('lock_timeout','3000',true);
 LOCK TABLE public.app_settings,public.broadcast,public.broadcast_schedules,public.group_broadcasts,public.playlist_items,public.playlists,public.room_video_rules,public.rooms,public.signage_groups,public.site_broadcasts,public.site_settings,public.sites,public.videos IN SHARE ROW EXCLUSIVE MODE;
 impact:=public.video_delete_impact(p_video,p_site);
 IF p_signature IS NULL OR p_signature IS DISTINCT FROM impact->>'signature' THEN RAISE EXCEPTION '사용 위치가 변경되었습니다. 다시 확인 후 삭제하세요.'; END IF;
 DELETE FROM public.playlist_items WHERE video_id=p_video;
 DELETE FROM public.room_video_rules WHERE video_id=p_video;
 UPDATE public.rooms SET manual_video_ids=array_remove(manual_video_ids,p_video),manual_active=manual_active AND cardinality(array_remove(manual_video_ids,p_video))>0,manual_updated_at=clock_timestamp() WHERE p_video=ANY(manual_video_ids);
 UPDATE public.site_broadcasts SET video_ids=array_remove(video_ids,p_video),active=active AND cardinality(array_remove(video_ids,p_video))>0,revision=revision+1,updated_at=clock_timestamp() WHERE p_video=ANY(video_ids);
 UPDATE public.group_broadcasts SET video_ids=array_remove(video_ids,p_video),active=active AND cardinality(array_remove(video_ids,p_video))>0,revision=revision+1,updated_at=clock_timestamp() WHERE p_video=ANY(video_ids);
 UPDATE public.broadcast_schedules SET video_ids=array_remove(video_ids,p_video),enabled=enabled AND cardinality(array_remove(video_ids,p_video))>0 WHERE p_video=ANY(video_ids);
 UPDATE public.site_settings SET operating_config=operating_config-'emergency_video_id',updated_at=clock_timestamp() WHERE operating_config->>'emergency_video_id'=p_video::text;
 UPDATE public.app_settings SET emergency_video_id=NULL,updated_at=clock_timestamp() WHERE emergency_video_id=p_video;
 UPDATE public.broadcast SET video_ids=array_remove(video_ids,p_video),active=active AND cardinality(array_remove(video_ids,p_video))>0,revision=revision+1,updated_at=clock_timestamp() WHERE p_video=ANY(video_ids);
 -- Existing authorization, key safety and shared-file checks still run; any failure rolls back all changes.
 RETURN public.video_delete_enqueue(p_video,p_site);
END $$;
REVOKE ALL ON FUNCTION public.video_delete_impact(uuid,uuid),public.video_delete_confirmed(uuid,uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.video_delete_impact(uuid,uuid),public.video_delete_confirmed(uuid,uuid,text) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.video_usage_counts(p_site uuid,p_ids uuid[])
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE result jsonb;
BEGIN
 IF p_site IS NULL OR NOT coalesce(public.can_manage_site(p_site),false) THEN RAISE EXCEPTION '병원 관리 권한이 없습니다.' USING ERRCODE='42501'; END IF;
 IF coalesce(cardinality(p_ids),0)>1000 THEN RAISE EXCEPTION '조회는 최대 1000개씩 가능합니다.'; END IF;
 WITH allowed AS (
  SELECT id FROM public.videos WHERE id=ANY(p_ids) AND (site_id=p_site OR (site_id IS NULL AND public.is_admin()))
 ), refs AS (
  SELECT i.video_id,p.site_id FROM public.playlist_items i JOIN public.playlists p ON p.id=i.playlist_id WHERE i.video_id=ANY(p_ids)
  UNION ALL SELECT i.video_id,r.site_id FROM public.room_video_rules i JOIN public.rooms r ON r.id=i.room_id WHERE i.video_id=ANY(p_ids)
  UNION ALL SELECT x.id,r.site_id FROM public.rooms r CROSS JOIN LATERAL (SELECT DISTINCT unnest(r.manual_video_ids) id) x WHERE x.id=ANY(p_ids)
  UNION ALL SELECT x.id,r.site_id FROM public.site_broadcasts r CROSS JOIN LATERAL (SELECT DISTINCT unnest(r.video_ids) id) x WHERE x.id=ANY(p_ids)
  UNION ALL SELECT x.id,g.site_id FROM public.group_broadcasts r JOIN public.signage_groups g ON g.id=r.group_id CROSS JOIN LATERAL (SELECT DISTINCT unnest(r.video_ids) id) x WHERE x.id=ANY(p_ids)
  UNION ALL SELECT x.id,r.site_id FROM public.broadcast_schedules r CROSS JOIN LATERAL (SELECT DISTINCT unnest(r.video_ids) id) x WHERE x.id=ANY(p_ids)
  UNION ALL SELECT a.id,s.site_id FROM public.site_settings s JOIN allowed a ON s.operating_config->>'emergency_video_id'=a.id::text
  UNION ALL SELECT emergency_video_id,NULL::uuid FROM public.app_settings WHERE emergency_video_id=ANY(p_ids)
  UNION ALL SELECT x.id,NULL::uuid FROM public.broadcast r CROSS JOIN LATERAL (SELECT DISTINCT unnest(r.video_ids) id) x WHERE x.id=ANY(p_ids)
 ), counts AS (SELECT a.id,count(r.video_id) AS n FROM allowed a LEFT JOIN refs r ON r.video_id=a.id GROUP BY a.id HAVING coalesce(public.is_admin(),false) OR count(*) FILTER (WHERE r.video_id IS NOT NULL AND r.site_id IS DISTINCT FROM p_site)=0)
 SELECT coalesce(jsonb_object_agg(id::text,n),'{}'::jsonb) INTO result FROM counts;
 RETURN result;
END $$;
CREATE OR REPLACE FUNCTION public.video_delete_batch_confirmed(p_site uuid,p_items jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE item jsonb; vid uuid; impact jsonb; jobs jsonb:='[]'::jsonb;
BEGIN
 IF jsonb_typeof(p_items) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION '삭제 대상을 선택하세요.'; END IF;
 IF jsonb_array_length(p_items) NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION '영상은 1~10개씩 삭제하세요.'; END IF;
 IF (SELECT count(DISTINCT (e->>'videoId')::uuid) FROM jsonb_array_elements(p_items) e)<>jsonb_array_length(p_items) THEN RAISE EXCEPTION '중복되거나 잘못된 영상입니다.'; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
  PERFORM public.video_delete_impact((item->>'videoId')::uuid,p_site);
 END LOOP;
 PERFORM set_config('lock_timeout','3000',true);
 LOCK TABLE public.app_settings,public.broadcast,public.broadcast_schedules,public.group_broadcasts,public.playlist_items,public.playlists,public.room_video_rules,public.rooms,public.signage_groups,public.site_broadcasts,public.site_settings,public.sites,public.videos IN SHARE ROW EXCLUSIVE MODE;
 -- Check every original preview BEFORE modifying any reference. Shared playlists change during a batch.
 FOR item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
  impact:=public.video_delete_impact((item->>'videoId')::uuid,p_site);
  IF item->>'signature' IS NULL OR (item->>'signature') IS DISTINCT FROM (impact->>'signature') THEN RAISE EXCEPTION '사용 위치가 변경되었습니다. 다시 확인 후 삭제하세요.'; END IF;
 END LOOP;
 FOR item IN SELECT value FROM jsonb_array_elements(p_items) LOOP
  vid:=(item->>'videoId')::uuid;
  impact:=public.video_delete_impact(vid,p_site);
  jobs:=jobs||jsonb_build_array(public.video_delete_confirmed(vid,p_site,impact->>'signature'));
 END LOOP;
 RETURN jobs;
END $$;
REVOKE ALL ON FUNCTION public.video_usage_counts(uuid,uuid[]),public.video_delete_batch_confirmed(uuid,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.video_usage_counts(uuid,uuid[]),public.video_delete_batch_confirmed(uuid,jsonb) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.video_delete_pending(p_site uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
BEGIN
 IF NOT public.is_admin() AND (p_site IS NULL OR NOT public.can_manage_site(p_site)) THEN
  RAISE EXCEPTION '접근 권한이 없습니다.' USING ERRCODE='42501';
 END IF;
 RETURN COALESCE((SELECT jsonb_agg(jsonb_build_object('video_id',video_id,'object_key',object_key,'site_id',site_id))
  FROM (SELECT video_id,object_key,site_id FROM public.video_r2_delete_jobs
   WHERE status='pending' AND (site_id=p_site OR (public.is_admin() AND (p_site IS NULL OR site_id IS NULL)))
   ORDER BY created_at LIMIT 20) jobs),'[]'::jsonb);
END $$;
CREATE OR REPLACE FUNCTION public.app_db_version()
RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
 SELECT jsonb_build_object('version','2.36.1','features',jsonb_build_array('pairing_v2','display_key_reset','pairing_v3','site_catalog_v1','video_delete_impact_v1'))
$$;
INSERT INTO public.schema_version(version,applied_at) VALUES('2.36.1',clock_timestamp()) ON CONFLICT(version) DO UPDATE SET applied_at=excluded.applied_at;
NOTIFY pgrst,'reload schema';
COMMIT;
BEGIN;
DO $$ BEGIN
 IF NOT EXISTS (SELECT 1 FROM public.schema_version WHERE version='2.36.1') THEN RAISE EXCEPTION 'Apply v2.36.1-video-delete-impact.sql first'; END IF;
END $$;
CREATE OR REPLACE FUNCTION public.hospital_reload_selected_players(p_site uuid,p_rooms uuid[])
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE v_count integer;
BEGIN
 IF NOT public.can_manage_site(p_site) THEN RAISE EXCEPTION 'not allowed' USING ERRCODE='42501'; END IF;
 WITH changed AS (
 UPDATE public.rooms r SET reload_nonce=CASE WHEN r.reload_nonce>=2147483646 THEN 1 ELSE r.reload_nonce+1 END
 WHERE r.site_id=p_site AND r.id=ANY(p_rooms) AND coalesce(r.display_control_mode,'remote') IN ('remote','hybrid') RETURNING r.id,r.site_id
 ) INSERT INTO public.player_control_signals(room_id,site_id,revision,updated_at)
 SELECT id,site_id,1,clock_timestamp() FROM changed
 ON CONFLICT(room_id) DO UPDATE SET site_id=excluded.site_id,revision=public.player_control_signals.revision+1,updated_at=excluded.updated_at;
 GET DIAGNOSTICS v_count=ROW_COUNT;
 RETURN v_count;
END $$;
CREATE OR REPLACE FUNCTION public.hospital_save_space_geometry(p_site uuid,p_space uuid,p_before jsonb,p_patch jsonb)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE old_space public.floor_spaces%ROWTYPE; new_space public.floor_spaces%ROWTYPE; dx numeric; dy numeric; moved jsonb;
BEGIN
 IF NOT public.can_manage_site(p_site) THEN RAISE EXCEPTION 'not allowed' USING ERRCODE='42501'; END IF;
 SELECT * INTO STRICT old_space FROM public.floor_spaces WHERE id=p_space AND site_id=p_site FOR UPDATE;
 IF ROW(old_space.x_pct,old_space.y_pct,old_space.width_pct,old_space.height_pct) IS DISTINCT FROM ROW((p_before->>'x_pct')::numeric,(p_before->>'y_pct')::numeric,(p_before->>'width_pct')::numeric,(p_before->>'height_pct')::numeric) THEN RAISE EXCEPTION '공간이 다른 관리자에 의해 변경되었습니다. 취소 후 새로고침하세요.'; END IF;
 UPDATE public.floor_spaces SET x_pct=coalesce((p_patch->>'x_pct')::numeric,x_pct),y_pct=coalesce((p_patch->>'y_pct')::numeric,y_pct),width_pct=coalesce((p_patch->>'width_pct')::numeric,width_pct),height_pct=coalesce((p_patch->>'height_pct')::numeric,height_pct),name=coalesce(nullif(trim(p_patch->>'name'),''),name),space_type=coalesce(p_patch->>'space_type',space_type) WHERE id=p_space AND site_id=p_site RETURNING * INTO new_space;
 dx:=new_space.x_pct-old_space.x_pct; dy:=new_space.y_pct-old_space.y_pct;
 PERFORM 1 FROM public.rooms WHERE site_id=p_site AND floor_space_id=p_space FOR UPDATE;
 IF EXISTS(SELECT 1 FROM public.rooms WHERE site_id=p_site AND floor_space_id=p_space AND map_x_pct IS NOT NULL AND map_y_pct IS NOT NULL AND (map_x_pct+dx NOT BETWEEN new_space.x_pct AND new_space.x_pct+new_space.width_pct OR map_y_pct+dy NOT BETWEEN new_space.y_pct AND new_space.y_pct+new_space.height_pct)) THEN RAISE EXCEPTION '연결된 TV가 새 공간 영역을 벗어납니다. TV 위치 또는 공간 크기를 조정하세요.'; END IF;
 WITH changed AS (UPDATE public.rooms SET map_x_pct=map_x_pct+dx,map_y_pct=map_y_pct+dy WHERE site_id=p_site AND floor_space_id=p_space AND map_x_pct IS NOT NULL AND map_y_pct IS NOT NULL RETURNING id,map_x_pct,map_y_pct)
 SELECT coalesce(jsonb_agg(to_jsonb(changed)),'[]'::jsonb) INTO moved FROM changed;
 RETURN jsonb_build_object('space',to_jsonb(new_space),'rooms',moved);
END $$;
CREATE OR REPLACE FUNCTION public.hospital_create_placed_displays(p_site uuid,p_space uuid,p_names text[])
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE sp public.floor_spaces%ROWTYPE; nm text; rid uuid; created public.rooms%ROWTYPE; result jsonb:='[]'::jsonb; n integer; i integer:=0;
BEGIN
 IF NOT public.can_manage_site(p_site) THEN RAISE EXCEPTION 'not allowed' USING ERRCODE='42501'; END IF;
 n:=coalesce(cardinality(p_names),0); IF n<1 OR n>6 THEN RAISE EXCEPTION 'TV count must be 1–6'; END IF;
 SELECT * INTO STRICT sp FROM public.floor_spaces WHERE id=p_space AND site_id=p_site FOR UPDATE;
 PERFORM 1 FROM public.signage_groups WHERE id=sp.group_id AND site_id=p_site AND kind='floor' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'invalid floor'; END IF;
 FOREACH nm IN ARRAY p_names LOOP
  IF nullif(trim(nm),'') IS NULL OR length(trim(nm))>40 THEN RAISE EXCEPTION 'TV 이름은 1~40자여야 합니다.'; END IF;
  IF EXISTS(SELECT 1 FROM public.rooms WHERE site_id=p_site AND group_id=sp.group_id AND lower(trim(name))=lower(trim(nm))) THEN RAISE EXCEPTION '같은 층에 같은 이름의 TV가 있습니다.'; END IF;
  i:=i+1;
  rid:=public.hospital_create_display(p_site,sp.group_id,trim(nm),'remote');
  UPDATE public.rooms SET floor_space_id=sp.id,map_x_pct=round(sp.x_pct+sp.width_pct*i/(n+1),2),map_y_pct=round(sp.y_pct+sp.height_pct/2,2) WHERE id=rid AND site_id=p_site RETURNING * INTO STRICT created;
  result:=result||jsonb_build_array(jsonb_build_object('id',created.id,'site_id',created.site_id,'group_id',created.group_id,'name',created.name,'sort_order',created.sort_order,'floor_space_id',created.floor_space_id,'map_x_pct',created.map_x_pct,'map_y_pct',created.map_y_pct,'display_control_mode',created.display_control_mode,'manual_check_status',created.manual_check_status));
 END LOOP;
 RETURN result;
END $$;
CREATE OR REPLACE FUNCTION public.hospital_create_space_with_displays(p_site uuid,p_group uuid,p_name text,p_type text,p_x numeric,p_y numeric,p_width numeric,p_height numeric,p_count integer)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE sp public.floor_spaces%ROWTYPE; names text[]; result jsonb:='[]'::jsonb;
BEGIN
 IF NOT public.can_manage_site(p_site) THEN RAISE EXCEPTION 'not allowed' USING ERRCODE='42501'; END IF;
 IF p_count IS NULL OR p_count NOT BETWEEN 0 AND 6 OR nullif(trim(p_name),'') IS NULL OR length(trim(p_name))>40 THEN RAISE EXCEPTION 'invalid space or TV count'; END IF;
 PERFORM 1 FROM public.signage_groups WHERE id=p_group AND site_id=p_site AND kind='floor' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'invalid floor'; END IF;
 INSERT INTO public.floor_spaces(site_id,group_id,name,space_type,x_pct,y_pct,width_pct,height_pct,sort_order) VALUES(p_site,p_group,trim(p_name),p_type,p_x,p_y,p_width,p_height,(SELECT coalesce(max(sort_order),0)+10 FROM public.floor_spaces WHERE site_id=p_site AND group_id=p_group)) RETURNING * INTO sp;
 IF p_count>0 THEN
  SELECT array_agg(left(trim(p_name),34)||' TV'||CASE WHEN p_count>1 THEN ' '||i::text ELSE '' END ORDER BY i) INTO names FROM generate_series(1,p_count) i;
  result:=public.hospital_create_placed_displays(p_site,sp.id,names);
 END IF;
 RETURN jsonb_build_object('space',to_jsonb(sp),'rooms',result);
END $$;
REVOKE ALL ON FUNCTION public.hospital_reload_selected_players(uuid,uuid[]),public.hospital_save_space_geometry(uuid,uuid,jsonb,jsonb),public.hospital_create_placed_displays(uuid,uuid,text[]),public.hospital_create_space_with_displays(uuid,uuid,text,text,numeric,numeric,numeric,numeric,integer) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.hospital_reload_selected_players(uuid,uuid[]),public.hospital_save_space_geometry(uuid,uuid,jsonb,jsonb),public.hospital_create_placed_displays(uuid,uuid,text[]),public.hospital_create_space_with_displays(uuid,uuid,text,text,numeric,numeric,numeric,numeric,integer) TO anon,authenticated;
