 SELECT jsonb_build_object('version','2.36.7','features',jsonb_build_array('pairing_v2','display_key_reset','pairing_v3','site_catalog_v1','video_delete_impact_v1','layout_atomic_v1','selected_reload_v1','security_v1'))
$$;
